function storedGalaxyMotionMode() {
  try {
    return normalizeGalaxyMotionMode(localStorage.getItem(GALAXY_MOTION_MODE_STORAGE_KEY));
  } catch {
    return "auto";
  }
}

function persistGalaxyMotionMode(mode) {
  const normalized = normalizeGalaxyMotionMode(mode);
  try { localStorage.setItem(GALAXY_MOTION_MODE_STORAGE_KEY, normalized); } catch { /* 浏览器禁用存储时仅保留本次选择 */ }
  return normalized;
}

function normalizePageSize(value, fallback = 30) {
  const candidate = Number(value);
  return Number.isInteger(candidate) && candidate >= 10 && candidate <= 100 ? candidate : fallback;
}

function normalizePageSizes(value) {
  return Object.fromEntries(Object.entries(defaultPageSizes).map(([module, fallback]) => [
    module,
    normalizePageSize(value?.[module], fallback)
  ]));
}

function isAvailableConfiguredModel(model) {
  return Boolean(model?.enabled)
    && model?.providerStatus === "enabled"
    && model?.providerConnectionStatus === "success";
}

function isSelectableModel(model) {
  return (model?.modelKind ?? "chat") === "chat" && isAvailableConfiguredModel(model);
}

