function hasCompletedOnboarding() {
  return state.user?.onboardingCompleted === true;
}

function isMobileViewport() {
  return window.matchMedia("(max-width: 850px)").matches;
}

function persistOnboardingCompletion() {
  if (!state.user || state.user.onboardingCompleted) return;
  state.user = { ...state.user, onboardingCompleted: true };
  api("/api/auth/onboarding/complete", { method: "POST", body: {} })
    .then((user) => { state.user = user; })
    .catch(() => { state.user = { ...state.user, onboardingCompleted: false }; });
}

function isOnboardingTargetVisible(target) {
  if (!target) return false;
  const style = window.getComputedStyle(target);
  const rect = target.getBoundingClientRect();
  return style.display !== "none" && style.visibility !== "hidden" && Number(style.opacity) !== 0
    && rect.width > 0 && rect.height > 0 && rect.right > 0 && rect.bottom > 0
    && rect.left < window.innerWidth && rect.top < window.innerHeight;
}

function currentOnboardingSteps() {
  const candidates = $("#app").classList.contains("shelf-mode") ? shelfOnboardingSteps : workspaceOnboardingSteps;
  return candidates.filter((step) => isOnboardingTargetVisible(document.querySelector(step.selector)));
}

function onboardingPlacementCoordinates(placement, targetRect, popoverRect, gap) {
  if (placement === "right") return { left: targetRect.right + gap, top: targetRect.top + (targetRect.height - popoverRect.height) / 2 };
  if (placement === "left") return { left: targetRect.left - popoverRect.width - gap, top: targetRect.top + (targetRect.height - popoverRect.height) / 2 };
  if (placement === "top") return { left: targetRect.left + (targetRect.width - popoverRect.width) / 2, top: targetRect.top - popoverRect.height - gap };
  return { left: targetRect.left + (targetRect.width - popoverRect.width) / 2, top: targetRect.bottom + gap };
}

function onboardingPlacementFits(placement, targetRect, popoverRect, gap, margin) {
  if (placement === "right") return targetRect.right + gap + popoverRect.width <= window.innerWidth - margin;
  if (placement === "left") return targetRect.left - gap - popoverRect.width >= margin;
  if (placement === "top") return targetRect.top - gap - popoverRect.height >= margin;
  return targetRect.bottom + gap + popoverRect.height <= window.innerHeight - margin;
}

function positionOnboardingElements() {
  onboardingPositionFrame = null;
  const dialog = $("#onboarding-dialog");
  const step = onboardingSteps[onboardingStep];
  if (!dialog.open || !step) return;
  const target = document.querySelector(step.selector);
  if (!isOnboardingTargetVisible(target)) return;
  const padding = 7;
  const targetBox = target.getBoundingClientRect();
  const targetRect = {
    left: Math.max(0, targetBox.left - padding),
    top: Math.max(0, targetBox.top - padding),
    right: Math.min(window.innerWidth, targetBox.right + padding),
    bottom: Math.min(window.innerHeight, targetBox.bottom + padding)
  };
  targetRect.width = targetRect.right - targetRect.left;
  targetRect.height = targetRect.bottom - targetRect.top;
  const spotlight = $("#onboarding-spotlight");
  spotlight.style.left = `${targetRect.left}px`;
  spotlight.style.top = `${targetRect.top}px`;
  spotlight.style.width = `${targetRect.width}px`;
  spotlight.style.height = `${targetRect.height}px`;

  const popover = $("#onboarding-popover");
  popover.style.visibility = "hidden";
  popover.style.left = "0px";
  popover.style.top = "0px";
  const popoverRect = popover.getBoundingClientRect();
  const gap = 18;
  const margin = 14;
  const placements = [step.placement, "right", "left", "bottom", "top"].filter((placement, index, values) => values.indexOf(placement) === index);
  const placement = placements.find((candidate) => onboardingPlacementFits(candidate, targetRect, popoverRect, gap, margin)) ?? step.placement;
  const coordinates = onboardingPlacementCoordinates(placement, targetRect, popoverRect, gap);
  const left = Math.max(margin, Math.min(window.innerWidth - popoverRect.width - margin, coordinates.left));
  const top = Math.max(margin, Math.min(window.innerHeight - popoverRect.height - margin, coordinates.top));
  const arrowOffset = placement === "left" || placement === "right"
    ? targetRect.top + targetRect.height / 2 - top
    : targetRect.left + targetRect.width / 2 - left;
  const maximumArrowOffset = (placement === "left" || placement === "right" ? popoverRect.height : popoverRect.width) - 26;
  popover.dataset.placement = placement;
  popover.style.setProperty("--onboarding-arrow-offset", `${Math.max(26, Math.min(maximumArrowOffset, arrowOffset))}px`);
  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
  popover.style.visibility = "visible";
}

function scheduleOnboardingPosition() {
  if (!$("#onboarding-dialog").open) return;
  if (onboardingPositionFrame !== null) return;
  onboardingPositionFrame = window.requestAnimationFrame(positionOnboardingElements);
}

function refreshOnboardingForViewport() {
  const dialog = $("#onboarding-dialog");
  if (!dialog.open) return;
  if (onboardingPositionFrame !== null) window.cancelAnimationFrame(onboardingPositionFrame);
  onboardingPositionFrame = window.requestAnimationFrame(() => {
    onboardingPositionFrame = null;
    const currentSelector = onboardingSteps[onboardingStep]?.selector;
    const refreshedSteps = currentOnboardingSteps();
    if (!refreshedSteps.length) return;
    onboardingSteps = refreshedSteps;
    const preservedStep = onboardingSteps.findIndex((step) => step.selector === currentSelector);
    renderOnboardingStep(preservedStep >= 0 ? preservedStep : 0);
  });
}

function renderOnboardingStep(step, focusTitle = false) {
  const lastStep = Math.max(0, onboardingSteps.length - 1);
  onboardingStep = Math.max(0, Math.min(lastStep, Number(step) || 0));
  const current = onboardingSteps[onboardingStep];
  if (!current) return;
  $("#onboarding-progress").textContent = `第 ${onboardingStep + 1} 步，共 ${onboardingSteps.length} 步`;
  $("#onboarding-eyebrow").textContent = current.eyebrow;
  $("#onboarding-dialog-title").textContent = current.title;
  $("#onboarding-dialog-description").textContent = current.description;
  $("#onboarding-previous").disabled = onboardingStep === 0;
  $("#onboarding-next").textContent = onboardingStep === lastStep ? "完成导览" : "下一步";
  $("#onboarding-dialog").dataset.step = String(onboardingStep + 1);
  $("#onboarding-dialog").dataset.target = current.selector;
  document.querySelector(current.selector)?.scrollIntoView({ block: "nearest", inline: "nearest" });
  scheduleOnboardingPosition();
  if (focusTitle) $("#onboarding-dialog-title").focus();
}

function openOnboarding(force = false) {
  if (isMobileViewport()) return;
  const dialog = $("#onboarding-dialog");
  if (!force && hasCompletedOnboarding()) return;
  onboardingSteps = currentOnboardingSteps();
  if (!onboardingSteps.length) return;
  onboardingStep = 0;
  if (!dialog.open) dialog.showModal();
  renderOnboardingStep(0);
  window.requestAnimationFrame(() => $("#onboarding-dialog-title").focus());
}

function completeOnboarding() {
  persistOnboardingCompletion();
  if (onboardingPositionFrame !== null) window.cancelAnimationFrame(onboardingPositionFrame);
  onboardingPositionFrame = null;
  if ($("#onboarding-dialog").open) $("#onboarding-dialog").close();
}

function scheduleFirstUseOnboarding() {
  if (isMobileViewport() || onboardingAutoScheduled || hasCompletedOnboarding()) return;
  onboardingAutoScheduled = true;
  window.requestAnimationFrame(() => {
    onboardingAutoScheduled = false;
    if (state.user && !document.body.classList.contains("auth-pending")) openOnboarding();
  });
}

function settingsRouteContext() {
  const context = settingsReturnContext ?? {};
  return {
    returnView: context.view,
    returnModule: context.module,
    returnChapterId: context.chapterId
  };
}

function replacePageRoute(route) {
  if (restoringPageRoute) return;
  const hash = serializePageRoute(route);
  if (window.location.hash !== hash) window.history.replaceState(null, "", hash);
  schedulePresenceHeartbeat();
  syncTopSearchButton();
}

function presencePageForRoute(route = currentPageRoute()) {
  if (!state.work || route.view === "shelf" || route.view === "platform-ai" || route.view === "platform-usage") return null;
  if (route.view === "reader") return { kind: "welcome" };
  if (relationshipPresenceId) return { kind: "entity-editor", module: "relationship", resourceId: relationshipPresenceId };
  if (route.view === "editor") return { kind: "editor", resourceId: String(route.chapterId ?? "") || undefined };
  if (route.view === "entity-editor") return { kind: "entity-editor", module: route.entity, resourceId: String(route.entityId ?? "") || undefined };
  if (route.view === "module") return { kind: "module", module: route.module };
  if (route.view === "settings" || route.view === "platform-ai" || route.view === "platform-usage" || route.view === "work-audit") return { kind: "settings" };
  return { kind: "welcome" };
}

function presencePageKey(page) {
  if (!page) return "";
  if (page.kind === "editor") return `editor:${page.resourceId ?? ""}`;
  if (page.kind === "entity-editor") return `entity-editor:${page.module ?? ""}:${page.resourceId ?? ""}`;
  if (page.kind === "module") return `module:${page.module ?? ""}`;
  return page.kind;
}

function groupedPresenceParticipants() {
  const groups = new Map();
  for (const participant of presenceParticipants) {
    const current = groups.get(participant.userId) ?? { ...participant, pages: [], clientIds: [] };
    if (!current.pages.some((page) => page.key === participant.page.key)) current.pages.push(participant.page);
    current.clientIds.push(participant.clientId);
    groups.set(participant.userId, current);
  }
  return [...groups.values()];
}

function hasOtherCollaborators() {
  return presenceParticipants.some((participant) => participant.userId !== state.user?.userId);
}

function syncChapterAutoSaveWithPresence() {
  const wasDisabled = collaborationAutoSaveDisabled;
  collaborationAutoSaveDisabled = hasOtherCollaborators();
  if (collaborationAutoSaveDisabled) {
    cancelChapterAutoSave();
    if (state.chapter && canEditProse() && !chapterEditorReadOnly) {
      setSaveState(state.dirty ? "多人协作，自动保存已关闭" : "自动保存已关闭", state.dirty);
    }
    return;
  }
  if (wasDisabled && state.dirty && state.chapter && canEditProse() && !chapterEditorReadOnly) scheduleChapterAutoSave(250);
}

function renderPresence() {
  const control = $("#presence-control");
  if (!state.work || !presenceParticipants.length) {
    syncChapterAutoSaveWithPresence();
    control.classList.add("hidden");
    $("#presence-panel").classList.add("hidden");
    $("#presence-button").setAttribute("aria-expanded", "false");
    return;
  }
  const groups = groupedPresenceParticipants();
  const showControl = groups.length > 1;
  const localKey = presencePageKey(presencePageForRoute());
  syncChapterAutoSaveWithPresence();
  control.classList.toggle("hidden", !showControl);
  if (!showControl) {
    $("#presence-panel").classList.add("hidden");
    $("#presence-button").setAttribute("aria-expanded", "false");
  }
  $("#presence-count").textContent = `${groups.length} 人`;
  $("#presence-list").innerHTML = groups.map((participant) => {
    const isCurrent = participant.userId === state.user?.userId;
    const samePage = !isCurrent && participant.pages.some((page) => page.key === localKey);
    const pageLabels = participant.pages.map((page) => page.label).join("、");
    const avatar = participant.avatarUrl
      ? `<span class="user-avatar"><span class="user-avatar-fallback">${esc(Array.from(participant.displayName || participant.username)[0] ?? "作")}</span><img src="${esc(participant.avatarUrl)}" alt=""></span>`
      : `<span class="user-avatar"><span class="user-avatar-fallback">${esc(Array.from(participant.displayName || participant.username)[0] ?? "作")}</span></span>`;
    return `<div class="presence-person${samePage ? " is-same-page" : ""}">${avatar}<div class="presence-person-copy"><strong>${esc(participant.displayName)}${isCurrent ? "（你）" : ""}</strong><small>${esc(pageLabels)}</small></div>${samePage ? '<span class="presence-same-page">同一页面</span>' : ""}</div>`;
  }).join("");
}

async function refreshPresence() {
  const requestId = ++presenceHeartbeatRequest;
  if (presenceHeartbeatTimer !== null) clearTimeout(presenceHeartbeatTimer);
  presenceHeartbeatTimer = null;
  const workId = state.work?.id;
  const page = presencePageForRoute();
  if (!workId || !page || !state.user) {
    presenceParticipants = [];
    renderPresence();
    return [];
  }
  try {
    const payload = await api(`/api/works/${encodeURIComponent(workId)}/presence`, {
      method: "POST",
      body: { clientId: presenceClientId, page },
      skipOptimisticVersion: true
    });
    if (state.work?.id === workId && presenceHeartbeatRequest === requestId) {
      presenceParticipants = Array.isArray(payload) ? payload : (payload?.participants ?? []);
      renderPresence();
      const recentChanges = Array.isArray(payload) ? [] : (payload?.recentChanges ?? []);
      void handleCollaborativeChanges(recentChanges);
    }
  } catch {
    if (state.work?.id === workId) renderPresence();
  } finally {
    if (state.work?.id === workId && presenceHeartbeatRequest === requestId) presenceHeartbeatTimer = setTimeout(refreshPresence, presenceHeartbeatInterval);
  }
  return presenceParticipants;
}

async function handleCollaborativeChanges(recentChanges) {
  if (!Array.isArray(recentChanges) || !recentChanges.length || collaborativeChangePromptOpen) return;
  const localKey = presencePageKey(presencePageForRoute());
  const selfId = state.user?.userId;
  const incoming = recentChanges.filter((change) => (
    change
    && change.pageKey === localKey
    && change.actorUserId
    && change.actorUserId !== selfId
    && change.id
    && !acknowledgedCollaborativeChangeIds.has(change.id)
  ));
  if (!incoming.length) return;
  const latest = incoming[0];
  for (const change of incoming) acknowledgedCollaborativeChangeIds.add(change.id);
  while (acknowledgedCollaborativeChangeIds.size > 200) {
    const oldest = acknowledgedCollaborativeChangeIds.values().next().value;
    acknowledgedCollaborativeChangeIds.delete(oldest);
  }
  collaborativeChangePromptOpen = true;
  try {
    const changeLabel = latest.label || "当前页面";
    const deleted = latest.action === "delete";
    const targetLabel = deleted ? changeLabel.replace(/编辑$/u, "") : changeLabel;
    const message = deleted
      ? `${latest.actorDisplayName || "协作者"}已删除当前${targetLabel}。请先确认本地没有需要保留的修改，${latest.pageDeleted ? "确认后返回对应列表。" : "再刷新页面查看最新状态。"}`
      : `${latest.actorDisplayName || "协作者"}已在“${changeLabel}”保存新内容。请先确认本地没有需要保留的修改，再刷新页面继续查看。`;
    const shouldReload = await confirmToast(message, {
      title: deleted ? `${targetLabel}已删除` : `${changeLabel}已更新`,
      confirmLabel: deleted && latest.pageDeleted ? (latest.pageKey.startsWith("editor:") ? "返回正文" : "返回列表") : "刷新页面",
      cancelLabel: "稍后处理"
    });
    if (shouldReload) reloadAfterCollaborativeChange(latest);
  } finally {
    collaborativeChangePromptOpen = false;
  }
}

function reloadAfterCollaborativeChange(change) {
  const workId = state.work?.id;
  if (change?.action === "delete" && change.pageDeleted && workId) {
    const entityModule = {
      setting: "settings",
      character: "characters",
      race: "races",
      organization: "organizations",
      relationship: "relationships"
    }[String(change.pageKey ?? "").split(":")[1] ?? ""];
    const safeRoute = change.pageKey.startsWith("editor:")
      ? { view: "editor", workId }
      : entityModule
        ? { view: "module", workId, module: entityModule }
        : { view: "welcome", workId };
    window.history.replaceState(null, "", serializePageRoute(safeRoute));
  }
  window.location.reload();
}

function schedulePresenceHeartbeat() {
  if (presenceHeartbeatQueued !== null) clearTimeout(presenceHeartbeatQueued);
  presenceHeartbeatQueued = setTimeout(() => {
    presenceHeartbeatQueued = null;
    void refreshPresence();
  }, 80);
}

function setRelationshipPresence(relationshipId) {
  const nextId = relationshipId ? String(relationshipId) : null;
  if (relationshipPresenceId === nextId) return;
  relationshipPresenceId = nextId;
  void refreshPresence();
}

async function confirmConcurrentSave() {
  await refreshPresence();
  const localKey = presencePageKey(presencePageForRoute());
  const peers = presenceParticipants.filter((participant) => participant.clientId !== presenceClientId && participant.page.key === localKey);
  if (!peers.length) return true;
  const names = [...new Set(peers.map((participant) => participant.displayName))];
  return confirmToast(`${names.join("、")}也停留在这个编辑页面。当前项目尚未适配多人同时编辑，继续保存可能覆盖对方的修改。`, {
    title: "检测到同页协作",
    confirmLabel: "仍然保存",
    cancelLabel: "暂不保存"
  });
}

function currentPageRoute() {
  const workId = state.work?.id ?? null;
  if (!$("#im-view").classList.contains("hidden")) return { view: "im" };
  if (!$("#reader-view").classList.contains("hidden") && workId) {
    return { view: "reader", workId, chapterId: readingTargetChapter?.id ?? null };
  }
  if (!$("#entity-editor-view").classList.contains("hidden") && workId && entityEditorType) {
    const entityId = entityEditorType === "setting" ? settingEditorItem?.id : entityEditorType === "character" ? characterEditorItem?.id : knowledgeEditorItem?.id;
    return { view: "entity-editor", workId, entity: entityEditorType, entityId: entityId ?? null, entityMode: entityEditorReadOnly ? "read" : "edit" };
  }
  if (!$("#settings-hub-view").classList.contains("hidden")) return { view: "settings", workId, ...settingsRouteContext() };
  if (!$("#platform-ai-view").classList.contains("hidden")) return { view: "platform-ai", workId, ...settingsRouteContext() };
  if (!$("#platform-usage-view").classList.contains("hidden")) return { view: "platform-usage", workId, ...settingsRouteContext() };
  if (!$("#work-audit-view").classList.contains("hidden")) return { view: "work-audit", workId, ...settingsRouteContext() };
  if (!$("#shelf-view").classList.contains("hidden")) return { view: "shelf" };
  if (!workId) return { view: "shelf" };
  if (!$("#editor-view").classList.contains("hidden")) return { view: "editor", workId, chapterId: state.chapter?.id ?? null };
  if (!$("#module-view").classList.contains("hidden")) return { view: "module", workId, module: state.module };
  return { view: "welcome", workId };
}

function isChapterSearchContext() {
  return Boolean(state.work && state.chapter && !$("#editor-view").classList.contains("hidden"));
}

function syncTopSearchButton() {
  const button = $("#top-search-button");
  const chapterContext = isChapterSearchContext();
  button.classList.toggle("hidden", chapterContext);
  button.disabled = !state.work || chapterContext || !canReadAggregateContent();
  if (!chapterContext) closeChapterSearchPanel({ restoreFocus: false });
}

function chapterSearchMatches() {
  return findTextMatches($("#chapter-content").value, $("#chapter-search-query").value);
}

function renderChapterSearchStatus() {
  const query = $("#chapter-search-query").value;
  const matches = chapterSearchMatches();
  const status = $("#chapter-search-status");
  const readOnly = !canEditProse() || chapterEditorReadOnly;
  const replaceButtons = [$("#chapter-search-replace"), $("#chapter-search-replace-all")];
  replaceButtons.forEach((button) => { button.disabled = readOnly || matches.length === 0; });
  $("#chapter-search-previous").disabled = matches.length === 0;
  $("#chapter-search-next").disabled = matches.length === 0;
  if (!query) {
    status.textContent = "输入关键词后开始搜索";
    return;
  }
  if (!matches.length) {
    status.textContent = "本章未找到匹配内容";
    return;
  }
  const current = chapterSearchMatchIndex >= 0 ? chapterSearchMatchIndex + 1 : 0;
  status.textContent = current ? `第 ${current} / ${matches.length} 处` : `找到 ${matches.length} 处`;
}

function syncChapterSearchControls() {
  if (!$("#chapter-search-panel")) return;
  const matches = chapterSearchMatches();
  if (chapterSearchMatchIndex >= matches.length) chapterSearchMatchIndex = matches.length - 1;
  renderChapterSearchStatus();
}

function selectChapterSearchMatch(index) {
  const matches = chapterSearchMatches();
  if (!matches.length) {
    chapterSearchMatchIndex = -1;
    renderChapterSearchStatus();
    return;
  }
  chapterSearchMatchIndex = (index + matches.length) % matches.length;
  const input = $("#chapter-content");
  const start = matches[chapterSearchMatchIndex];
  input.focus({ preventScroll: true });
  input.setSelectionRange(start, start + $("#chapter-search-query").value.length);
  renderChapterSearchStatus();
}

function moveChapterSearchMatch(direction) {
  const matches = chapterSearchMatches();
  if (!matches.length) {
    renderChapterSearchStatus();
    return;
  }
  const nextIndex = chapterSearchMatchIndex < 0
    ? direction > 0 ? 0 : matches.length - 1
    : chapterSearchMatchIndex + direction;
  selectChapterSearchMatch(nextIndex);
}

function openChapterSearchPanel() {
  if (!isChapterSearchContext()) return false;
  const panel = $("#chapter-search-panel");
  panel.classList.remove("hidden");
  panel.setAttribute("aria-hidden", "false");
  syncChapterSearchControls();
  queueMicrotask(() => {
    const input = $("#chapter-search-query");
    input.focus();
    if (input.value) input.select();
  });
  return true;
}

function closeChapterSearchPanel({ restoreFocus = true } = {}) {
  const panel = $("#chapter-search-panel");
  if (!panel || panel.classList.contains("hidden")) return;
  panel.classList.add("hidden");
  panel.setAttribute("aria-hidden", "true");
  chapterSearchMatchIndex = -1;
  if (restoreFocus && isChapterSearchContext()) $("#chapter-content").focus({ preventScroll: true });
}

function resetChapterSearchPanel() {
  closeChapterSearchPanel({ restoreFocus: false });
  $("#chapter-search-query").value = "";
  $("#chapter-replace-query").value = "";
  chapterSearchMatchIndex = -1;
  renderChapterSearchStatus();
}

function replaceCurrentChapterSearchMatch() {
  if (!isChapterSearchContext() || !canEditProse() || chapterEditorReadOnly) {
    toast("请先进入编辑模式", "error");
    return;
  }
  const query = $("#chapter-search-query").value;
  const matches = chapterSearchMatches();
  if (!query || !matches.length) return renderChapterSearchStatus();
  const index = chapterSearchMatchIndex < 0 ? 0 : chapterSearchMatchIndex;
  const start = matches[index];
  const input = $("#chapter-content");
  const replacement = $("#chapter-replace-query").value;
  input.value = `${input.value.slice(0, start)}${replacement}${input.value.slice(start + query.length)}`;
  syncChapterDraftLineIds(input.value);
  chapterSearchMatchIndex = Math.min(index, Math.max(0, findTextMatches(input.value, query).length - 1));
  updateChapterStats();
  clearChapterLineSelection();
  scheduleChapterLineNumbers();
  scheduleChapterAutoSave(120);
  syncChapterSearchControls();
  toast("已替换本章 1 处，等待自动保存");
}

function replaceAllChapterSearchMatches() {
  if (!isChapterSearchContext() || !canEditProse() || chapterEditorReadOnly) {
    toast("请先进入编辑模式", "error");
    return;
  }
  const query = $("#chapter-search-query").value;
  const input = $("#chapter-content");
  const result = replaceTextMatches(input.value, query, $("#chapter-replace-query").value);
  if (!result.matches) return renderChapterSearchStatus();
  input.value = result.content;
  syncChapterDraftLineIds(input.value);
  chapterSearchMatchIndex = -1;
  updateChapterStats();
  clearChapterLineSelection();
  scheduleChapterLineNumbers();
  scheduleChapterAutoSave(120);
  syncChapterSearchControls();
  toast(`已替换本章 ${result.matches} 处，等待自动保存`);
}

function loadPanelLayout() {
  try {
    const stored = JSON.parse(localStorage.getItem(panelLayoutStorageKey) ?? "{}");
    return {
      leftWidth: Math.round(Math.max(180, Math.min(520, Number(stored.leftWidth) || panelLayoutDefaults.leftWidth))),
      aiWidth: Math.round(Math.max(260, Math.min(600, Number(stored.aiWidth) || panelLayoutDefaults.aiWidth))),
      leftCollapsed: Boolean(stored.leftCollapsed),
      aiCollapsed: Boolean(stored.aiCollapsed)
    };
  } catch {
    return { ...panelLayoutDefaults };
  }
}

let panelLayout = loadPanelLayout();
if (window.matchMedia("(max-width: 850px)").matches) {
  // 手机上默认收起创作助手，避免遮挡正文；用户可通过底部把手随时展开。
  panelLayout.aiCollapsed = true;
  panelLayout.leftCollapsed = true;
}

function constrainPanelLayout() {
  const minimumMainWidth = 480;
  if (!panelLayout.leftCollapsed) {
    const available = window.innerWidth - (panelLayout.aiCollapsed ? 42 : panelLayout.aiWidth) - minimumMainWidth;
    panelLayout.leftWidth = Math.max(180, Math.min(520, available, panelLayout.leftWidth));
  }
  if (!panelLayout.aiCollapsed) {
    const available = window.innerWidth - (panelLayout.leftCollapsed ? 42 : panelLayout.leftWidth) - minimumMainWidth;
    panelLayout.aiWidth = Math.max(260, Math.min(600, available, panelLayout.aiWidth));
  }
}

function applyPanelLayout(persist = false) {
  const phoneClient = isPhoneClient();
  if (phoneClient && !aiConversationWorkspaceOpen) panelLayout.aiCollapsed = true;
  constrainPanelLayout();
  const app = $("#app");
  app.style.setProperty("--left-panel-width", `${panelLayout.leftWidth}px`);
  app.style.setProperty("--ai-panel-width", `${panelLayout.aiWidth}px`);
  app.classList.toggle("left-panel-collapsed", panelLayout.leftCollapsed);
  app.classList.toggle("ai-panel-collapsed", panelLayout.aiCollapsed);
  app.classList.toggle("phone-client", phoneClient);
  const mobileViewport = isMobileViewport();
  $("#left-panel-toggle").textContent = mobileViewport ? "›" : (panelLayout.leftCollapsed ? "›" : "‹");
  $("#left-panel-toggle").setAttribute("aria-expanded", String(!panelLayout.leftCollapsed));
  $("#left-panel-toggle").setAttribute("aria-label", mobileViewport
    ? (panelLayout.leftCollapsed ? "打开作品模块" : "关闭作品模块")
    : (panelLayout.leftCollapsed ? "展开作品侧栏" : "收起作品侧栏"));
  $("#mobile-module-tab").setAttribute("aria-expanded", String(!panelLayout.leftCollapsed));
  $("#ai-panel-toggle").textContent = aiConversationWorkspaceOpen ? "×" : (panelLayout.aiCollapsed ? "‹" : "›");
  $("#ai-panel-toggle").setAttribute("aria-expanded", String(!panelLayout.aiCollapsed));
  $("#ai-panel-toggle").setAttribute("aria-label", aiConversationWorkspaceOpen ? "关闭创作助手全屏面板" : (panelLayout.aiCollapsed ? "展开创作助手" : "收起创作助手"));
  syncMobileAiPanelSafeTop();
  scheduleChapterLineNumbers();
  if (persist) {
    try { localStorage.setItem(panelLayoutStorageKey, JSON.stringify(panelLayout)); } catch { /* 浏览器禁用存储时仅保留当前布局 */ }
  }
}

function ensureAiPanelExpanded() {
  if (!state.work || !canReadPermissionModule(state.work, "ai-chat")) return;
  if (isPhoneClient() || isMobileViewport()) {
    setAiConversationWorkspaceVisible(true);
    return;
  }
  panelLayout.aiCollapsed = false;
  applyPanelLayout(true);
}

function setupPanelResize(handle, side) {
  let resize = null;
  const updateWidth = (width) => {
    if (side === "left") panelLayout.leftWidth = width;
    else panelLayout.aiWidth = width;
    applyPanelLayout();
  };
  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || (side === "left" ? panelLayout.leftCollapsed : panelLayout.aiCollapsed)) return;
    resize = { pointerId: event.pointerId, startX: event.clientX, startWidth: side === "left" ? panelLayout.leftWidth : panelLayout.aiWidth };
    handle.setPointerCapture(event.pointerId);
    document.body.classList.add("is-panel-resizing");
  });
  handle.addEventListener("pointermove", (event) => {
    if (!resize || event.pointerId !== resize.pointerId) return;
    updateWidth(resize.startWidth + (event.clientX - resize.startX) * (side === "left" ? 1 : -1));
  });
  const finish = (event) => {
    if (!resize || event.pointerId !== resize.pointerId) return;
    resize = null;
    document.body.classList.remove("is-panel-resizing");
    applyPanelLayout(true);
  };
  handle.addEventListener("pointerup", finish);
  handle.addEventListener("pointercancel", finish);
  handle.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const direction = event.key === "ArrowRight" ? 1 : -1;
    const current = side === "left" ? panelLayout.leftWidth : panelLayout.aiWidth;
    updateWidth(current + direction * 12 * (side === "left" ? 1 : -1));
    applyPanelLayout(true);
  });
}

