function createEditorDirtyTracker(initialSnapshot = "") {
  let savedSnapshot = String(initialSnapshot);
  return {
    markSaved(snapshot) {
      savedSnapshot = String(snapshot);
    },
    isDirty(snapshot) {
      return String(snapshot) !== savedSnapshot;
    }
  };
}

