let characterEditorRelationshipsLoading = false;
let characterEditorRelationshipsLoaded = false;
let characterEditorSections = [];
let characterSectionPendingAttachments = [];
let markdownEditorPendingAttachments = [];
let characterSectionEditorDirty = false;
let settingEditorVditor = null;
let knowledgeSectionVditor = null;
let characterSectionVditor = null;
let vditorResourcesPromise = null;
const settingEditorDirtyTracker = createEditorDirtyTracker();
const characterSectionEditorDirtyTracker = createEditorDirtyTracker();
let formDialogVditors = [];
let entityHistoryContext = null;
let moduleContentInteractionsBound = false;

function applyChapterEditorMode() {
  const permissionBlocked = Boolean(state.work) && !canEditProse();
  const viewOnly = permissionBlocked || chapterEditorReadOnly;
  const editButton = $("#chapter-edit-button");
  $("#editor-view").classList.toggle("is-read-only", viewOnly);
  $("#chapter-title").readOnly = viewOnly;
  $("#chapter-content").readOnly = viewOnly;
  $("#chapter-title").setAttribute("aria-readonly", String(viewOnly));
  $("#chapter-content").setAttribute("aria-readonly", String(viewOnly));
  editButton.classList.toggle("hidden", permissionBlocked || !state.chapter);
  editButton.classList.toggle("primary-button", chapterEditorReadOnly);
  editButton.classList.toggle("ghost-button", !chapterEditorReadOnly);
  editButton.textContent = chapterEditorReadOnly ? "编辑" : "预览";
  editButton.setAttribute("aria-pressed", String(!chapterEditorReadOnly));
  editButton.setAttribute("aria-label", chapterEditorReadOnly ? "切换到编辑模式" : "切换到预览模式");
  $("#chapter-annotations-button").classList.toggle("hidden", !state.chapter || !canReadModule("comments"));
  syncChapterSearchControls();
  if (viewOnly) cancelChapterAutoSave();
  syncMobileAiPanelSafeTop();
}

function enterChapterEditMode() {
  if (!state.chapter || !canEditProse()) return;
  chapterEditorReadOnly = false;
  applyChapterEditorMode();
  const draft = chapterDraftSnapshot();
  if (!sameChapterSnapshot(draft, lastSavedChapterSnapshot)) scheduleChapterAutoSave(120);
  else setSaveState("已保存");
  $("#chapter-content").focus();
}

function toggleChapterEditPreviewMode() {
  if (!state.chapter || !canEditProse()) return;
  if (chapterEditorReadOnly) {
    enterChapterEditMode();
    return;
  }
  chapterEditorReadOnly = true;
  cancelChapterAutoSave();
  applyChapterEditorMode();
  setSaveState(state.dirty ? "预览中 · 有未保存修改" : "预览中", state.dirty);
  $("#chapter-edit-button").focus();
}

function showEntityEditorPage(type, { readOnly = false } = {}) {
  const module = type === "setting" ? "settings" : type === "character" ? "characters" : type === "race" ? "races" : "organizations";
  const viewOnly = readOnly || !canEditModule(module);
  entityEditorType = type;
  entityEditorDirty = false;
  entityEditorReadOnly = viewOnly;
  characterSectionEditorDirty = false;
  knowledgeSectionEditorDirty = false;
  $("#entity-editor-view").classList.remove("hidden");
  $("#setting-editor-form").classList.toggle("hidden", type !== "setting");
  $("#character-editor-form").classList.toggle("hidden", type !== "character");
  $("#knowledge-editor-form").classList.toggle("hidden", !["race", "organization"].includes(type));
  $("#character-section-editor-view").classList.add("hidden");
  $("#knowledge-section-editor-view").classList.add("hidden");
  ["setting", "character", "knowledge"].forEach((editor) => $(`#${editor}-editor-readonly-badge`).classList.toggle("hidden", !(viewOnly && (editor === "knowledge" ? ["race", "organization"].includes(type) : editor === type))));
  $("#app").inert = true;
  document.body.classList.add("entity-editor-open");
  replacePageRoute(currentPageRoute());
}

function markEntityEditorDirty() {
  const module = entityEditorType === "setting" ? "settings" : entityEditorType === "character" ? "characters" : entityEditorType === "race" ? "races" : "organizations";
  if (entityEditorType && !entityEditorReadOnly && canEditModule(module)) entityEditorDirty = true;
}

async function confirmEntityEditorDiscard(message) {
  if (!entityEditorDirty) return true;
  return confirmToast(message ?? "当前资料有未保存修改，返回列表将丢弃这些修改。是否继续？", {
    title: "放弃未保存修改",
    confirmLabel: "放弃并继续",
    cancelLabel: "继续编辑"
  });
}

function isEntityEditorSaving() {
  return Boolean($("#entity-editor-view").querySelector('[aria-busy="true"]'));
}

async function closeEntityEditor({ force = false } = {}) {
  if (isEntityEditorSaving()) {
    toast("正在保存，请稍候");
    return false;
  }
  if (!$("#character-section-editor-view").classList.contains("hidden")) return closeCharacterSectionEditor({ force });
  if (!$("#knowledge-section-editor-view").classList.contains("hidden")) return closeKnowledgeSectionEditor({ force });
  if (!force && !(await confirmEntityEditorDiscard())) return false;
  await discardPendingCharacterAttachments();
  await discardPendingMarkdownAttachments();
  destroyVditorEditor(settingEditorVditor);
  settingEditorVditor = null;
  const module = entityEditorType === "setting" ? "settings" : entityEditorType === "character" ? "characters" : entityEditorType === "race" ? "races" : "organizations";
  entityEditorType = null;
  entityEditorDirty = false;
  entityEditorReadOnly = false;
  settingEditorItem = null;
  characterEditorItem = null;
  knowledgeEditorItem = null;
  knowledgeEditorKind = null;
  knowledgeEditorSections = [];
  knowledgeSectionEditorIndex = null;
  knowledgeSectionEditorDirty = false;
  $("#entity-editor-view").classList.add("hidden");
  $("#setting-editor-form").classList.add("hidden");
  $("#character-editor-form").classList.add("hidden");
  $("#knowledge-editor-form").classList.add("hidden");
  $("#knowledge-section-editor-view").classList.add("hidden");
  $("#app").inert = false;
  document.body.classList.remove("entity-editor-open");
  await showModule(module);
  return true;
}

function setModuleNavExpanded(expanded) {
  moduleNavExpanded = expanded;
  $("#module-more-button .nav-label").textContent = expanded ? "收起" : "更多";
  $("#module-more-button").setAttribute("aria-expanded", String(expanded));
  $("#module-nav").querySelectorAll(".module-nav-secondary").forEach((button) => button.classList.toggle("hidden", !expanded));
}

function syncChapterLineNumberScroll() {
  const input = $("#chapter-content");
  const inner = $("#chapter-line-numbers-inner");
  const whitespace = $("#chapter-whitespace-inner");
  if (!input || !inner) return;
  inner.style.transform = `translateY(${-input.scrollTop}px)`;
  inner.dataset.scrollTop = String(input.scrollTop);
  if (whitespace) {
    whitespace.style.transform = `translate(${-input.scrollLeft}px, ${-input.scrollTop}px)`;
    whitespace.dataset.scrollTop = String(input.scrollTop);
  }
  if (!chapterLineVirtualWindow) return;
  const buffer = input.clientHeight * 0.35;
  const viewportBottom = input.scrollTop + input.clientHeight;
  const needsPreviousLines = chapterLineVirtualWindow.start > 0 && input.scrollTop < chapterLineVirtualWindow.top + buffer;
  const needsNextLines = chapterLineVirtualWindow.end < chapterLineVirtualWindow.lineCount
    && viewportBottom > chapterLineVirtualWindow.bottom - buffer;
  if (needsPreviousLines || needsNextLines) scheduleChapterLineNumbers();
}

function syncChapterWhitespaceControls() {
  document.querySelectorAll("[data-toggle-whitespace]").forEach((button) => {
    button.setAttribute("aria-pressed", String(chapterWhitespaceVisible));
    button.textContent = chapterWhitespaceVisible ? "隐藏空白符" : "显示空白符";
  });
}

function toggleChapterWhitespaceVisibility() {
  chapterWhitespaceVisible = !chapterWhitespaceVisible;
  syncChapterWhitespaceControls();
  scheduleChapterLineNumbers();
}

function renderChapterWhitespaceMarkers(input, style, layout, lineWindow, getLineBounds, totalHeight) {
  const overlay = $("#chapter-whitespace-overlay");
  const inner = $("#chapter-whitespace-inner");
  syncChapterWhitespaceControls();
  if (!overlay || !inner) return;
  overlay.classList.toggle("is-visible", chapterWhitespaceVisible);
  if (!chapterWhitespaceVisible) {
    inner.replaceChildren();
    delete inner.dataset.virtualStart;
    delete inner.dataset.virtualEnd;
    delete inner.dataset.renderedLineCount;
    return;
  }
  const paddingTop = parseFloat(style.paddingTop) || 0;
  const paddingBottom = parseFloat(style.paddingBottom) || 0;
  const firstLineTop = getLineBounds(lineWindow.start).top;
  Object.assign(inner.style, {
    width: `${input.clientWidth}px`,
    height: `${Math.max(input.clientHeight, totalHeight + paddingTop + paddingBottom)}px`,
    fontFamily: style.fontFamily,
    fontSize: style.fontSize,
    fontWeight: style.fontWeight,
    fontStyle: style.fontStyle,
    lineHeight: style.lineHeight,
    letterSpacing: style.letterSpacing,
    tabSize: style.tabSize,
    padding: style.padding,
    paddingTop: `${paddingTop + firstLineTop}px`,
    whiteSpace: style.whiteSpace,
    overflowWrap: style.overflowWrap,
    wordBreak: style.wordBreak
  });
  const fragment = document.createDocumentFragment();
  const visibleText = layout.lines.slice(lineWindow.start, lineWindow.end).join("\n");
  for (const token of tokenizeVisibleSpaces(visibleText)) {
    if (token.type === "text") {
      fragment.append(document.createTextNode(token.text));
      continue;
    }
    const marker = document.createElement("span");
    marker.className = `chapter-space-marker ${token.type}`;
    marker.textContent = token.text;
    marker.dataset.spaceType = token.type;
    fragment.append(marker);
  }
  inner.replaceChildren(fragment);
  inner.dataset.virtualStart = String(lineWindow.start);
  inner.dataset.virtualEnd = String(lineWindow.end - 1);
  inner.dataset.renderedLineCount = String(lineWindow.end - lineWindow.start);
}

function prepareChapterLineLayout(input, measure, style, contentWidth) {
  Object.assign(measure.style, {
    width: `${contentWidth}px`,
    fontFamily: style.fontFamily,
    fontSize: style.fontSize,
    fontWeight: style.fontWeight,
    fontStyle: style.fontStyle,
    lineHeight: style.lineHeight,
    letterSpacing: style.letterSpacing,
    tabSize: style.tabSize,
    overflowWrap: style.overflowWrap,
    wordBreak: style.wordBreak
  });
  const value = input.value.replace(/\r\n?/gu, "\n");
  const styleKey = JSON.stringify([
    contentWidth,
    style.fontFamily,
    style.fontSize,
    style.fontWeight,
    style.fontStyle,
    style.lineHeight,
    style.letterSpacing,
    style.tabSize,
    style.overflowWrap,
    style.wordBreak
  ]);
  if (!chapterLineLayout || chapterLineLayout.value !== value) {
    const mirror = buildChapterLineMirror(value);
    measure.textContent = mirror.text;
    chapterLineLayout = { ...mirror, value, styleKey, bounds: new Map() };
  } else if (chapterLineLayout.styleKey !== styleKey) {
    chapterLineLayout.styleKey = styleKey;
    chapterLineLayout.bounds.clear();
  }
  return chapterLineLayout;
}

function createChapterLineBoundsGetter(layout, measure, lineHeight, targetHeight = null) {
  const textNode = measure.firstChild;
  const measureRect = measure.getBoundingClientRect();
  const contentHeight = Number.isFinite(targetHeight) && targetHeight > 0 ? targetHeight : measureRect.height;
  const geometryScale = measureRect.height > 0 ? contentHeight / measureRect.height : 1;
  const geometryKey = `${measureRect.height}:${contentHeight}:${lineHeight}`;
  if (layout.geometryKey !== geometryKey) {
    layout.geometryKey = geometryKey;
    layout.bounds.clear();
  }
  return {
    measureHeight: contentHeight,
    getLineBounds(index) {
      const cached = layout.bounds.get(index);
      if (cached) return cached;
      const range = document.createRange();
      const start = layout.offsets[index];
      range.setStart(textNode, start);
      range.setEnd(textNode, start + layout.lines[index].length + 1);
      const rects = [...range.getClientRects()].filter((rect) => rect.height > 0);
      let top;
      let bottom;
      if (rects.length > 0) {
        const lineBoxes = rects.map((rect) => {
          const height = Math.max(lineHeight, rect.height);
          const leading = Math.max(0, (lineHeight - rect.height) / 2);
          const boxTop = (rect.top - measureRect.top - leading) * geometryScale;
          return { top: boxTop, bottom: boxTop + height * geometryScale };
        });
        top = Math.max(0, Math.min(...lineBoxes.map((box) => box.top)));
        bottom = Math.max(...lineBoxes.map((box) => box.bottom));
      } else {
        const scaledLineHeight = lineHeight * geometryScale;
        const availableHeight = Math.max(0, contentHeight - scaledLineHeight);
        top = layout.lines.length > 1 ? availableHeight * index / (layout.lines.length - 1) : 0;
        bottom = top + scaledLineHeight;
      }
      const bounds = { top, bottom: Math.max(top + lineHeight * geometryScale, bottom) };
      layout.bounds.set(index, bounds);
      return bounds;
    }
  };
}

function renderChapterLineNumbers({ targetLineIndex = null } = {}) {
  const input = $("#chapter-content");
  const inner = $("#chapter-line-numbers-inner");
  const measure = $("#chapter-line-measure");
  if (!input || !inner || !measure || input.clientWidth === 0) return;
  const style = getComputedStyle(input);
  const contentWidth = Math.max(1, input.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight));
  const lineHeight = parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.55;
  const numberStyle = getComputedStyle($("#chapter-line-numbers"));
  const numberLineHeight = parseFloat(numberStyle.lineHeight) || parseFloat(numberStyle.fontSize) * 1.2;
  const paddingTop = parseFloat(style.paddingTop) || 0;
  inner.style.top = `${calculateLineNumberTop(paddingTop, lineHeight, numberLineHeight)}px`;
  const numberTextOffset = calculateLineNumberTextOffset(lineHeight, numberLineHeight);
  const layout = prepareChapterLineLayout(input, measure, style, contentWidth);
  const paddingBottom = parseFloat(style.paddingBottom) || 0;
  const scrollContentHeight = input.scrollHeight - paddingTop - paddingBottom;
  const targetHeight = input.scrollHeight > input.clientHeight + 1 ? scrollContentHeight : null;
  const { getLineBounds, measureHeight } = createChapterLineBoundsGetter(layout, measure, lineHeight, targetHeight);
  if (Number.isInteger(targetLineIndex)) {
    const safeTarget = Math.max(0, Math.min(targetLineIndex, layout.lines.length - 1));
    input.scrollTop = Math.max(0, getLineBounds(safeTarget).top + paddingTop - input.clientHeight / 3);
  }
  const viewportTop = Math.max(0, input.scrollTop - paddingTop);
  const overscan = Math.max(input.clientHeight, lineHeight * 8);
  const lineWindow = findChapterLineWindow(
    layout.lines.length,
    getLineBounds,
    viewportTop - overscan,
    viewportTop + input.clientHeight + overscan
  );
  const numbers = document.createDocumentFragment();
  for (let index = lineWindow.start; index < lineWindow.end; index += 1) {
    const number = document.createElement("div");
    number.className = "chapter-line-number";
    number.dataset.lineIndex = String(index);
    const lineSelect = document.createElement("button");
    lineSelect.type = "button";
    lineSelect.className = "chapter-line-number-select";
    lineSelect.textContent = String(index + 1);
    lineSelect.setAttribute("aria-label", `选择第 ${index + 1} 行`);
    lineSelect.tabIndex = -1;
    number.append(lineSelect);
    const annotationCount = chapterAnnotationCounts.get(index + 1) ?? 0;
    if (annotationCount > 0) {
      const bubble = document.createElement("button");
      bubble.type = "button";
      bubble.className = "chapter-line-annotation-count";
      bubble.dataset.lineIndex = String(index);
      bubble.dataset.lineAnnotationCount = String(annotationCount);
      bubble.textContent = String(annotationCount);
      bubble.setAttribute("aria-label", `查看第 ${index + 1} 行的 ${annotationCount} 条评论和待办`);
      number.append(bubble);
    }
    const selected = chapterLineSelection && index >= chapterLineSelection.start && index <= chapterLineSelection.end;
    if (selected) {
      number.classList.add("is-line-selected");
      lineSelect.setAttribute("aria-pressed", "true");
    }
    const bounds = getLineBounds(index);
    number.style.top = `${bounds.top}px`;
    number.style.height = `${bounds.bottom - bounds.top}px`;
    lineSelect.style.paddingTop = `${numberTextOffset}px`;
    numbers.append(number);
  }
  inner.replaceChildren(numbers);
  inner.style.height = `${measureHeight}px`;
  inner.dataset.lineCount = String(layout.lines.length);
  inner.dataset.virtualStart = String(lineWindow.start);
  inner.dataset.virtualEnd = String(lineWindow.end - 1);
  inner.dataset.renderedLineCount = String(lineWindow.end - lineWindow.start);
  const firstBounds = getLineBounds(lineWindow.start);
  const lastBounds = getLineBounds(lineWindow.end - 1);
  chapterLineVirtualWindow = {
    start: lineWindow.start,
    end: lineWindow.end,
    lineCount: layout.lines.length,
    top: firstBounds.top + paddingTop,
    bottom: lastBounds.bottom + paddingTop
  };
  renderChapterWhitespaceMarkers(input, style, layout, lineWindow, getLineBounds, measureHeight);
  syncChapterLineNumberScroll();
}

function requestChapterLineNumberFrame() {
  if (chapterLineNumberFrame !== null) return;
  chapterLineNumberFrame = requestAnimationFrame(() => {
    chapterLineNumberFrame = null;
    renderChapterLineNumbers();
  });
}

function scheduleChapterLineNumbers(delay = 0) {
  const wait = typeof delay === "number" && Number.isFinite(delay) ? Math.max(0, delay) : 0;
  if (wait === 0) {
    if (chapterLineNumberTimer !== null) {
      clearTimeout(chapterLineNumberTimer);
      chapterLineNumberTimer = null;
    }
    requestChapterLineNumberFrame();
    return;
  }
  if (chapterLineNumberFrame !== null || chapterLineNumberTimer !== null) return;
  chapterLineNumberTimer = setTimeout(() => {
    chapterLineNumberTimer = null;
    requestChapterLineNumberFrame();
  }, wait);
}

function scheduleChapterCaretScroll() {
  if (!state.work?.editorTypewriterModeEnabled || chapterCaretScrollFrame !== null) return;
  chapterCaretScrollFrame = requestAnimationFrame(() => {
    chapterCaretScrollFrame = null;
    const input = $("#chapter-content");
    const measure = $("#chapter-line-measure");
    if (!state.work?.editorTypewriterModeEnabled || document.activeElement !== input || input.readOnly || input.clientWidth === 0 || input.clientHeight === 0) return;
    const style = getComputedStyle(input);
    const paddingTop = parseFloat(style.paddingTop) || 0;
    const paddingBottom = parseFloat(style.paddingBottom) || 0;
    const contentWidth = Math.max(1, input.clientWidth - parseFloat(style.paddingLeft) - parseFloat(style.paddingRight));
    const lineHeight = parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.55;
    const layout = prepareChapterLineLayout(input, measure, style, contentWidth);
    const scrollContentHeight = input.scrollHeight - paddingTop - paddingBottom;
    const targetHeight = input.scrollHeight > input.clientHeight + 1 ? scrollContentHeight : null;
    const { getLineBounds } = createChapterLineBoundsGetter(layout, measure, lineHeight, targetHeight);
    const lineIndex = Math.min(layout.lines.length - 1, chapterLineIndexAtOffset(input.value, input.selectionEnd));
    const caretBottom = getLineBounds(lineIndex).bottom + paddingTop;
    const nextScrollTop = calculateChapterCaretScroll({
      caretBottom,
      scrollTop: input.scrollTop,
      clientHeight: input.clientHeight,
      scrollHeight: input.scrollHeight
    });
    if (nextScrollTop === input.scrollTop) return;
    input.scrollTop = nextScrollTop;
    syncChapterLineNumberScroll();
    scheduleChapterLineNumbers();
  });
}

function lineIndexAtPointer(clientY) {
  const rows = [...$("#chapter-line-numbers-inner").querySelectorAll(".chapter-line-number")];
  if (!rows.length) return 0;
  for (const row of rows) {
    if (clientY < row.getBoundingClientRect().bottom) return Number(row.dataset.lineIndex);
  }
  return Number(rows[rows.length - 1].dataset.lineIndex);
}

function paintChapterLineSelection(anchor, focus) {
  const start = Math.min(anchor, focus);
  const end = Math.max(anchor, focus);
  chapterLineSelection = { start, end };
  $("#chapter-line-numbers-inner").querySelectorAll(".chapter-line-number").forEach((row) => {
    const selected = Number(row.dataset.lineIndex) >= start && Number(row.dataset.lineIndex) <= end;
    row.classList.toggle("is-line-selected", selected);
    row.querySelector(".chapter-line-number-select")?.setAttribute("aria-pressed", String(selected));
  });
}

function selectedChapterLinePayload(start, end) {
  const input = $("#chapter-content");
  const lines = input.value.replace(/\r\n?/gu, "\n").split("\n");
  const safeStart = Math.max(0, Math.min(start, lines.length - 1));
  const safeEnd = Math.max(safeStart, Math.min(end, lines.length - 1));
  const text = lines.slice(safeStart, safeEnd + 1).join("\n");
  const startOffset = lines.slice(0, safeStart).reduce((length, line) => length + line.length + 1, 0);
  return { safeStart, safeEnd, text, startOffset };
}

function selectChapterLines(start, end) {
  const input = $("#chapter-content");
  const selection = selectedChapterLinePayload(start, end);
  input.focus({ preventScroll: true });
  input.setSelectionRange(selection.startOffset, selection.startOffset);
  return selection;
}

function renderAiCitations() {
  const host = $("#ai-citations");
  host.replaceChildren();
  host.classList.toggle("hidden", state.aiCitations.length === 0);
  for (const citation of state.aiCitations) {
    const card = document.createElement("article");
    card.className = "ai-citation-card";
    const main = document.createElement("button");
    main.type = "button";
    main.className = "ai-citation-main";
    const source = document.createElement("strong");
    source.textContent = citation.chapterTitle;
    const range = document.createElement("small");
    range.textContent = citation.startLine === citation.endLine ? `第 ${citation.startLine} 行` : `第 ${citation.startLine}-${citation.endLine} 行`;
    const excerpt = document.createElement("span");
    excerpt.textContent = citation.text.replace(/\s+/gu, " ").trim() || "空白行";
    main.append(source, range, excerpt);
    main.addEventListener("click", () => card.classList.toggle("is-expanded"));
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "ai-citation-remove";
    remove.setAttribute("aria-label", `移除 ${citation.chapterTitle} 第 ${citation.startLine}-${citation.endLine} 行引用`);
    remove.textContent = "×";
    remove.addEventListener("click", () => {
      state.aiCitations = state.aiCitations.filter((item) => item.id !== citation.id);
      renderAiCitations();
    });
    const fullText = document.createElement("pre");
    fullText.textContent = citation.text || "（空白行）";
    card.append(main, remove, fullText);
    host.append(card);
  }
  setAiContextMeter(null);
}

function setAiSemanticSearchVisible(visible) {
  const panel = $("#ai-semantic-search-panel");
  panel.classList.toggle("hidden", !visible);
  $("#ai-semantic-search-toggle").setAttribute("aria-expanded", String(visible));
  if (visible) $("#ai-semantic-query").focus();
}

function semanticSearchScopeTypes(value) {
  return ({
    chapter: ["chapter"],
    setting: ["setting"],
    character: ["character"],
    race: ["race"],
    organization: ["organization"],
    timeline: ["timeline-track", "timeline-event"],
    relationship: ["relationship"],
    outlines: ["chapter-outline", "foreshadow"]
  })[value] ?? undefined;
}

function syncAiSemanticSelectionSummary() {
  const selected = [...$("#ai-semantic-search-results").querySelectorAll('input[data-semantic-entry-id]:checked')];
  const tokenCount = selected.reduce((total, input) => total + Number(input.dataset.estimatedTokens || 0), 0);
  $("#ai-semantic-selection-summary").textContent = selected.length
    ? `已选择 ${selected.length} 项，预计 ${tokenCount.toLocaleString("zh-CN")} Token`
    : "尚未选择结果";
  $("#ai-semantic-inject").disabled = selected.length === 0 || !state.work || !canWritePermissionModule(state.work, "ai-chat");
}

function renderAiSemanticSearchResults(search) {
  aiSemanticSearchResults = Array.isArray(search?.results) ? search.results : [];
  const host = $("#ai-semantic-search-results");
  const matchLabels = { metadata: "资料", exact: "精确", phonetic: "拼音", semantic: "语义" };
  host.innerHTML = aiSemanticSearchResults.length
    ? aiSemanticSearchResults.map((item, index) => {
      const lineRange = Number.isInteger(item.startLine)
        ? `<span>${item.startLine === item.endLine ? `第 ${item.startLine} 行` : `第 ${item.startLine}-${item.endLine} 行`}</span>`
        : "";
      const matchKinds = (Array.isArray(item.matchKinds) ? item.matchKinds : [])
        .map((kind) => `<span class="search-result-chip search-result-chip-${esc(kind)}">${esc(matchLabels[kind] ?? kind)}</span>`).join("");
      const relevance = typeof item.semanticScore === "number" ? `<span>相似度 ${Math.round(item.semanticScore * 1000) / 10}%</span>` : "";
      const rerank = typeof item.rerankScore === "number" ? `<span>Rerank ${item.rerankScore > 0 ? "相关" : "不相关"}</span>` : "";
      return `<article class="ai-semantic-result" data-semantic-result-index="${index}"><label>${item.entryId ? `<input type="checkbox" data-semantic-entry-id="${esc(item.entryId)}" data-estimated-tokens="${esc(String(item.estimatedTokens ?? 0))}">` : '<span class="ai-semantic-view-only">仅查看</span>'}<span class="ai-semantic-result-copy"><strong>${esc(searchResultTypeLabel(item.type))} · ${esc(item.title)}</strong><small>${lineRange}${matchKinds}${relevance}${rerank}<span>预计 ${esc(String(item.estimatedTokens ?? 0))} Token</span></small><span>${esc(item.snippet || "无原文片段")}</span></span></label><button type="button" data-semantic-locate="${index}">定位来源</button></article>`;
    }).join("")
    : '<p class="ai-semantic-empty">没有找到可展示的结果。</p>';
  host.querySelectorAll('input[data-semantic-entry-id]').forEach((input) => input.addEventListener("change", syncAiSemanticSelectionSummary));
  host.querySelectorAll("[data-semantic-locate]").forEach((button) => button.addEventListener("click", async () => {
    const result = aiSemanticSearchResults[Number(button.dataset.semanticLocate)];
    if (!result) return;
    try {
      setAiSemanticSearchVisible(false);
      await openSearchResult(result);
    } catch (error) {
      toast(error.message, "error");
    }
  }));
  syncAiSemanticSelectionSummary();
}

function renderAiSemanticInjection() {
  const host = $("#ai-semantic-injection");
  const snapshot = state.aiSemanticSnapshot;
  host.classList.toggle("hidden", !snapshot);
  if (!snapshot) {
    host.replaceChildren();
    setAiContextMeter(null);
    return;
  }
  host.innerHTML = `<div><strong>本轮语义快照</strong><span>${esc(String(snapshot.itemCount ?? snapshot.items?.length ?? 0))} 项 · 预计 ${Number(snapshot.estimatedTokens ?? 0).toLocaleString("zh-CN")} Token</span><small>${esc(snapshot.query ?? "")}</small></div><button type="button" aria-label="移除本轮语义快照">×</button>`;
  host.querySelector("button")?.addEventListener("click", () => {
    state.aiSemanticSnapshot = null;
    renderAiSemanticInjection();
    persistActiveAiChatTab();
  });
  setAiContextMeter(null);
}

async function runAiSemanticSearch() {
  if (!state.work) return toast("请先选择作品", "error");
  const query = $("#ai-semantic-query").value.trim();
  if (!query) return toast("请输入自然语言检索问题", "error");
  const button = $("#ai-semantic-search-run");
  button.disabled = true;
  $("#ai-semantic-search-status").textContent = "正在执行主动语义检索……";
  try {
    const selection = state.chapter
      ? $("#chapter-content").value.slice($("#chapter-content").selectionStart, $("#chapter-content").selectionEnd).slice(0, 4_000)
      : "";
    aiSemanticSearchQuery = query;
    const search = await api(`/api/works/${encodeURIComponent(state.work.id)}/semantic-search`, {
      method: "POST",
      body: {
        query,
        types: semanticSearchScopeTypes($("#ai-semantic-scope").value),
        currentChapterId: state.chapter?.id,
        selection: selection || undefined,
        includeKeyword: true
      }
    });
    renderAiSemanticSearchResults(search);
    $("#ai-semantic-search-status").textContent = search.semanticUsed
      ? `${search.results.length} 项融合结果${search.degraded ? `；${search.reason}` : "；已标注 semantic 通道"}`
      : `${search.results.length} 项关键词降级结果；${search.reason}`;
  } catch (error) {
    aiSemanticSearchResults = [];
    renderAiSemanticSearchResults({ results: [] });
    $("#ai-semantic-search-status").textContent = error.message;
    toast(error.message, "error");
  } finally {
    button.disabled = false;
  }
}

async function injectAiSemanticSelection() {
  if (!state.work) return;
  const entryIds = [...$("#ai-semantic-search-results").querySelectorAll('input[data-semantic-entry-id]:checked')]
    .map((input) => input.dataset.semanticEntryId)
    .filter(Boolean);
  if (!entryIds.length) return;
  const button = $("#ai-semantic-inject");
  button.disabled = true;
  try {
    const snapshot = await api(`/api/works/${encodeURIComponent(state.work.id)}/semantic-search/snapshots`, {
      method: "POST",
      body: {
        query: aiSemanticSearchQuery,
        entryIds,
        scope: { types: semanticSearchScopeTypes($("#ai-semantic-scope").value) ?? [] },
        conversationId: state.aiConversationId || undefined
      }
    });
    state.aiSemanticSnapshot = snapshot;
    renderAiSemanticInjection();
    persistActiveAiChatTab();
    setAiSemanticSearchVisible(false);
    toast(`已将 ${snapshot.itemCount} 项语义原文加入本轮上下文`);
  } catch (error) {
    toast(error.message, "error");
    button.disabled = false;
  }
}

function aiReferenceKey(reference) {
  return `${reference.kind}:${reference.id}`;
}

function aiReferenceKindLabel(reference) {
  return ({ character: "角色", setting: "设定", chapter: "章节", "context-settings": "能力" })[reference.kind] ?? "引用";
}

function createAiReferenceChip(reference) {
  const chip = document.createElement("span");
  chip.className = "ai-prompt-reference";
  chip.contentEditable = "false";
  chip.dataset.aiReferenceKey = aiReferenceKey(reference);
  chip.setAttribute("role", "group");
  chip.setAttribute("aria-label", `已引用${aiReferenceKindLabel(reference)} ${reference.name}`);
  const label = document.createElement("span");
  label.textContent = `${aiReferenceKindLabel(reference)} · ${reference.name}`;
  const remove = document.createElement("button");
  remove.type = "button";
  remove.setAttribute("aria-label", `移除引用 ${reference.name}`);
  remove.textContent = "×";
  remove.addEventListener("click", () => {
    state.aiReferences = state.aiReferences.filter((item) => aiReferenceKey(item) !== aiReferenceKey(reference));
    renderAiReferences();
    $("#ai-prompt").focus();
  });
  chip.append(label, remove);
  return chip;
}

function renderAiReferences() {
  const prompt = $("#ai-prompt");
  const references = new Map(state.aiReferences.map((reference) => [aiReferenceKey(reference), reference]));
  prompt.querySelectorAll("[data-ai-reference-key]").forEach((chip) => {
    if (!references.has(chip.dataset.aiReferenceKey)) chip.remove();
  });
  const rendered = new Set([...prompt.querySelectorAll("[data-ai-reference-key]")].map((chip) => chip.dataset.aiReferenceKey));
  for (const reference of state.aiReferences) {
    if (rendered.has(aiReferenceKey(reference))) continue;
    prompt.append(createAiReferenceChip(reference), document.createTextNode(" "));
  }
  setAiContextMeter(null);
}

function renderAiQuickActions() {
  const quickActions = $(".quick-actions");
  const visible = !state.aiRoleplayCharacter && shouldShowAiQuickActions(state.aiPromptSent);
  quickActions.classList.toggle("hidden", !visible);
  quickActions.setAttribute("aria-hidden", String(!visible));
}

function createAiChatFeed() {
  const feed = document.createElement("div");
  feed.className = "ai-feed hidden";
  feed.setAttribute("role", "tabpanel");
  $("#ai-chat-panels").append(feed);
  return feed;
}

function createAiChatTabState(input = {}) {
  const existing = input.conversationId ? aiChatTabManager.findByConversation(input.conversationId) : null;
  if (existing) {
    aiChatTabManager.activate(existing.id);
    return existing;
  }
  const feed = input.feed ?? createAiChatFeed();
  bindAiFeedAutoScroll(feed);
  const tab = aiChatTabManager.open({
    workId: String(state.work?.id ?? ""),
    conversationId: input.conversationId ?? null,
    title: input.title ?? "新对话",
    modelId: input.modelId ?? null,
    selectedModelId: input.selectedModelId ?? null,
    hasImageAttachments: input.hasImageAttachments === true,
    promptSent: input.promptSent === true,
    taskType: input.taskType ?? "chat",
    contextScope: input.contextScope ?? { type: "none" },
    roleplayCharacter: input.roleplayCharacter ?? null,
    roleplayUserCharacter: input.roleplayUserCharacter ?? null,
    citations: input.citations ?? [],
    references: input.references ?? [],
    composer: input.composer ?? { text: "", citations: [], references: [], images: [], semanticSnapshot: null, sceneDirection: "", scenePin: emptyRoleplayScenePin() },
    contextUsage: input.contextUsage ?? null,
    contextWarning: input.contextWarning === true,
    lastMessageAt: input.lastMessageAt ?? null,
    status: input.status ?? "ready",
    unread: input.unread === true,
    feed
  });
  feed.dataset.aiTabId = tab.id;
  feed.setAttribute("aria-labelledby", `ai-chat-tab-${tab.id}`);
  return tab;
}

function persistActiveAiChatTab() {
  const tab = activeAiChatTab();
  if (!tab) return null;
  tab.workId = String(state.work?.id ?? "");
  tab.conversationId = state.aiConversationId;
  tab.title = $("#ai-conversation-title").textContent || tab.title || "新对话";
  tab.modelId = state.aiConversationModelId;
  tab.hasImageAttachments = state.aiConversationHasImages === true;
  tab.selectedModelId = $("#ai-model").value || tab.selectedModelId || null;
  tab.promptSent = state.aiPromptSent;
  tab.taskType = state.aiTaskType;
  tab.contextScope = { ...state.aiContextScope };
  tab.roleplayCharacter = state.aiRoleplayCharacter ? { ...state.aiRoleplayCharacter } : null;
  tab.roleplayUserCharacter = state.aiRoleplayUserCharacter ? { ...state.aiRoleplayUserCharacter } : null;
  setAiChatTabComposerSnapshot(tab, captureAiPromptComposer());
  tab.contextUsage = latestAiContextUsage;
  tab.contextWarning = !$("#ai-context-warning").classList.contains("hidden");
  tab.lastMessageAt = state.aiLastMessageAt;
  return tab;
}

function setAiChatTabComposerSnapshot(tab, snapshot) {
  if (!tab) return;
  tab.citations = snapshot.citations.map((citation) => ({ ...citation }));
  tab.references = snapshot.references.map((reference) => ({ ...reference }));
  tab.composer = {
    text: snapshot.text,
    citations: tab.citations.map((citation) => ({ ...citation })),
    references: tab.references.map((reference) => ({ ...reference })),
    images: normalizeAiChatImageAttachments(snapshot.images),
    semanticSnapshot: snapshot.semanticSnapshot ? structuredClone(snapshot.semanticSnapshot) : null,
    sceneDirection: String(snapshot.sceneDirection ?? ""),
    scenePin: normalizeRoleplayScenePin(snapshot.scenePin)
  };
}

function clearAiChatTabComposer(tab) {
  setAiChatTabComposerSnapshot(tab, {
    text: "",
    citations: [],
    references: [],
    images: [],
    semanticSnapshot: null,
    sceneDirection: "",
    scenePin: normalizeRoleplayScenePin(tab.composer?.scenePin)
  });
}

function applyAiChatTabState(tab) {
  state.aiConversationId = tab.conversationId;
  state.aiConversationModelId = tab.modelId;
  state.aiConversationHasImages = tab.hasImageAttachments === true;
  state.aiPromptSent = tab.promptSent;
  state.aiCitations = tab.citations.map((citation) => ({ ...citation }));
  state.aiReferences = tab.references.map((reference) => ({ ...reference }));
  state.aiImageAttachments = normalizeAiChatImageAttachments(tab.composer?.images);
  state.aiSemanticSnapshot = tab.composer?.semanticSnapshot ? structuredClone(tab.composer.semanticSnapshot) : null;
  state.aiLastMessageAt = tab.lastMessageAt;
  $("#ai-conversation-title").textContent = tab.title || "新对话";
  applyAiConversationTaskType(tab.taskType);
  applyAiConversationContextScope(tab.contextScope);
  applyAiRoleplayCharacter(tab.roleplayCharacter, tab.roleplayUserCharacter);
  const selectedModelId = tab.modelId ?? tab.selectedModelId;
  if (selectedModelId && state.models.some((model) => model.id === selectedModelId)) $("#ai-model").value = selectedModelId;
  syncAiModelPicker();
  setAiPromptText(tab.composer.text);
  restoreAiSceneComposer(tab.composer);
  renderAiCitations();
  renderAiSemanticInjection();
  renderAiReferences();
  renderAiImageAttachments();
  latestAiContextUsage = null;
  setAiContextMeter(tab.contextUsage);
  if (tab.contextWarning) showAiContextWarning();
  else hideAiContextWarning();
  setAiAssistantStatus(tab.status);
  renderAiQuickActions();
  renderAiConversationHistory();
  syncAiRequestControls();
}

function aiChatTabIsReplaceable(tab = activeAiChatTab()) {
  return Boolean(tab
    && !tab.conversationId
    && !tab.promptSent
    && !aiRequestManager.hasActive(tab.id)
    && !(tab.composer?.text || "").trim()
    && !(tab.composer?.citations?.length)
    && !(tab.composer?.references?.length)
    && !(tab.composer?.images?.length)
    && !(tab.composer?.sceneDirection || "").trim()
    && !roleplayScenePinHasContent(tab.composer?.scenePin));
}

function aiChatTabOpeningSlot() {
  const active = activeAiChatTab();
  if (aiChatTabLimit === 1) return { allowed: true, tab: active, replacing: true };
  if (aiChatTabIsReplaceable(active)) return { allowed: true, tab: active, replacing: true };
  if (aiChatTabManager.list().length < aiChatTabLimit) return { allowed: true, tab: null, replacing: false };
  return { allowed: false, tab: null, replacing: false };
}

function interruptAiChatTabForReplacement(slot) {
  if (!slot?.replacing || !slot.tab) return;
  if (aiRequestManager.cancel("已切换到其他对话", slot.tab.id)) {
    toast("当前对话仍在生成，切换后已中断该 turn；已收到的内容仍保留在历史记录中", "warning");
  }
}

function reportAiChatTabLimit() {
  toast(`最多同时打开 ${aiChatTabLimit} 个对话，请先关闭一个再继续`, "warning");
}

function aiChatTabStatusLabel(tab, selected) {
  if (tab.status === "streaming") return "正在生成";
  if (tab.status === "error") return "执行失败";
  if (tab.unread) return "已完成 · 未读";
  return selected ? "当前对话" : "空闲";
}

function renderAiConversationSwitcher() {
  const button = $("#ai-conversation-switcher");
  const list = $("#ai-open-conversation-list");
  if (!button || !list) return;
  const tabs = aiChatTabManager.list();
  const active = activeAiChatTab();
  const multipleEnabled = aiChatTabLimit > 1;
  $("#ai-conversation-title").textContent = active?.title || "新对话";
  $("#ai-open-conversation-count").textContent = String(tabs.length);
  $("#ai-conversation-switcher-limit").textContent = `${tabs.length} / ${aiChatTabLimit}`;
  button.disabled = !multipleEnabled;
  button.setAttribute("aria-disabled", String(!multipleEnabled));
  button.title = multipleEnabled ? "切换打开的对话" : "多会话已通过环境变量关闭";
  button.classList.toggle("has-background-activity", tabs.some((tab) => tab.id !== active?.id && (tab.status === "streaming" || tab.unread)));
  $("#ai-workspace-open").classList.toggle("hidden", !multipleEnabled);
  list.replaceChildren();
  for (const tab of tabs) {
    const selected = tab.id === active?.id;
    const row = document.createElement("div");
    row.className = `ai-open-conversation-row${selected ? " is-active" : ""}`;
    row.setAttribute("role", "listitem");
    const select = document.createElement("button");
    select.type = "button";
    select.className = "ai-open-conversation-select";
    select.dataset.aiSwitcherTabId = tab.id;
    select.setAttribute("aria-current", selected ? "true" : "false");
    const status = document.createElement("span");
    status.className = `ai-chat-tab-status${tab.status === "streaming" ? " is-streaming" : tab.status === "error" ? " is-error" : tab.unread ? " is-unread" : ""}`;
    status.setAttribute("aria-hidden", "true");
    const copy = document.createElement("span");
    copy.className = "ai-open-conversation-copy";
    const title = document.createElement("strong");
    title.textContent = tab.title || "新对话";
    const meta = document.createElement("small");
    meta.textContent = aiChatTabStatusLabel(tab, selected);
    copy.append(title, meta);
    select.append(status, copy);
    select.addEventListener("click", () => {
      activateAiChatTab(tab.id);
      setAiConversationSwitcherVisible(false);
    });
    const close = document.createElement("button");
    close.type = "button";
    close.className = "ai-open-conversation-close";
    close.setAttribute("aria-label", `关闭对话“${tab.title || "新对话"}”`);
    close.textContent = "×";
    close.classList.toggle("hidden", tabs.length === 1);
    close.addEventListener("click", () => closeAiChatTab(tab.id));
    row.append(select, close);
    list.append(row);
  }
}

function setAiConversationSwitcherVisible(visible) {
  const menu = $("#ai-conversation-switcher-menu");
  const button = $("#ai-conversation-switcher");
  if (!menu || !button) return;
  const nextVisible = Boolean(visible && aiChatTabLimit > 1);
  menu.classList.toggle("hidden", !nextVisible);
  button.setAttribute("aria-expanded", String(nextVisible));
  if (nextVisible) renderAiConversationSwitcher();
}

function setAiConversationWorkspaceVisible(visible) {
  const mobileWorkspace = isPhoneClient() || isMobileViewport();
  aiConversationWorkspaceOpen = Boolean(visible);
  panelLayout.aiCollapsed = aiConversationWorkspaceOpen ? false : mobileWorkspace;
  $("#app").classList.toggle("ai-workspace-mode", aiConversationWorkspaceOpen);
  $(".ai-panel").classList.toggle("is-conversation-workspace", aiConversationWorkspaceOpen);
  $("#ai-assistant-entry").classList.toggle("active", aiConversationWorkspaceOpen);
  $("#ai-assistant-entry").setAttribute("aria-expanded", String(aiConversationWorkspaceOpen));
  applyPanelLayout(true);
  $("#ai-chat-tabs").classList.add("hidden");
  $("#ai-panel-resize").setAttribute("aria-hidden", String(aiConversationWorkspaceOpen));
  setAiConversationSwitcherVisible(false);
  renderAiChatTabs();
  $("#ai-panel-toggle").textContent = aiConversationWorkspaceOpen ? "×" : (panelLayout.aiCollapsed ? "‹" : "›");
  $("#ai-panel-toggle").setAttribute("aria-label", aiConversationWorkspaceOpen ? "关闭创作助手全屏面板" : (panelLayout.aiCollapsed ? "展开创作助手" : "收起创作助手"));
  if (aiConversationWorkspaceOpen) {
    window.requestAnimationFrame(() => $("#ai-prompt").focus({ preventScroll: true }));
  }
}

function applyAiChatTabLimit(value) {
  aiChatTabLimit = normalizeAiChatTabLimit(value);
  const singleSession = aiChatTabLimit === 1;
  $(".ai-panel").classList.toggle("is-single-conversation", singleSession);
  if (singleSession) {
    setAiConversationSwitcherVisible(false);
  }
  renderAiChatTabs();
}

function renderAiChatTabs() {
  const host = $("#ai-chat-tabs");
  if (!host) return;
  const tabs = aiChatTabManager.list();
  const active = activeAiChatTab();
  host.replaceChildren();
  for (const tab of tabs) {
    const item = document.createElement("div");
    item.className = "ai-chat-tab";
    item.setAttribute("role", "presentation");
    const button = document.createElement("button");
    const selected = tab.id === active?.id;
    button.type = "button";
    button.id = `ai-chat-tab-${tab.id}`;
    button.className = "ai-chat-tab-select";
    button.dataset.aiTabId = tab.id;
    button.setAttribute("role", "tab");
    button.setAttribute("aria-selected", String(selected));
    button.setAttribute("aria-controls", tab.feed.id || `ai-chat-panel-${tab.id}`);
    button.tabIndex = selected ? 0 : -1;
    button.title = tab.title || "新对话";
    const status = document.createElement("span");
    status.className = `ai-chat-tab-status${tab.status === "streaming" ? " is-streaming" : tab.status === "error" ? " is-error" : tab.unread ? " is-unread" : ""}`;
    status.setAttribute("aria-hidden", "true");
    const title = document.createElement("span");
    title.textContent = tab.title || "新对话";
    button.append(status, title);
    button.addEventListener("click", () => activateAiChatTab(tab.id));
    button.addEventListener("keydown", (event) => {
      const index = tabs.findIndex((candidate) => candidate.id === tab.id);
      const offset = event.key === "ArrowLeft" ? -1 : event.key === "ArrowRight" ? 1 : 0;
      if (!offset) return;
      event.preventDefault();
      const target = tabs[(index + offset + tabs.length) % tabs.length];
      activateAiChatTab(target.id);
      $("#ai-conversation-switcher").focus();
    });
    const close = document.createElement("button");
    close.type = "button";
    close.className = "ai-chat-tab-close";
    close.dataset.aiTabClose = tab.id;
    close.setAttribute("aria-label", `关闭对话页签“${tab.title || "新对话"}”`);
    close.title = "关闭页签";
    close.textContent = "×";
    close.classList.toggle("hidden", tabs.length === 1);
    close.addEventListener("click", () => closeAiChatTab(tab.id));
    item.append(button, close);
    host.append(item);
  }
  renderAiConversationSwitcher();
}

function activateAiChatTab(tabId, { persistCurrent = true, force = false } = {}) {
  const current = activeAiChatTab();
  if (!force && current?.id === tabId) return current;
  if (persistCurrent) persistActiveAiChatTab();
  const tab = aiChatTabManager.activate(tabId);
  if (!tab) return null;
  tab.unread = false;
  for (const feed of $("#ai-chat-panels").querySelectorAll(".ai-feed")) {
    feed.classList.toggle("hidden", feed !== tab.feed);
    feed.id = feed === tab.feed ? "ai-feed" : `ai-chat-panel-${feed.dataset.aiTabId}`;
  }
  tab.feed.classList.remove("hidden");
  applyAiChatTabState(tab);
  renderAiChatTabs();
  return tab;
}

function closeAiChatTab(tabId) {
  const tab = aiChatTabManager.get(tabId);
  if (!tab) return;
  const wasActive = isActiveAiChatTab(tab);
  if (wasActive) persistActiveAiChatTab();
  if (aiRequestManager.cancel("对话页签已关闭", tab.id)) {
    toast(`“${tab.title || "新对话"}”仍在生成，关闭页签已中断该 turn；其他页签不受影响`, "warning");
  }
  const { active } = aiChatTabManager.close(tab.id);
  tab.feed.remove();
  if (!wasActive) {
    renderAiChatTabs();
    return;
  }
  const next = active ?? createAiChatTabState();
  activateAiChatTab(next.id, { persistCurrent: false, force: true });
}

function resetAiChatTabs() {
  aiRequestManager.cancelAll("已重置 Agent 对话页签");
  setAiConversationSwitcherVisible(false);
  setAiConversationWorkspaceVisible(false);
  const panels = $("#ai-chat-panels");
  panels.replaceChildren();
  aiChatTabManager.reset();
  const tab = createAiChatTabState();
  resetAiFeed(tab.feed, tab.roleplayCharacter, tab.roleplayUserCharacter);
  activateAiChatTab(tab.id, { persistCurrent: false, force: true });
}

function initializeAiChatTabs() {
  const feed = $("#ai-feed");
  aiChatTabManager.reset();
  const tab = createAiChatTabState({ feed });
  feed.dataset.aiTabId = tab.id;
  activateAiChatTab(tab.id, { persistCurrent: false, force: true });
}

function attachMessageHeading(message, label, createdAt = new Date().toISOString(), tab = activeAiChatTab()) {
  const timestamp = createdAt || new Date().toISOString();
  const previousCreatedAt = tab?.lastMessageAt ?? state.aiLastMessageAt;
  const heading = document.createElement("span");
  heading.className = "message-heading";
  const role = document.createElement("span");
  role.textContent = label;
  const time = document.createElement("time");
  time.dateTime = timestamp;
  time.textContent = formatAiMessageTime(timestamp);
  heading.append(role, time);
  message.prepend(heading);
  message.dataset.createdAt = timestamp;
  message.dataset.previousCreatedAt = previousCreatedAt ?? "";
  if (tab) tab.lastMessageAt = timestamp;
  if (isActiveAiChatTab(tab)) state.aiLastMessageAt = timestamp;
  return heading;
}

function updateMessageCreatedAt(message, createdAt) {
  if (!message || !createdAt) return;
  const time = message.querySelector(".message-heading time");
  if (!time) return;
  time.dateTime = createdAt;
  time.textContent = formatAiMessageTime(createdAt);
  message.dataset.createdAt = createdAt;
  const tab = aiChatTabManager.get(message.closest(".ai-feed")?.dataset.aiTabId);
  if (message === tab?.feed.lastElementChild) {
    tab.lastMessageAt = createdAt;
    if (isActiveAiChatTab(tab)) state.aiLastMessageAt = createdAt;
  }
}

function resetAiFeed(
  feed = $("#ai-feed"),
  roleplayCharacter = state.aiRoleplayCharacter,
  roleplayUserCharacter = state.aiRoleplayUserCharacter
) {
  const tab = aiChatTabManager.get(feed?.dataset.aiTabId);
  if (tab) tab.lastMessageAt = null;
  if (isActiveAiChatTab(tab)) state.aiLastMessageAt = null;
  const roleplayName = roleplayCharacter?.name;
  const roleplayUserName = roleplayUserCharacter?.name;
  feed.innerHTML = roleplayName
    ? `<div class="assistant-message"><span class="message-heading"><span>${esc(roleplayName)}</span></span><div class="message-body"><p>正在扮演 ${esc(roleplayName)}。${roleplayUserName ? `你将以 ${esc(roleplayUserName)} 的身份与我互动。` : "我可以通过角色卡、人物关系、知情设定和故事正文回答。"}</p></div></div>`
    : '<div class="assistant-message"><span class="message-heading"><span>助手</span></span><div class="message-body"><p>选择章节和模型后即可开始问答；所有引用都基于已保存正文。</p></div></div>';
}

function aiAssistantLabel(suffix = "", roleplayCharacter = state.aiRoleplayCharacter) {
  const name = roleplayCharacter?.name || "助手";
  return suffix ? `${name} · ${suffix}` : name;
}

function aiUserLabel(roleplayUserCharacter = state.aiRoleplayUserCharacter) {
  return roleplayUserCharacter?.name || "作者";
}

function createAiContextCompactionDivider({ kind = "conversation", ariaLabel = "当前上下文已压缩", title = "" } = {}) {
  const divider = document.createElement("div");
  divider.className = "ai-context-compaction-divider";
  divider.dataset.contextCompaction = kind;
  divider.dataset.testid = "ai-context-compaction-divider";
  divider.setAttribute("role", "separator");
  divider.setAttribute("aria-label", ariaLabel);
  if (title) divider.title = title;
  divider.innerHTML = "<span>—— 当前上下文已压缩 ——</span>";
  return divider;
}

function appendAiContextCompactionDivider(kind, before = null, feed = $("#ai-feed")) {
  const divider = createAiContextCompactionDivider({ kind });
  if (before?.parentElement === feed) feed.insertBefore(divider, before);
  else feed.append(divider);
  scrollAiFeedToBottom(feed);
  return divider;
}

function renderConversationCompactionDivider(compactedMessageCount, totalMessageCount = null, feed = $("#ai-feed"), conversation = null) {
  feed.querySelector('[data-context-compaction="conversation"]')?.remove();
  const compactedCount = Math.max(0, Number(compactedMessageCount) || 0);
  if (compactedCount === 0) return null;
  const messages = [...feed.querySelectorAll("[data-message-id]")];
  const current = conversation ?? state.aiConversations.find((item) => item.id === state.aiConversationId);
  const totalCount = Math.max(messages.length, Number(totalMessageCount ?? current?.messageCount) || messages.length);
  const loadedOffset = Math.max(0, totalCount - messages.length);
  const boundaryIndex = Math.max(0, Math.min(messages.length, compactedCount - loadedOffset));
  return appendAiContextCompactionDivider("conversation", messages[boundaryIndex] ?? null, feed);
}

function findAiRetryUserMessage(message) {
  const feed = message.closest(".ai-feed");
  if (!feed) return null;
  const messages = [...feed.children].filter((candidate) => candidate.matches(".user-message, .assistant-message"));
  const messageIndex = messages.indexOf(message);
  for (let index = messageIndex - 1; index >= 0; index -= 1) {
    if (messages[index].classList.contains("user-message")) return messages[index];
  }
  return null;
}

function aiMessageCitations(message) {
  try {
    const citations = JSON.parse(message.dataset.aiCitations ?? "[]");
    return Array.isArray(citations) ? citations : [];
  } catch {
    return [];
  }
}

function aiMessageImageAttachments(message) {
  try {
    const ids = JSON.parse(message.dataset.aiImageAttachmentIds ?? "[]");
    return normalizeAiChatImageAttachments(Array.isArray(ids) ? ids.map((id) => ({ id })) : []);
  } catch {
    return [];
  }
}

async function retryAiMessage(message) {
  const sourceTab = aiChatTabManager.get(message.closest(".ai-feed")?.dataset.aiTabId);
  const userMessage = findAiRetryUserMessage(message);
  const prompt = userMessage?.dataset.copyText ?? "";
  const sceneDirection = userMessage?.dataset.sceneDirection ?? "";
  const userMessageId = userMessage?.dataset.messageId ?? "";
  if (!sourceTab?.conversationId || !userMessageId || !(prompt.trim() || sceneDirection.trim())) {
    toast("找不到需要重试的用户指令", "error");
    return;
  }
  if (aiRequestManager.hasActive(sourceTab.id)) {
    toast("当前对话仍在生成回复，请等待完成或取消后再重试", "error");
    return;
  }
  if (!isActiveAiChatTab(sourceTab)) activateAiChatTab(sourceTab.id, { persistCurrent: false, force: true });
  await sendAiWithOptions({
    retry: {
      message,
      prompt,
      sceneDirection,
      citations: aiMessageCitations(userMessage),
      images: aiMessageImageAttachments(userMessage),
      userMessageId
    }
  });
}

function clearAiRetryComposer() {
  clearAiPromptComposer();
}

function prepareAiRetryState(tab, modelId) {
  tab.modelId = modelId;
  tab.selectedModelId = modelId;
  tab.promptSent = true;
  clearAiChatTabComposer(tab);
  if (isActiveAiChatTab(tab)) {
    state.aiConversationModelId = modelId;
    state.aiPromptSent = true;
    syncAiTaskOptions();
    renderAiRoleplayCharacterSelect();
    renderAiQuickActions();
    clearAiRetryComposer();
  }
}

function aiRetryStreamRequestBody(body, retry) {
  return retry?.userMessageId
    ? { ...body, currentMessageId: retry.userMessageId }
    : body;
}

function renderMessageCardActions(message) {
  let actions = message.querySelector(".message-card-actions");
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "message-card-actions";
    message.append(actions);
  }
  actions.replaceChildren();
  const hasCopyValue = Object.hasOwn(message.dataset, "rawMarkdown") || Object.hasOwn(message.dataset, "copyText");
  if (hasCopyValue) {
    const copy = document.createElement("button");
    copy.type = "button";
    copy.className = "message-copy-button";
    const isUserMessage = message.classList.contains("user-message");
    copy.setAttribute("aria-label", isUserMessage ? "复制用户指令" : "复制 AI 回复");
    copy.innerHTML = '<svg class="message-action-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/></svg><span>复制</span>';
    const copyLabel = copy.querySelector("span");
    copy.addEventListener("click", async () => {
      try {
        await copyAiRawMarkdown(message.dataset.rawMarkdown ?? message.dataset.copyText ?? "");
        copyLabel.textContent = "已复制";
        window.setTimeout(() => { copyLabel.textContent = "复制"; }, 1200);
      } catch (error) {
        toast(error.message, "error");
      }
    });
    actions.append(copy);
  }
  if (message.dataset.status === "failed" && message.classList.contains("assistant-message")) {
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "message-retry-button";
    retry.setAttribute("aria-label", "重试");
    retry.innerHTML = '<svg class="message-action-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8 8 0 0 0-14.7-4L4 9"/><path d="M4 4v5h5"/><path d="M4 13a8 8 0 0 0 14.7 4L20 15"/><path d="M20 20v-5h-5"/></svg><span>重试</span>';
    retry.addEventListener("click", () => {
      retry.disabled = true;
      void retryAiMessage(message).finally(() => {
        if (retry.isConnected) retry.disabled = false;
      });
    });
    actions.append(retry);
  } else if (message.dataset.messageId && message.classList.contains("assistant-message")) {
    const fork = document.createElement("button");
    fork.type = "button";
    fork.className = "message-fork-button";
    fork.setAttribute("aria-label", "从此消息续写为新对话");
    fork.innerHTML = '<svg class="message-action-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="5" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="12" cy="19" r="2"/><path d="M6 7v2a4 4 0 0 0 4 4h4a4 4 0 0 0 4-4V7M12 13v4"/></svg><span>从此续写</span>';
    const forkRequestId = createAiIdempotencyKey();
    fork.addEventListener("click", async () => {
      const openingSlot = aiChatTabOpeningSlot();
      if (!openingSlot.allowed) {
        reportAiChatTabLimit();
        return;
      }
      fork.disabled = true;
      try {
        const sourceTab = aiChatTabManager.get(message.closest(".ai-feed")?.dataset.aiTabId);
        if (!sourceTab?.conversationId) throw new Error("无法确定消息所属对话");
        const conversation = await api(`/api/ai-conversations/${sourceTab.conversationId}/fork`, {
          method: "POST",
          body: { messageId: message.dataset.messageId, requestId: forkRequestId }
        });
        upsertAiConversationSummary(conversation);
        await openAiConversation(conversation.id);
        toast("已从所选消息创建分支对话");
      } catch (error) {
        fork.disabled = false;
        toast(error.message, "error");
      }
    });
    actions.append(fork);
  }
  const copyAction = actions.querySelector(".message-copy-button");
  if (copyAction) actions.append(copyAction);
  message.classList.toggle("has-message-actions", actions.childElementCount > 0);
}

function attachAssistantCopyAction(message, rawMarkdown) {
  message.dataset.rawMarkdown = String(rawMarkdown ?? "");
  renderMessageCardActions(message);
}

function attachUserCopyAction(message, text) {
  message.dataset.copyText = String(text ?? "");
  renderMessageCardActions(message);
}

function attachMessageIdentity(message, messageId) {
  if (!messageId) return;
  message.dataset.messageId = messageId;
  renderMessageCardActions(message);
}

