const aiFeedScrollFrames = new WeakMap();
const aiFeedAutoScrollStates = new WeakMap();
const aiFeedScrollBindings = new WeakSet();
const aiProcessScrollFrames = new WeakMap();
const AI_FEED_BOTTOM_THRESHOLD_PX = 24;
let markdownTableMenuTarget = null;
let markdownTableMenuTrigger = null;

function closeMarkdownTableMenu(restoreFocus = false) {
  const trigger = markdownTableMenuTrigger;
  $("#markdown-table-menu").classList.add("hidden");
  markdownTableMenuTarget = null;
  markdownTableMenuTrigger = null;
  if (restoreFocus && trigger?.isConnected) trigger.focus();
}

function setMarkdownTableWrapping(table, wrapping) {
  table.classList.toggle("is-wrapping", wrapping);
  table.setAttribute("aria-label", wrapping ? "Markdown 表格，内容自动换行" : "Markdown 表格，内容不换行");
}

function openMarkdownTableMenu(header, clientX, clientY) {
  const table = header.closest(".markdown-table-scroll");
  if (!table) return;
  if (header.closest(".is-streaming")) {
    toast("回复生成完成后可以设置表格换行");
    return;
  }
  closeChapterTypeMenu();
  closeLineCitationMenu();
  markdownTableMenuTarget = table;
  markdownTableMenuTrigger = header;
  const menu = $("#markdown-table-menu");
  const toggle = $("#markdown-table-wrap-toggle");
  toggle.setAttribute("aria-checked", String(table.classList.contains("is-wrapping")));
  menu.classList.remove("hidden");
  const menuRect = menu.getBoundingClientRect();
  const headerRect = header.getBoundingClientRect();
  const anchorX = clientX > 0 ? clientX : headerRect.left;
  const anchorY = clientY > 0 ? clientY : headerRect.bottom;
  menu.style.left = `${Math.max(8, Math.min(anchorX, window.innerWidth - menuRect.width - 8))}px`;
  menu.style.top = `${Math.max(8, Math.min(anchorY, window.innerHeight - menuRect.height - 8))}px`;
  toggle.focus();
}

function aiFeedIsNearBottom(feed) {
  if (!feed.clientHeight) return true;
  return feed.scrollHeight - feed.scrollTop - feed.clientHeight <= AI_FEED_BOTTOM_THRESHOLD_PX;
}

function bindAiFeedAutoScroll(feed) {
  if (!feed || aiFeedScrollBindings.has(feed)) return;
  const update = () => {
    const shouldFollow = aiFeedIsNearBottom(feed);
    aiFeedAutoScrollStates.set(feed, shouldFollow);
    if (shouldFollow) return;
    const currentFrame = aiFeedScrollFrames.get(feed);
    if (currentFrame === undefined) return;
    window.cancelAnimationFrame(currentFrame);
    aiFeedScrollFrames.delete(feed);
  };
  feed.addEventListener("scroll", update, { passive: true });
  aiFeedScrollBindings.add(feed);
  update();
}

function scrollAiFeedToBottom(feed = $("#ai-feed"), { force = false } = {}) {
  bindAiFeedAutoScroll(feed);
  if (force) aiFeedAutoScrollStates.set(feed, true);
  if (!aiFeedAutoScrollStates.get(feed)) return;
  feed.scrollTop = feed.scrollHeight;
  const currentFrame = aiFeedScrollFrames.get(feed);
  if (currentFrame !== undefined) window.cancelAnimationFrame(currentFrame);
  const nextFrame = window.requestAnimationFrame(() => {
    feed.scrollTop = feed.scrollHeight;
    aiFeedScrollFrames.delete(feed);
  });
  aiFeedScrollFrames.set(feed, nextFrame);
}

function scrollAiProcessStepsToBottom(message) {
  const scroll = () => {
    message.querySelectorAll(".ai-process-step-body").forEach((body) => {
      body.scrollTop = body.scrollHeight;
    });
  };
  scroll();
  const currentFrame = aiProcessScrollFrames.get(message);
  if (currentFrame !== undefined) window.cancelAnimationFrame(currentFrame);
  const nextFrame = window.requestAnimationFrame(() => {
    scroll();
    aiProcessScrollFrames.delete(message);
  });
  aiProcessScrollFrames.set(message, nextFrame);
}

function formatAiToolCallTime(value) {
  if (!value) return "历史记录未保存";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "时间记录无效";
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  }).format(date);
}

const AI_TOOL_CALL_COPY_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="8" y="8" width="12" height="12" rx="2"></rect><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"></path></svg>';
const AI_TOOL_CALL_COPIED_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m5 12 4 4L19 6"></path></svg>';

function setAiToolCallCopyButtonState(button, copied) {
  const label = button.dataset.copyLabel ?? "代码块";
  const nextState = copied ? "copied" : "idle";
  if (button.dataset.copyState !== nextState) button.innerHTML = copied ? AI_TOOL_CALL_COPIED_ICON : AI_TOOL_CALL_COPY_ICON;
  button.dataset.copyState = nextState;
  button.classList.toggle("is-copied", copied);
  button.setAttribute("aria-label", copied ? `${label}已复制` : `复制${label}`);
  button.title = copied ? "已复制" : `复制${label}`;
}

async function copyAiToolCallCode(button) {
  const targetId = button.dataset.copyTarget;
  const target = targetId ? document.getElementById(targetId) : null;
  if (!target) return;
  try {
    await copyAiRawMarkdown(target.textContent);
    setAiToolCallCopyButtonState(button, true);
    window.setTimeout(() => {
      if (button.isConnected && button.dataset.copyState === "copied") setAiToolCallCopyButtonState(button, false);
    }, 1200);
  } catch (error) {
    toast(error.message, "error");
  }
}

function openAiToolCallDetail(toolCall) {
  const name = String(toolCall?.name ?? "unknown");
  const status = toolCall?.status === "failed" ? "调用失败" : "调用成功";
  const calledAt = String(toolCall?.calledAt ?? "");
  $("#ai-tool-call-status").textContent = status;
  $("#ai-tool-call-title").textContent = `${AI_TOOL_DISPLAY_NAMES[name] ?? name} · ${name}`;
  $("#ai-tool-call-name").textContent = name;
  $("#ai-tool-call-description").textContent = AI_TOOL_DESCRIPTIONS[name] ?? "未登记此工具函数的用途说明。";
  const time = $("#ai-tool-call-time");
  time.textContent = formatAiToolCallTime(calledAt);
  if (calledAt && !Number.isNaN(new Date(calledAt).getTime())) time.dateTime = new Date(calledAt).toISOString();
  else time.removeAttribute("datetime");
  const resultDetails = formatAiToolCallResult(toolCall?.result);
  $("#ai-tool-call-arguments").textContent = JSON.stringify(toolCall?.arguments ?? {}, null, 2);
  $("#ai-tool-call-result-length").textContent = `${resultDetails.characterCount.toLocaleString("zh-CN")} 字符`;
  $("#ai-tool-call-result").textContent = resultDetails.text;
  document.querySelectorAll("[data-ai-tool-call-copy]").forEach((button) => setAiToolCallCopyButtonState(button, false));
  $("#ai-tool-call-dialog").showModal();
}

function createAiToolCallButton(toolCall) {
  const name = String(toolCall?.name ?? "unknown");
  if (name === "propose_write_plan" || name === "ask_user_question") {
    const card = createInteractiveToolCard(toolCall, AI_TOOL_CARD_ACTIONS);
    if (card) return card;
  }
  const button = document.createElement("button");
  button.type = "button";
  button.className = `ai-tool-call-summary${toolCall?.status === "failed" ? " is-failed" : ""}`;
  button.setAttribute("aria-haspopup", "dialog");
  button.textContent = toolCall?.status === "failed" ? `调用 ${name} 工具失败` : `调用了 ${name} 工具`;
  button.title = AI_TOOL_DISPLAY_NAMES[name] ?? name;
  button.addEventListener("click", () => openAiToolCallDetail(toolCall));
  return button;
}

