// AI 可写工具：审批卡片动作、修改计划详情、撤销与用户提问
// ---------------------------------------------------------------------------

let aiWritePlanDialogPlanId = null;
let aiWritePlanDialogBusy = false;
let currentPlanDialogDetail = null;
let currentPlanDialogFocusConfirm = false;
let aiQuestionDialogQuestionId = null;
let currentAiQuestionDialogView = null;
let aiQuestionDialogBusy = false;
const aiQuestionContinuationTabIds = new Set();
let autoOpenedQuestionIds = new Set();
const aiApprovalCenterState = { status: "" };

/** 消息流中交互工具卡片绑定的动作：全部先取服务端最新状态，再弹窗确认。 */
const AI_TOOL_CARD_ACTIONS = {
  openPlanDetail(planId) {
    openAiWritePlanDetail(planId).catch((error) => toast(`审批详情加载失败：${error.message}`, "error"));
  },
  confirmPlan(planId) {
    openAiWritePlanDetail(planId, { focusConfirm: true }).catch((error) => toast(`审批详情加载失败：${error.message}`, "error"));
  },
  rejectPlan(planId) {
    decideAiWritePlan(planId, "reject").catch((error) => toast(`拒绝失败：${error.message}`, "error"));
  },
  openQuestionDialog(questionId) {
    openAiUserQuestionDialog(questionId).catch((error) => toast(`提问加载失败：${error.message}`, "error"));
  },
  rejectQuestion(questionId) {
    respondAiUserQuestion(questionId, { action: "reject" }).catch((error) => toast(`操作失败：${error.message}`, "error"));
  },
  openApprovalCenter() {
    openAiApprovalCenter();
  }
};

/** 流式收到交互式可写工具调用时的提示与自动弹出提问。 */
function handleInteractiveToolCallEvent(toolCall) {
  const name = String(toolCall?.name ?? "");
  if (name === "propose_write_plan") {
    if (toolCall.status === "failed") {
      const message = String(parseInteractiveToolPayload(toolCall)?.error?.message ?? "未知错误");
      toast(`AI 的写入审批提交失败：${message}`, "error");
      return;
    }
    const payload = parseInteractiveToolPayload(toolCall);
    const targets = Array.isArray(payload?.plan?.targets) ? payload.plan.targets.join("、") : "待确认操作";
    const summary = String(payload?.plan?.aiSummary ?? "");
    toast(`AI 提交了写入审批：${targets}${summary ? ` · ${summary}` : ""}`);
    return;
  }
  if (name !== "ask_user_question" || toolCall.status === "failed") return;
  const question = toolCall.result?.question;
  if (!question?.id) return;
  cacheAiQuestionView(question);
  const questionId = String(question.id);
  if (autoOpenedQuestionIds.has(questionId)) return;
  autoOpenedQuestionIds.add(questionId);
  // 直接弹出回答框等待作者选择；不会预填任何答案。
  openAiUserQuestionDialog(questionId).catch(() => undefined);
}

function questionsEndpoint(path) {
  return `/api/works/${state.work.id}/ai/questions${path}`;
}

function plansEndpoint(path) {
  return `/api/works/${state.work.id}/ai/write-plans${path}`;
}

async function fetchAiWritePlanDetail(planId) {
  const detail = await api(plansEndpoint(`/${encodeURIComponent(String(planId))}`));
  cacheAiWritePlanDetail(detail);
  return detail;
}

async function decideAiWritePlan(planId, action) {
  const buttonLabel = action === "confirm" ? "确认执行" : "拒绝";
  const targetButton = $(action === "confirm" ? "#ai-write-plan-confirm" : "#ai-write-plan-reject");
  if (targetButton?.disabled || aiWritePlanDialogBusy) return;
  if (targetButton) targetButton.disabled = true;
  aiWritePlanDialogBusy = true;
  try {
    const detail = await api(plansEndpoint(`/${encodeURIComponent(String(planId))}/${action}`), { method: "POST" });
    cacheAiWritePlanDetail(detail);
    toast(action === "confirm"
      ? `已执行 AI 写入审批：${detail.aiSummary}`
      : `已拒绝该写入审批，未产生任何写入`);
    if ($("#ai-write-plan-dialog").open && aiWritePlanDialogPlanId === String(detail.id)) {
      applyPlanDetailToDialog(detail);
    }
    if ($("#ai-approval-center-dialog").open) loadAiApprovalCenterPlans().catch(() => undefined);
    return detail;
  } catch (error) {
    // 已被处理（409）等冲突也需要刷新展示的明细状态。
    try {
      const fresh = await fetchAiWritePlanDetail(planId);
      if ($("#ai-write-plan-dialog").open && aiWritePlanDialogPlanId === String(planId)) applyPlanDetailToDialog(fresh);
      else if (targetButton) targetButton.disabled = false;
    } catch {
      if (targetButton) targetButton.disabled = false;
    }
    throw new Error(`${buttonLabel}失败：${error.message}`);
  } finally {
    aiWritePlanDialogBusy = false;
  }
}

async function undoAiWritePlan(planId) {
  if (aiWritePlanDialogBusy) return;
  const button = $("#ai-write-plan-undo");
  button.disabled = true;
  try {
    const undoPlan = await api(plansEndpoint(`/${encodeURIComponent(String(planId))}/undo`), { method: "POST" });
    cacheAiWritePlanDetail(undoPlan);
    toast("已创建撤销审批，请在新弹窗中单独确认执行");
    await openAiWritePlanDetail(undoPlan.id);
  } catch (error) {
    toast(`创建撤销审批失败：${error.message}`, "error");
    button.disabled = false;
  }
}

function applyPlanDetailToDialog(detail) {
  currentPlanDialogDetail = detail;
  aiWritePlanDialogPlanId = String(detail.id);
  $("#ai-write-plan-body").innerHTML = renderWritePlanDetailMarkup(detail);
  const isPending = detail.status === "pending";
  const canUndo = Boolean(detail.undoAvailable) && detail.status === "executed";
  $("#ai-write-plan-confirm").classList.toggle("hidden", !isPending);
  $("#ai-write-plan-reject").classList.toggle("hidden", !isPending);
  $("#ai-write-plan-undo").classList.toggle("hidden", !canUndo);
  $("#ai-write-plan-confirm").disabled = false;
  $("#ai-write-plan-reject").disabled = false;
  $("#ai-write-plan-undo").disabled = false;
  if (isPending && currentPlanDialogFocusConfirm) {
    $("#ai-write-plan-dialog").querySelector(".card-actions")?.scrollIntoView({ block: "end" });
  }
}

async function openAiWritePlanDetail(planId, options = {}) {
  currentPlanDialogFocusConfirm = options.focusConfirm === true;
  const dialog = $("#ai-write-plan-dialog");
  if (!dialog.open) dialog.showModal();
  $("#ai-write-plan-body").innerHTML = '<p class="usage-measurement-note">正在加载系统生成的完整修改明细……</p>';
  try {
    const detail = await fetchAiWritePlanDetail(planId);
    applyPlanDetailToDialog(detail);
  } catch (error) {
    $("#ai-write-plan-body").innerHTML = `<p class="usage-measurement-note">加载失败：${esc(error.message)}</p>`;
    throw error;
  }
}

async function loadAiApprovalCenterPlans() {
  const statusQuery = aiApprovalCenterState.status ? `?status=${encodeURIComponent(aiApprovalCenterState.status)}&limit=50` : "?limit=50";
  const [planPayload, questionPayload] = await Promise.all([
    api(plansEndpoint(statusQuery)),
    api(questionsEndpoint(statusQuery))
  ]);
  const plans = Array.isArray(planPayload) ? planPayload : (Array.isArray(planPayload?.plans) ? planPayload.plans : []);
  const questions = Array.isArray(questionPayload) ? questionPayload : (Array.isArray(questionPayload?.questions) ? questionPayload.questions : []);
  $("#ai-approval-list-host").innerHTML = renderApprovalCenterRows(plans, questions);
}

function openAiApprovalCenter() {
  const dialog = $("#ai-approval-center-dialog");
  if (!dialog.open) dialog.showModal();
  $("#ai-approval-center-toggle").setAttribute("aria-expanded", "true");
  $("#ai-approval-list-host").innerHTML = '<p class="usage-measurement-note">正在加载审批记录……</p>';
  loadAiApprovalCenterPlans().catch((error) => {
    $("#ai-approval-list-host").innerHTML = `<p class="usage-measurement-note">加载失败：${esc(error.message)}</p>`;
  });
}

async function fetchAiUserQuestion(questionId) {
  const question = await api(questionsEndpoint(`/${encodeURIComponent(String(questionId))}`));
  cacheAiQuestionView(question);
  return question;
}

function syncAiQuestionOptionPresentation() {
  const checked = document.querySelector('input[name="ai-question-choice"]:checked');
  for (const label of document.querySelectorAll(".ai-question-option-item")) {
    const input = label.querySelector('input[name="ai-question-choice"]');
    const isSelected = Boolean(input && checked === input);
    label.classList.toggle("is-selected", isSelected);
    label.classList.toggle("is-recommended", label.dataset.recommended === "true" && (!checked || isSelected));
  }
}

function syncAiQuestionAnswerCount() {
  const input = $("#ai-question-custom-answer");
  const maximum = Number(input.maxLength) || 3000;
  $("#ai-question-answer-count").textContent = `已填写 ${input.value.length} / ${maximum}`;
}

function renderAiUserQuestionOptions(question) {
  const host = $("#ai-question-options");
  const customInput = $("#ai-question-custom-answer");
  const isPending = question.status === "pending";
  host.replaceChildren();
  for (const option of question.options ?? []) {
    const label = document.createElement("label");
    label.className = "ai-question-option-item";
    label.dataset.recommended = String(option.recommended === true);
    const input = document.createElement("input");
    input.type = "radio";
    input.name = "ai-question-choice";
    input.value = String(option.index);
    input.checked = question.selectedOption === option.index;
    input.disabled = !isPending;
    const span = document.createElement("span");
    span.textContent = `${option.recommended ? "（最推荐）" : ""}${option.label}`;
    label.append(input, span);
    host.append(label);
  }
  const customLabel = document.createElement("label");
  customLabel.className = "ai-question-option-item ai-question-custom-choice";
  const customRadio = document.createElement("input");
  customRadio.type = "radio";
  customRadio.name = "ai-question-choice";
  customRadio.value = "custom";
  customRadio.checked = question.selectedOption == null && question.isCustomAnswer === true;
  customRadio.disabled = !isPending;
  const customText = document.createElement("span");
  customText.textContent = "自定义回答";
  customLabel.append(customRadio, customText);
  host.append(customLabel);
  customInput.value = question.customAnswer ?? (question.selectedOption == null && question.isCustomAnswer ? (question.answerText ?? "") : "");
  customInput.disabled = !isPending;
  syncAiQuestionAnswerCount();
  syncAiQuestionOptionPresentation();
  // 提交按钮由选择状态驱动：待回答且已选择（或输入）时才可提交。
  if (isPending) syncAiQuestionSubmitState();
  else $("#ai-question-submit").disabled = true;
  $("#ai-question-skip").disabled = !isPending;
  $("#ai-question-expiry").textContent = isPending
    ? `请选择一个预设选项，或填写自定义回答后提交。有效期至 ${aiFormatDateTime(question.expiresAt)}；过期未回答将自动失效，AI 不允许在未获得回答时自行假定答案。`
    : `该问题当前状态：${question.statusLabel}${question.answerText ? ` · 回答：${question.answerText}` : ""}`;
}

async function refreshAiQuestionDialog() {
  const question = await fetchAiUserQuestion(aiQuestionDialogQuestionId);
  currentAiQuestionDialogView = question;
  $("#ai-question-text").textContent = question.question;
  renderAiUserQuestionOptions(question);
  return question;
}

async function openAiUserQuestionDialog(questionId) {
  aiQuestionDialogQuestionId = String(questionId);
  const dialog = $("#ai-question-dialog");
  if (!dialog.open) dialog.showModal();
  $("#ai-question-text").textContent = "";
  $("#ai-question-options").replaceChildren();
  $("#ai-question-custom-answer").value = "";
  syncAiQuestionAnswerCount();
  $("#ai-question-expiry").textContent = "正在加载问题……";
  try {
    return await refreshAiQuestionDialog();
  } catch (error) {
    $("#ai-question-expiry").textContent = `加载失败：${error.message}`;
    throw error;
  }
}

function beginAiQuestionContinuationUi(conversationId, questionId) {
  const tab = conversationId ? aiChatTabManager.findByConversation(conversationId) : null;
  if (!tab) return null;
  const card = questionId
    ? tab.feed.querySelector(`.ai-question-card[data-question-id="${CSS.escape(String(questionId))}"]`)
    : null;
  const note = card?.querySelector(".ai-interactive-note") ?? null;
  const status = card?.querySelector(".ai-status-chip") ?? null;
  const previousNote = note?.textContent ?? "";
  const previousStatus = status?.textContent ?? "";
  const controlStates = card
    ? [...card.querySelectorAll("button")].map((button) => ({ button, disabled: button.disabled }))
    : [];
  if (card) {
    card.classList.add("is-resuming");
    card.setAttribute("aria-busy", "true");
    controlStates.forEach(({ button }) => { button.disabled = true; });
    if (status) status.textContent = "处理中";
    if (note) note.textContent = "回答已作为工具结果提交，正在根据你的回答继续处理…";
  }
  aiQuestionContinuationTabIds.add(tab.id);
  setAiChatTabStatus(tab, "streaming");
  if (isActiveAiChatTab(tab)) syncAiRequestControls();
  scrollAiFeedToBottom(tab.feed);
  return {
    tab,
    card,
    note,
    status,
    previousNote,
    previousStatus,
    controlStates
  };
}

function finishAiQuestionContinuationUi(continuationUi, failed = false) {
  if (!continuationUi) return;
  aiQuestionContinuationTabIds.delete(continuationUi.tab.id);
  if (continuationUi.card?.isConnected) {
    continuationUi.card.classList.remove("is-resuming");
    continuationUi.card.removeAttribute("aria-busy");
    continuationUi.controlStates.forEach(({ button, disabled }) => { button.disabled = disabled; });
    if (continuationUi.note) continuationUi.note.textContent = continuationUi.previousNote;
    if (continuationUi.status) continuationUi.status.textContent = continuationUi.previousStatus;
  }
  if (aiChatTabManager.get(continuationUi.tab.id)) setAiChatTabStatus(continuationUi.tab, failed ? "error" : "ready");
  if (isActiveAiChatTab(continuationUi.tab)) syncAiRequestControls();
}

async function reloadAiQuestionConversation(conversationId) {
  if (!conversationId) return null;
  const tab = aiChatTabManager.findByConversation(conversationId);
  if (!tab) return openAiConversation(conversationId);
  const conversation = await api(`/api/ai-conversations/${encodeURIComponent(conversationId)}?page=1&limit=100`);
  if (String(conversation.workId ?? "") !== String(state.work?.id ?? "")) throw new Error("AI 对话不属于当前作品");
  upsertAiConversationSummary(conversation);
  applyConversationToAiChatTab(tab, conversation);
  activateAiChatTab(tab.id, { persistCurrent: false, force: true });
  return conversation;
}

async function respondAiUserQuestion(questionId, payload) {
  if (aiQuestionDialogBusy) return;
  aiQuestionDialogBusy = true;
  $("#ai-question-submit").disabled = true;
  $("#ai-question-skip").disabled = true;
  const questionDialog = $("#ai-question-dialog");
  const approvalCenterDialog = $("#ai-approval-center-dialog");
  let continuationUi = null;
  let continuationFailed = false;
  try {
    const knownQuestion = currentAiQuestionDialogView?.id === String(questionId)
      ? currentAiQuestionDialogView
      : await fetchAiUserQuestion(questionId);
    const conversationId = typeof knownQuestion?.conversationId === "string" ? knownQuestion.conversationId : null;
    if (questionDialog.open) questionDialog.close();
    if (approvalCenterDialog.open) approvalCenterDialog.close();
    continuationUi = beginAiQuestionContinuationUi(conversationId, questionId);
    let question;
    if (payload.action === "reject") {
      question = await api(questionsEndpoint(`/${encodeURIComponent(String(questionId))}/reject`), { method: "POST" });
    } else if (payload.action === "custom") {
      question = await api(questionsEndpoint(`/${encodeURIComponent(String(questionId))}/answer`), { method: "POST", body: { customAnswer: payload.customAnswer } });
    } else {
      question = await api(questionsEndpoint(`/${encodeURIComponent(String(questionId))}/answer`), {
        method: "POST",
        body: {
          selectedOption: payload.selectedOption,
          ...(payload.customAnswer ? { customAnswer: payload.customAnswer } : {})
        }
      });
    }
    cacheAiQuestionView(question);
    currentAiQuestionDialogView = question;
    aiQuestionDialogQuestionId = String(question.id);
    await reloadAiQuestionConversation(question.conversationId ?? conversationId);
    toast(payload.action === "reject" ? "已跳过该问题，AI 已继续处理" : "回答已提交，AI 已继续处理");
    return question;
  } catch (error) {
    continuationFailed = true;
    const latestQuestion = await fetchAiUserQuestion(questionId).catch(() => null);
    if (latestQuestion) {
      currentAiQuestionDialogView = latestQuestion;
      cacheAiQuestionView(latestQuestion);
      if (latestQuestion.status === "pending") {
        $("#ai-question-text").textContent = latestQuestion.question;
        renderAiUserQuestionOptions(latestQuestion);
        if (!questionDialog.open) questionDialog.showModal();
      }
    }
    throw error;
  } finally {
    finishAiQuestionContinuationUi(continuationUi, continuationFailed);
    aiQuestionDialogBusy = false;
  }
}

/** Convert a persisted tool call back into a process step for history rendering. */
function aiToolProcessStep(toolCall, round = 1) {
  const normalizedToolCall = { ...toolCall };
  delete normalizedToolCall.round;
  return {
    id: `tool-${String(toolCall?.id ?? "unknown")}`,
    type: "tool",
    round: Number(round) || 1,
    toolCall: normalizedToolCall,
    createdAt: toolCall?.calledAt ?? new Date().toISOString()
  };
}

function formatAiProcessDuration(value) {
  const durationMs = Number(value);
  if (!Number.isFinite(durationMs) || durationMs < 0) return "";
  const totalSeconds = durationMs / 1000;
  if (totalSeconds < 60) return `${Math.max(0.1, totalSeconds).toFixed(1)} 秒`;
  const roundedSeconds = Math.round(totalSeconds);
  const hours = Math.floor(roundedSeconds / 3600);
  const minutes = Math.floor((roundedSeconds % 3600) / 60);
  const seconds = roundedSeconds % 60;
  if (hours > 0) return `${hours} 小时 ${minutes} 分 ${seconds} 秒`;
  return `${minutes} 分 ${String(seconds).padStart(2, "0")} 秒`;
}

function resolveAiProcessDuration(metadata, steps, completedAt) {
  const storedDuration = Number(metadata?.processDurationMs);
  if (Number.isFinite(storedDuration) && storedDuration >= 0) return storedDuration;
  const completedTime = new Date(completedAt ?? "").getTime();
  if (!Number.isFinite(completedTime)) return null;
  const startedTimes = steps
    .map((step) => new Date(step?.createdAt ?? "").getTime())
    .filter((value) => Number.isFinite(value));
  if (!startedTimes.length) return null;
  return Math.max(0, completedTime - Math.min(...startedTimes));
}

function shouldRenderAiProcessStep(step) {
  if (step?.type === "context_compaction") return true;
  if (step?.type === "tool" && step.toolCall) return true;
  if (!step?.content || !["thinking", "intermediate"].includes(step.type)) return false;
  return step.type !== "intermediate" || typeof step.content !== "string" || step.content.trim().length > 0;
}

function renderAiProcessSteps(message, steps, completed, durationMs = null, visibleContents = null) {
  const previousDetails = message.querySelector(".ai-process-details");
  const previousScrollStates = new Map();
  previousDetails?.querySelectorAll(".ai-process-step[data-ai-process-step-id]").forEach((section) => {
    const body = section.querySelector(".ai-process-step-body");
    if (!body) return;
    previousScrollStates.set(section.dataset.aiProcessStepId, {
      scrollTop: body.scrollTop,
      nearBottom: body.scrollHeight - body.scrollTop - body.clientHeight < 24
    });
  });
  previousDetails?.remove();
  const renderableSteps = (Array.isArray(steps) ? steps : []).filter(shouldRenderAiProcessStep);
  if (!renderableSteps.length) return;
  const details = document.createElement("details");
  details.className = "ai-process-details";
  // 存在待确认/待回答的交互卡片时保持展开，避免审批入口在历史消息中被折叠。
  details.open = !completed || steps.some((step) => step?.type === "tool" && isInteractiveToolPending(step.toolCall));
  const summary = document.createElement("summary");
  const title = document.createElement("span");
  title.textContent = completed ? "思考与执行过程" : "正在思考与执行";
  const status = document.createElement("small");
  const duration = durationMs === null || durationMs === undefined ? "" : formatAiProcessDuration(durationMs);
  status.textContent = `${renderableSteps.length} 个步骤${duration ? ` · 耗时 ${duration}` : ""}`;
  summary.append(title, status);
  const list = document.createElement("div");
  list.className = "ai-process-list";
  for (const step of renderableSteps) {
    if (step?.type === "context_compaction") {
      list.append(createAiContextCompactionDivider({
        kind: "tool",
        ariaLabel: `第 ${Number(step.round) || 1} 轮已压缩上下文`,
        title: `已将 ${Number(step.sourceMessageCount) || 0} 条工具上下文压缩为摘要`
      }));
      continue;
    }
    if (step?.type === "tool" && step.toolCall) {
      const tool = document.createElement("section");
      tool.className = "ai-process-step ai-process-tool-step";
      const label = document.createElement("small");
      label.textContent = `第 ${Number(step.round) || 1} 轮 · 工具调用`;
      tool.append(label, createAiToolCallButton(step.toolCall));
      list.append(tool);
      continue;
    }
    const section = document.createElement("section");
    section.className = `ai-process-step ai-process-${step.type}-step`;
    section.dataset.aiProcessStepId = `${step.type}:${String(step.id ?? step.round ?? "")}`;
    const label = document.createElement("small");
    label.textContent = `第 ${Number(step.round) || 1} 轮 · ${step.type === "thinking" ? "Thinking" : "中间输出"}`;
    const body = document.createElement("div");
    body.className = "message-body ai-process-step-body";
    const content = visibleContents?.has(step) ? visibleContents.get(step) : step.content;
    body.innerHTML = renderMarkdown(content);
    section.append(label, body);
    list.append(section);
  }
  details.append(summary, list);
  list.querySelectorAll(".ai-process-step[data-ai-process-step-id]").forEach((section) => {
    const scrollState = previousScrollStates.get(section.dataset.aiProcessStepId);
    const body = section.querySelector(".ai-process-step-body");
    if (!scrollState || !body) return;
    body.scrollTop = scrollState.nearBottom
      ? body.scrollHeight
      : Math.min(scrollState.scrollTop, body.scrollHeight);
  });
  const body = message.querySelector(".message-body");
  if (body) body.before(details);
  else message.append(details);
  if (!completed) scrollAiProcessStepsToBottom(message);
}

function renderAiToolCalls(message, toolCalls, completed = false) {
  renderAiProcessSteps(message, (Array.isArray(toolCalls) ? toolCalls : []).map((toolCall) => aiToolProcessStep(toolCall)), completed);
}

function setAiHistoryVisible(visible) {
  const dialog = $("#ai-history-dialog");
  if (visible && !dialog.open) dialog.showModal();
  else if (!visible && dialog.open) dialog.close();
  $("#ai-history-toggle").setAttribute("aria-expanded", String(dialog.open));
}

let aiHistoryActionConversation = null;
let aiHistoryActionAnchor = null;

function closeAiHistoryActionMenu(restoreFocus = false) {
  const menu = $("#ai-history-action-menu");
  menu.classList.add("hidden");
  document.querySelectorAll(".ai-history-more[aria-expanded=\"true\"]").forEach((button) => {
    button.setAttribute("aria-expanded", "false");
  });
  if (restoreFocus && aiHistoryActionAnchor?.isConnected) aiHistoryActionAnchor.focus();
  aiHistoryActionConversation = null;
  aiHistoryActionAnchor = null;
}

function syncAiHistoryActionMenu(conversation) {
  const menu = $("#ai-history-action-menu");
  const isFavorite = conversation?.isFavorite === true;
  const favorite = menu.querySelector('[data-ai-history-action="favorite"]');
  const favoriteLabel = favorite?.querySelector("span");
  const favoriteHint = favorite?.querySelector("small");
  if (favoriteLabel) favoriteLabel.textContent = isFavorite ? "取消收藏" : "收藏对话";
  if (favoriteHint) favoriteHint.textContent = isFavorite ? "取消收藏后才可以清理对话" : "收藏后不会被清理";
  const deleteOption = menu.querySelector('[data-ai-history-action="delete"]');
  if (deleteOption) {
    deleteOption.disabled = isFavorite;
    deleteOption.title = isFavorite ? "收藏的对话不能清理，请先取消收藏" : "清理后无法恢复";
  }
}

function showAiHistoryActionMenu(anchor, conversation) {
  const menu = $("#ai-history-action-menu");
  closeAiHistoryActionMenu();
  aiHistoryActionConversation = conversation;
  aiHistoryActionAnchor = anchor;
  syncAiHistoryActionMenu(conversation);
  menu.classList.remove("hidden");
  const anchorRect = anchor.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  const left = Math.max(8, Math.min(anchorRect.right - menuRect.width, window.innerWidth - menuRect.width - 8));
  const top = Math.max(8, Math.min(anchorRect.bottom + 6, window.innerHeight - menuRect.height - 8));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
  anchor.setAttribute("aria-expanded", "true");
  menu.querySelector("button")?.focus();
}

async function downloadAiConversation(conversation) {
  if (!conversation?.id) return;
  const response = await fetch(`/api/ai-conversations/${encodeURIComponent(conversation.id)}/export`, {
    headers: { Accept: "text/markdown" }
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({ error: { message: `请求失败：${response.status}` } }));
    throw createClientError(payload.error, `请求失败：${response.status}`, response.status);
  }
  const blob = await response.blob();
  const objectUrl = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  const safeId = String(conversation.id).replace(/[^A-Za-z0-9_-]/gu, "-") || "export";
  anchor.href = objectUrl;
  anchor.download = `ai-conversation-${safeId}.md`;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(objectUrl), 0);
}

async function copyAiConversationSessionId(conversation) {
  const sessionId = typeof conversation?.id === "string" ? conversation.id.trim() : "";
  if (!sessionId) throw new Error("无法确定对话 Session ID");
  await copyAiRawMarkdown(sessionId);
}

function resetAiConversationAfterDelete() {
  const tab = activeAiChatTab();
  if (tab) closeAiChatTab(tab.id);
}

async function favoriteAiConversation(conversation) {
  const updated = await api(`/api/ai-conversations/${encodeURIComponent(conversation.id)}/favorite`, {
    method: "PATCH",
    body: { isFavorite: conversation.isFavorite !== true }
  });
  upsertAiConversationSummary(updated);
  toast(updated.isFavorite ? "对话已收藏" : "已取消收藏");
}

async function deleteAiConversation(conversation) {
  if (conversation.isFavorite === true) {
    toast("收藏的对话不能清理，请先取消收藏", "error");
    return;
  }
  if (!await confirmToast(`清理“${conversation.title}”后，对话及其消息将无法恢复。确认继续吗？`, {
    title: "清理对话",
    confirmLabel: "确认清理"
  })) return;
  await api(`/api/ai-conversations/${encodeURIComponent(conversation.id)}`, { method: "DELETE" });
  state.aiConversations = state.aiConversations.filter((item) => item.id !== conversation.id);
  const tab = aiChatTabManager.findByConversation(conversation.id);
  if (tab) {
    if (isActiveAiChatTab(tab)) resetAiConversationAfterDelete();
    else closeAiChatTab(tab.id);
  }
  renderAiConversationHistory();
  toast("对话已清理");
}

const aiConversationTaskTypeLabels = {
  chat: "问答",
  roleplay: "角色扮演"
};

function aiConversationTaskTypeLabel(taskType) {
  return aiConversationTaskTypeLabels[String(taskType)] ?? aiConversationTaskTypeLabels.chat;
}

function aiConversationContextScopeLabel(scope) {
  const normalizedScope = scope && typeof scope === "object" ? scope : {};
  if (normalizedScope.type === "chapter" && normalizedScope.includeBookSummary === true) return "当前章节 + 全书概要";
  return {
    none: "无上下文",
    chapter: "当前章节",
    volume: "当前卷",
    book: "全书",
    "settings-catalog": "设定库"
  }[String(normalizedScope.type)] ?? "无上下文";
}

function aiConversationHistoryMeta(conversation) {
  const parts = [
    `${Number(conversation.messageCount ?? 0)} 条`,
    aiConversationTaskTypeLabel(conversation.taskType),
    aiConversationContextScopeLabel(conversation.contextScope)
  ];
  if (conversation.roleplayCharacter?.name) parts.push(`扮演 ${conversation.roleplayCharacter.name}`);
  if (conversation.roleplayUserCharacter?.name) parts.push(`用户扮演 ${conversation.roleplayUserCharacter.name}`);
  parts.push(formatDateTime(conversation.updatedAt));
  return parts.join(" · ");
}

function renderAiConversationHistory() {
  closeAiHistoryActionMenu();
  const host = $("#ai-history-list");
  host.replaceChildren();
  const pagination = $("#ai-history-pagination");
  const showPagination = aiConversationHistoryPage.page > 1 || aiConversationHistoryPage.hasMore;
  pagination.classList.toggle("hidden", !showPagination);
  $("#ai-history-previous").disabled = aiConversationHistoryPage.page <= 1;
  $("#ai-history-next").disabled = !aiConversationHistoryPage.hasMore;
  $("#ai-history-page-label").textContent = `第 ${aiConversationHistoryPage.page} 页 · 本页 ${state.aiConversations.length} 条`;
  if (!state.aiConversations.length) {
    host.innerHTML = '<p class="ai-history-empty">还没有历史对话</p>';
    return;
  }
  for (const conversation of state.aiConversations) {
    const row = document.createElement("div");
    row.className = "ai-history-row";
    const button = document.createElement("button");
    button.type = "button";
    button.className = `ai-history-item${conversation.id === state.aiConversationId ? " is-active" : ""}`;
    button.dataset.aiConversationId = conversation.id;
    const titleRow = document.createElement("span");
    titleRow.className = "ai-history-title-row";
    const title = document.createElement("strong");
    title.textContent = conversation.title;
    titleRow.append(title);
    if (conversation.isFavorite === true) {
      const favorite = document.createElement("small");
      favorite.className = "ai-history-favorite";
      favorite.textContent = "已收藏";
      favorite.setAttribute("aria-label", "已收藏");
      titleRow.append(favorite);
    }
    const meta = document.createElement("small");
    meta.textContent = aiConversationHistoryMeta(conversation);
    button.append(titleRow, meta);
    button.addEventListener("click", () => openAiConversation(conversation.id));
    const more = document.createElement("button");
    more.type = "button";
    more.className = "ai-history-more";
    more.setAttribute("aria-label", `打开“${conversation.title}”对话操作`);
    more.setAttribute("aria-haspopup", "menu");
    more.setAttribute("aria-controls", "ai-history-action-menu");
    more.setAttribute("aria-expanded", "false");
    more.textContent = "···";
    more.addEventListener("click", (event) => {
      event.stopPropagation();
      const expanded = more.getAttribute("aria-expanded") === "true";
      if (expanded) closeAiHistoryActionMenu(true);
      else showAiHistoryActionMenu(more, conversation);
    });
    row.append(button, more);
    host.append(row);
  }
}

const roleplayMemoryCategoryLabels = Object.freeze({
  event: "事件",
  state: "状态",
  relationship: "关系",
  commitment: "承诺",
  knowledge: "知识",
  scene: "场景"
});
const roleplayMemoryImportanceLabels = Object.freeze({ low: "低重要度", medium: "中重要度", high: "高重要度" });
const roleplayMemoryCertaintyLabels = Object.freeze({ experienced: "亲历", observed: "观察", heard: "听说", believed: "相信" });
const roleplayMemoryStatusLabels = Object.freeze({ active: "生效中", superseded: "已取代", archived: "已删除" });
let roleplayMemoryItems = [];
let roleplayMemoryCharacter = null;
let roleplayMemoryPagination = { cursor: 0, limit: 20, total: 0, nextCursor: null };
let roleplayMemoryCursorHistory = [0];
let roleplayMemorySearchTimer = null;
let roleplayMemoryLoaded = false;
let roleplayMemoryLoading = false;

function roleplayMemoryReadOnly() {
  return Boolean(state.work) && !canEditModule("characters");
}

function roleplayMemoryQuery() {
  const parameters = new URLSearchParams({
    cursor: String(roleplayMemoryCursorHistory.at(-1) ?? 0),
    limit: "20"
  });
  const query = $("#roleplay-memory-search").value.trim();
  const category = $("#roleplay-memory-category").value;
  const status = $("#roleplay-memory-status").value;
  if (query) parameters.set("q", query);
  if (category) parameters.set("categories", category);
  if (status === "all") parameters.set("statuses", "active,superseded,archived");
  else parameters.set("statuses", status || "active");
  return parameters;
}

function roleplayMemorySourceHtml(source) {
  const canOpen = source.canOpen === true && source.conversationId && source.messageId;
  const sourceLabel = source.role === "assistant" ? "角色回复" : "用户消息";
  const detail = source.restricted
    ? "来自其他用户的角色扮演对话，无权查看原文"
    : source.evidence || "来源消息已删除，保留来源时间";
  return `<article class="roleplay-memory-source"><p><strong>${sourceLabel}</strong> · ${esc(formatDateTime(source.sourceAt))} · ${esc(detail)}</p>${canOpen ? `<button type="button" data-roleplay-memory-source-id="${esc(source.id)}" data-roleplay-memory-source-conversation="${esc(source.conversationId)}" data-roleplay-memory-source-message="${esc(source.messageId)}">查看来源</button>` : ""}</article>`;
}

function renderRoleplayMemoryList() {
  const host = $("#roleplay-memory-list");
  if (!host) return;
  $("#roleplay-memory-add").disabled = roleplayMemoryReadOnly();
  if (roleplayMemoryLoading) {
    host.innerHTML = '<p class="roleplay-memory-empty">正在读取角色扮演记忆……</p>';
    return;
  }
  if (!roleplayMemoryLoaded) {
    host.innerHTML = '<p class="roleplay-memory-empty">打开角色扮演记忆分区后读取该角色的共享记忆库。</p>';
    return;
  }
  if (!roleplayMemoryItems.length) {
    host.innerHTML = '<p class="roleplay-memory-empty">当前筛选下没有记忆。可以手工添加，AI 也会在成功回复后整理值得保留的扮演经历。</p>';
  } else {
    host.innerHTML = roleplayMemoryItems.map((memory) => {
      const sources = Array.isArray(memory.sources) ? memory.sources : [];
      const editable = !roleplayMemoryReadOnly();
      const pinAction = memory.isPinned ? "取消置顶" : "置顶";
      const actions = editable
        ? memory.status === "archived"
          ? `<button type="button" data-roleplay-memory-action="restore" data-memory-id="${esc(memory.id)}">恢复</button>`
          : `<button class="danger-button roleplay-memory-icon-action" type="button" data-roleplay-memory-action="archive" data-memory-id="${esc(memory.id)}" aria-label="删除角色扮演记忆" title="删除">${trashIconMarkup()}</button><button class="roleplay-memory-icon-action${memory.isPinned ? " is-pinned" : ""}" type="button" data-roleplay-memory-action="pin" data-memory-id="${esc(memory.id)}" aria-label="${pinAction}角色扮演记忆" aria-pressed="${memory.isPinned === true}" title="${pinAction}">${roleplayMemoryPinIconMarkup()}</button><button class="roleplay-memory-icon-action" type="button" data-roleplay-memory-action="edit" data-memory-id="${esc(memory.id)}" aria-label="编辑角色扮演记忆" title="编辑">${pencilIconMarkup()}</button>`
        : "";
      return `<article class="roleplay-memory-card${memory.status === "archived" ? " is-archived" : ""}" data-roleplay-memory-id="${esc(memory.id)}">
        <header class="roleplay-memory-card-header"><div class="roleplay-memory-card-badges"><span class="roleplay-memory-badge">${esc(roleplayMemoryCategoryLabels[memory.category] ?? memory.category)}</span><span class="roleplay-memory-badge">${esc(roleplayMemoryImportanceLabels[memory.importance] ?? memory.importance)}</span><span class="roleplay-memory-badge">${esc(roleplayMemoryCertaintyLabels[memory.certainty] ?? memory.certainty)}</span><span class="roleplay-memory-badge">${esc(roleplayMemoryStatusLabels[memory.status] ?? memory.status)}</span><span class="roleplay-memory-badge is-noncanonical">非正史</span>${memory.isPinned ? '<span class="roleplay-memory-badge is-pinned">已置顶</span>' : ""}</div><time datetime="${esc(memory.updatedAt)}">${esc(formatDateTime(memory.updatedAt))}</time></header>
        <p class="roleplay-memory-content">${esc(memory.content)}</p>
        <p class="roleplay-memory-card-meta">${memory.sourceType === "ai" ? "AI 整理" : "手工添加"} · 版本 ${Number(memory.versionNo ?? 1)} · 角色共享</p>
        ${sources.length ? `<details class="roleplay-memory-sources"><summary>来源信息 · ${sources.length} 条</summary><div class="roleplay-memory-source-list">${sources.map(roleplayMemorySourceHtml).join("")}</div></details>` : ""}
        ${actions ? `<div class="roleplay-memory-card-actions">${actions}</div>` : ""}
      </article>`;
    }).join("");
  }
  const page = roleplayMemoryCursorHistory.length;
  const hasPrevious = roleplayMemoryCursorHistory.length > 1;
  const hasNext = roleplayMemoryPagination.nextCursor !== null;
  $("#roleplay-memory-pagination").classList.toggle("hidden", !hasPrevious && !hasNext);
  $("#roleplay-memory-previous").disabled = !hasPrevious;
  $("#roleplay-memory-next").disabled = !hasNext;
  $("#roleplay-memory-page-label").textContent = `第 ${page} 页 · 共 ${Number(roleplayMemoryPagination.total ?? 0)} 条`;
}

async function loadRoleplayMemories({ resetCursor = false } = {}) {
  if (!roleplayMemoryCharacter?.id || roleplayMemoryLoading) return;
  if (resetCursor) roleplayMemoryCursorHistory = [0];
  const characterId = roleplayMemoryCharacter.id;
  roleplayMemoryLoading = true;
  renderRoleplayMemoryList();
  try {
    const result = await api(`/api/characters/${encodeURIComponent(characterId)}/roleplay-memories?${roleplayMemoryQuery()}`);
    if (roleplayMemoryCharacter?.id !== characterId) return;
    roleplayMemoryItems = Array.isArray(result.items) ? result.items : [];
    roleplayMemoryPagination = result.pagination ?? { cursor: 0, limit: 20, total: roleplayMemoryItems.length, nextCursor: null };
    if (result.character) roleplayMemoryCharacter = { ...roleplayMemoryCharacter, ...result.character };
    roleplayMemoryLoaded = true;
  } catch (error) {
    if (roleplayMemoryCharacter?.id === characterId) {
      roleplayMemoryItems = [];
      roleplayMemoryLoaded = false;
    }
    throw error;
  } finally {
    if (roleplayMemoryCharacter?.id === characterId) {
      roleplayMemoryLoading = false;
      renderRoleplayMemoryList();
    }
  }
}

function bindRoleplayMemorySurface(character) {
  const surface = $("#character-roleplay-memory-surface");
  if (!surface || !character?.id) return;
  roleplayMemoryCharacter = { id: character.id, name: character.name, workId: character.workId ?? state.work?.id };
  roleplayMemoryItems = [];
  roleplayMemoryPagination = { cursor: 0, limit: 20, total: 0, nextCursor: null };
  roleplayMemoryCursorHistory = [0];
  roleplayMemoryLoaded = false;
  roleplayMemoryLoading = false;
  if (roleplayMemorySearchTimer) window.clearTimeout(roleplayMemorySearchTimer);
  roleplayMemorySearchTimer = null;
  renderRoleplayMemoryList();
  $("#roleplay-memory-filter-toggle").addEventListener("click", (event) => {
    const panel = $("#roleplay-memory-filter-panel");
    const expanded = panel.classList.contains("hidden");
    panel.classList.toggle("hidden", !expanded);
    event.currentTarget.setAttribute("aria-expanded", String(expanded));
    if (expanded) $("#roleplay-memory-search").focus();
  });
  $("#roleplay-memory-add").addEventListener("click", () => openRoleplayMemoryEditor());
  $("#roleplay-memory-list").addEventListener("click", async (event) => {
    const sourceButton = event.target.closest("[data-roleplay-memory-source-conversation]");
    if (sourceButton) {
      try {
        if (!$("#character-editor-form").classList.contains("hidden")) await closeEntityEditor({ force: true });
        await openAiConversation(
          sourceButton.dataset.roleplayMemorySourceConversation,
          true,
          sourceButton.dataset.roleplayMemorySourceMessage,
          sourceButton.dataset.roleplayMemorySourceId
        );
      } catch (error) {
        toast(`来源消息打开失败：${error.message}`, "error");
      }
      return;
    }
    const actionButton = event.target.closest("[data-roleplay-memory-action]");
    if (!actionButton) return;
    const memory = roleplayMemoryItems.find((item) => item.id === actionButton.dataset.memoryId);
    actionButton.disabled = true;
    try {
      await updateRoleplayMemoryAction(memory, actionButton.dataset.roleplayMemoryAction);
    } catch (error) {
      toast(`记忆操作失败：${error.message}`, "error");
    } finally {
      if (actionButton.isConnected) actionButton.disabled = false;
    }
  });
  $("#roleplay-memory-search").addEventListener("input", () => {
    if (roleplayMemorySearchTimer) window.clearTimeout(roleplayMemorySearchTimer);
    roleplayMemorySearchTimer = window.setTimeout(() => {
      void loadRoleplayMemories({ resetCursor: true }).catch((error) => toast(`记忆搜索失败：${error.message}`, "error"));
    }, 250);
  });
  for (const select of [$("#roleplay-memory-category"), $("#roleplay-memory-status")]) {
    select.addEventListener("change", () => {
      void loadRoleplayMemories({ resetCursor: true }).catch((error) => toast(`记忆筛选失败：${error.message}`, "error"));
    });
  }
  $("#roleplay-memory-filter-reset").addEventListener("click", () => {
    $("#roleplay-memory-search").value = "";
    $("#roleplay-memory-category").value = "";
    $("#roleplay-memory-status").value = "active";
    void loadRoleplayMemories({ resetCursor: true }).catch((error) => toast(`记忆筛选重置失败：${error.message}`, "error"));
  });
  $("#roleplay-memory-previous").addEventListener("click", () => {
    if (roleplayMemoryCursorHistory.length <= 1) return;
    roleplayMemoryCursorHistory.pop();
    void loadRoleplayMemories().catch((error) => toast(`记忆分页失败：${error.message}`, "error"));
  });
  $("#roleplay-memory-next").addEventListener("click", () => {
    if (roleplayMemoryPagination.nextCursor === null) return;
    roleplayMemoryCursorHistory.push(roleplayMemoryPagination.nextCursor);
    void loadRoleplayMemories().catch((error) => toast(`记忆分页失败：${error.message}`, "error"));
  });
}

function roleplayMemoryEditorFields(memory = null) {
  return field("category", "记忆类别", "select", memory?.category ?? "event", Object.entries(roleplayMemoryCategoryLabels))
    + field("importance", "重要度", "select", memory?.importance ?? "medium", Object.entries(roleplayMemoryImportanceLabels))
    + field("certainty", "可信状态", "select", memory?.certainty ?? "experienced", Object.entries(roleplayMemoryCertaintyLabels))
    + field("isPinned", "置顶这条记忆", "checkbox", memory?.isPinned === true)
    + field("content", "记忆内容", "textarea", memory?.content ?? "");
}

function openRoleplayMemoryEditor(memory = null) {
  openDialog(memory ? "编辑角色扮演记忆" : "手工添加角色扮演记忆", roleplayMemoryEditorFields(memory), async (form) => {
    const body = {
      category: String(form.get("category") ?? "event"),
      importance: String(form.get("importance") ?? "medium"),
      certainty: String(form.get("certainty") ?? "experienced"),
      isPinned: form.get("isPinned") === "on",
      content: String(form.get("content") ?? "").trim(),
      ...(memory ? { expectedVersion: Number(memory.versionNo) } : {})
    };
    if (!body.content) throw new Error("请输入记忆内容");
    await api(memory
      ? `/api/roleplay-memories/${encodeURIComponent(memory.id)}`
      : `/api/characters/${encodeURIComponent(roleplayMemoryCharacter.id)}/roleplay-memories`, {
      method: memory ? "PATCH" : "POST",
      body
    });
    await loadRoleplayMemories();
    toast(memory ? "角色扮演记忆已更新" : "角色扮演记忆已添加");
  }, memory ? "版本化编辑" : "非正史 · 手工添加", {
    submitLabel: memory ? "保存记忆" : "添加记忆",
    errorPrefix: "记忆保存失败：",
    meta: "记录该角色在作品内共享的非正史互动，不会写入正文、角色卡字段或设定库。"
  });
  const textarea = $("#dialog-fields textarea[name='content']");
  if (textarea) {
    textarea.maxLength = 2_000;
    textarea.rows = 7;
    textarea.focus();
  }
}

async function updateRoleplayMemoryAction(memory, action) {
  if (!memory) return;
  if (action === "edit") return openRoleplayMemoryEditor(memory);
  if (action === "archive" && !await confirmToast("删除后 AI 不再召回这条记忆，可稍后从“已删除”筛选中恢复。", {
    title: "删除角色扮演记忆",
    confirmLabel: "确认删除"
  })) return;
  if (action === "pin") {
    await api(`/api/roleplay-memories/${encodeURIComponent(memory.id)}`, {
      method: "PATCH",
      body: { expectedVersion: Number(memory.versionNo), isPinned: memory.isPinned !== true }
    });
  } else if (action === "archive") {
    await api(`/api/roleplay-memories/${encodeURIComponent(memory.id)}`, {
      method: "DELETE",
      body: { expectedVersion: Number(memory.versionNo) }
    });
  } else if (action === "restore") {
    await api(`/api/roleplay-memories/${encodeURIComponent(memory.id)}/restore`, {
      method: "POST",
      body: { expectedVersion: Number(memory.versionNo) }
    });
  }
  await loadRoleplayMemories();
  toast(action === "pin" ? (memory.isPinned ? "已取消置顶" : "记忆已置顶") : action === "archive" ? "记忆已删除" : "记忆已恢复");
}

function defaultAiConversationTitle(prompt) {
  const normalized = roleplayUserTurnTitleSource(String(prompt ?? "")).replace(/\s+/gu, " ").trim();
  return Array.from(normalized).slice(0, 15).join("") || "新对话";
}

function upsertAiConversationSummary(conversation) {
  if (!conversation?.id) return;
  const current = state.aiConversations.find((item) => item.id === conversation.id);
  const lastMessage = Array.isArray(conversation.messages) ? conversation.messages.at(-1) : null;
  const summary = { ...current, ...conversation, ...(lastMessage ? { preview: roleplayUserTurnDisplayText(lastMessage.content) } : {}) };
  delete summary.messages;
  delete summary.messagesPage;
  if (!current && loadedAiConversationsWorkId === state.work?.id) {
    loadedAiConversationsWorkId = null;
    aiConversationHistoryPage = { page: 1, limit: aiConversationHistoryPageLimit, hasMore: false, nextPage: null };
    state.aiConversations = [summary];
    renderAiConversationHistory();
    return;
  }
  state.aiConversations = [summary, ...state.aiConversations.filter((item) => item.id !== summary.id)]
    .sort((left, right) => new Date(right.updatedAt).getTime() - new Date(left.updatedAt).getTime());
  renderAiConversationHistory();
}

function updateAiConversationSummaryFromMessage(message) {
  if (!message?.conversationId) return;
  const current = state.aiConversations.find((conversation) => conversation.id === message.conversationId);
  if (!current) return;
  upsertAiConversationSummary({
    ...current,
    title: current.title === "新对话" && message.role === "user" ? defaultAiConversationTitle(message.content) : current.title,
    messageCount: Number(current.messageCount ?? 0) + 1,
    preview: roleplayUserTurnDisplayText(message.content),
    ...(aiConversationMessageHasImages(message) ? { hasImageAttachments: true, modelLockedByImage: true } : {}),
    updatedAt: message.createdAt ?? current.updatedAt
  });
}

function applyAiConversationTitle(title, conversationId = state.aiConversationId) {
  if (!title || !conversationId) return;
  const current = state.aiConversations.find((conversation) => conversation.id === conversationId);
  if (current) current.title = title;
  const tab = aiChatTabManager.findByConversation(conversationId);
  if (tab) tab.title = title;
  if (state.aiConversationId === conversationId) $("#ai-conversation-title").textContent = title;
  renderAiConversationHistory();
  renderAiChatTabs();
}

function applyAiConversations(pageResult) {
  state.aiConversations = pageResult.items;
  aiConversationHistoryPage = {
    page: pageResult.page,
    limit: pageResult.limit,
    hasMore: pageResult.hasMore,
    nextPage: pageResult.nextPage
  };
  loadedAiConversationsWorkId = state.work?.id ?? null;
  renderAiConversationHistory();
  const current = state.aiConversations.find((conversation) => conversation.id === state.aiConversationId);
  if (current) $("#ai-conversation-title").textContent = current.title;
}

async function loadAiConversations(page = 1) {
  const workId = state.work?.id;
  if (!workId) return;
  const generation = workScopedUiGeneration;
  const conversations = await apiPage(`/api/works/${workId}/ai-conversations`, page, aiConversationHistoryPageLimit);
  if (state.work?.id !== workId || generation !== workScopedUiGeneration) return;
  applyAiConversations(conversations);
}

async function ensureAiConversationsLoaded() {
  const workId = state.work?.id;
  if (!workId || loadedAiConversationsWorkId === workId) return;
  if (aiConversationsLoadPromise && aiConversationsLoadWorkId === workId) return aiConversationsLoadPromise;
  aiConversationsLoadWorkId = workId;
  aiConversationsLoadPromise = loadAiConversations();
  try {
    await aiConversationsLoadPromise;
  } finally {
    if (aiConversationsLoadWorkId === workId) {
      aiConversationsLoadPromise = null;
      aiConversationsLoadWorkId = null;
    }
  }
}

async function openAiConversation(conversationId, hideHistory = true, focusMessageId = null, roleplayMemorySourceId = null) {
  if (!state.work) return null;
  const existingTab = aiChatTabManager.findByConversation(conversationId);
  const existingMessage = focusMessageId
    ? existingTab?.feed.querySelector(`[data-message-id="${CSS.escape(String(focusMessageId))}"]`)
    : null;
  if (existingTab && (!focusMessageId || existingMessage || aiRequestManager.hasActive(existingTab.id))) {
    activateAiChatTab(existingTab.id);
    if (focusMessageId && existingMessage) focusAiConversationMessage(focusMessageId);
    if (hideHistory) setAiHistoryVisible(false);
    return state.aiConversations.find((conversation) => conversation.id === conversationId) ?? existingTab;
  }
  let openingSlot = existingTab ? { allowed: true, tab: existingTab, replacing: false } : aiChatTabOpeningSlot();
  if (!openingSlot.allowed) {
    reportAiChatTabLimit();
    return null;
  }
  const navigation = beginAiConversationNavigation("已切换 AI 对话", "切换会话");
  try {
    const parameters = new URLSearchParams({ page: "1", limit: "100" });
    if (focusMessageId) parameters.set("messageId", String(focusMessageId));
    if (roleplayMemorySourceId) parameters.set("roleplayMemorySourceId", String(roleplayMemorySourceId));
    const [conversation] = await Promise.all([
      api(`/api/ai-conversations/${conversationId}?${parameters}`),
      ensureAiReferencesLoaded()
    ]);
    if (!isAiConversationNavigationCurrent(navigation)) return null;
    if (String(conversation.workId ?? "") !== navigation.workId) throw new Error("AI 对话不属于当前作品");
    upsertAiConversationSummary(conversation);
    persistActiveAiChatTab();
    if (!existingTab) openingSlot = aiChatTabOpeningSlot();
    if (!openingSlot.allowed) {
      reportAiChatTabLimit();
      return null;
    }
    interruptAiChatTabForReplacement(openingSlot);
    let tab = existingTab ?? openingSlot.tab;
    if (!tab) tab = createAiChatTabState();
    applyConversationToAiChatTab(tab, conversation);
    activateAiChatTab(tab.id, { persistCurrent: false, force: true });
    if (focusMessageId) window.requestAnimationFrame(() => focusAiConversationMessage(focusMessageId));
    if (hideHistory) setAiHistoryVisible(false);
    return conversation;
  } catch (error) {
    if (!isAiConversationNavigationCurrent(navigation)) return null;
    throw error;
  } finally {
    finishAiConversationNavigation(navigation);
  }
}

function focusAiConversationMessage(messageId) {
  const message = [...$("#ai-feed").querySelectorAll("[data-message-id]")]
    .find((candidate) => candidate.dataset.messageId === String(messageId));
  if (!message) return;
  message.scrollIntoView({ behavior: "smooth", block: "center" });
  message.classList.add("is-search-target");
  window.setTimeout(() => message.classList.remove("is-search-target"), 1800);
}

function aiConversationMessageHasImages(message) {
  return Array.isArray(message?.metadata?.chatImageAttachmentIds)
    && message.metadata.chatImageAttachmentIds.some((attachmentId) => String(attachmentId ?? "").trim().length > 0);
}

function applyConversationToAiChatTab(tab, conversation) {
  tab.workId = String(conversation.workId ?? state.work?.id ?? "");
  tab.conversationId = conversation.id;
  tab.title = conversation.title || "新对话";
  tab.modelId = typeof conversation.modelId === "string" ? conversation.modelId : null;
  tab.hasImageAttachments = conversation.hasImageAttachments === true
    || (Array.isArray(conversation.messages) && conversation.messages.some(aiConversationMessageHasImages));
  tab.selectedModelId = tab.modelId ?? tab.selectedModelId;
  tab.promptSent = Array.isArray(conversation.messages) && conversation.messages.some((message) => message.role === "user");
  tab.taskType = conversation.taskType ?? "chat";
  tab.contextScope = conversation.contextScope ?? { type: "none" };
  tab.roleplayCharacter = conversation.roleplayCharacter ?? null;
  tab.roleplayUserCharacter = conversation.roleplayUserCharacter ?? null;
  tab.citations = [];
  tab.references = [];
  tab.composer = {
    text: "",
    citations: [],
    references: [],
    images: [],
    sceneDirection: "",
    scenePin: normalizeRoleplayScenePin(conversation.scenePin)
  };
  tab.contextUsage = null;
  tab.contextWarning = conversation.contextWarningPending === true;
  resetAiFeed(tab.feed, tab.roleplayCharacter, tab.roleplayUserCharacter);
  for (const message of conversation.messages ?? []) {
    appendMessage(message.role, message.content, message.citations, message.createdAt, message.metadata, message.id, { tab });
  }
  if (conversation.hasCompactedSummary) {
    renderConversationCompactionDivider(conversation.compactedMessageCount, conversation.messageCount, tab.feed, conversation);
  }
  renderAiChatTabs();
}

function applyNewAiConversation(conversation, tab = activeAiChatTab()) {
  upsertAiConversationSummary(conversation);
  applyConversationToAiChatTab(tab, { ...conversation, messages: [] });
  if (isActiveAiChatTab(tab)) applyAiChatTabState(tab);
  setAiHistoryVisible(false);
}

async function createNewAiConversation(taskType = "chat") {
  if (!state.work) return null;
  let openingSlot = aiChatTabOpeningSlot();
  if (!openingSlot.allowed) {
    reportAiChatTabLimit();
    return null;
  }
  const navigation = beginAiConversationNavigation("已新建 AI 对话", "新建会话");
  try {
    const conversation = await api(`/api/works/${navigation.workId}/ai-conversations`, { method: "POST", body: { taskType } });
    if (!isAiConversationNavigationCurrent(navigation)) return null;
    if (String(conversation.workId ?? "") !== navigation.workId) throw new Error("新对话不属于当前作品");
    persistActiveAiChatTab();
    openingSlot = aiChatTabOpeningSlot();
    if (!openingSlot.allowed) {
      reportAiChatTabLimit();
      return null;
    }
    interruptAiChatTabForReplacement(openingSlot);
    const tab = openingSlot.tab ?? createAiChatTabState();
    applyNewAiConversation(conversation, tab);
    activateAiChatTab(tab.id, { persistCurrent: false, force: true });
    return conversation;
  } catch (error) {
    if (!isAiConversationNavigationCurrent(navigation)) return null;
    throw error;
  } finally {
    finishAiConversationNavigation(navigation);
  }
}

function favoriteCharactersFirst(characters) {
  const items = Array.isArray(characters) ? characters : [];
  return [
    ...items.filter((character) => character.isPinned === true && character.isFavorite === true),
    ...items.filter((character) => character.isPinned === true && character.isFavorite !== true),
    ...items.filter((character) => character.isPinned !== true && character.isFavorite === true),
    ...items.filter((character) => character.isPinned !== true && character.isFavorite !== true)
  ];
}

function roleplayCharacterOptionLabel(character) {
  const pinLabel = character?.isPinned === true ? "[置顶]" : "";
  const favoriteLabel = character?.isFavorite === true ? "[收藏]" : "";
  const deathLabel = character?.isDead ? "（已死亡）" : "";
  return `${pinLabel}${favoriteLabel}${pinLabel || favoriteLabel ? " " : ""}${String(character?.name ?? "")}${deathLabel}`;
}

function renderAiRoleplayCharacterSelect() {
  const select = $("#ai-roleplay-character");
  const selectedId = String(state.aiRoleplayCharacter?.id ?? "");
  const availableCharacters = favoriteCharactersFirst(state.characters.filter((character) => !character.mergedIntoCharacterId));
  const options = [{ id: "", name: "选择角色卡" }, ...availableCharacters.map((character) => ({
    id: String(character.id),
    name: roleplayCharacterOptionLabel(character)
  }))];
  if (selectedId && !options.some((option) => option.id === selectedId)) {
    options.push({ id: selectedId, name: roleplayCharacterOptionLabel(state.aiRoleplayCharacter) });
  }
  select.replaceChildren(...options.map((option) => {
    const element = document.createElement("option");
    element.value = option.id;
    element.textContent = option.name;
    return element;
  }));
  select.value = selectedId;
  const canSelectCharacter = Boolean(state.work)
    && canReadModule("characters")
    && canWritePermissionModule(state.work, "ai-chat");
  select.disabled = aiInteractionBusy() || !canSelectCharacter;
  select.title = canSelectCharacter
    ? state.aiPromptSent
      ? aiConversationOptionLockedMessage
      : "为当前对话选择角色卡；角色扮演时 Agent 可以查询角色记忆、相识角色、知情设定、故事正文和设定图片"
    : "当前账户没有角色模块读取权限";
  renderAiRoleplayUserCharacterSelect();
}

function renderAiRoleplayUserCharacterSelect() {
  const select = $("#ai-roleplay-user-character");
  const selectedId = String(state.aiRoleplayUserCharacter?.id ?? "");
  const aiCharacterId = String(state.aiRoleplayCharacter?.id ?? "");
  const availableCharacters = favoriteCharactersFirst(state.characters.filter((character) => (
    !character.mergedIntoCharacterId && String(character.id) !== aiCharacterId
  )));
  const options = [{ id: "", name: "选择我的角色（可选）" }, ...availableCharacters.map((character) => ({
    id: String(character.id),
    name: roleplayCharacterOptionLabel(character)
  }))];
  if (selectedId && !options.some((option) => option.id === selectedId)) {
    options.push({ id: selectedId, name: roleplayCharacterOptionLabel(state.aiRoleplayUserCharacter) });
  }
  select.replaceChildren(...options.map((option) => {
    const element = document.createElement("option");
    element.value = option.id;
    element.textContent = option.name;
    return element;
  }));
  select.value = selectedId;
  const canSelectCharacter = Boolean(state.work)
    && canReadModule("characters")
    && canWritePermissionModule(state.work, "ai-chat");
  select.disabled = aiInteractionBusy() || !canSelectCharacter || !state.aiRoleplayCharacter;
  select.title = !canSelectCharacter
    ? "当前账户没有角色模块读取权限"
    : !state.aiRoleplayCharacter
      ? "请先选择 AI 扮演的角色"
      : state.aiPromptSent
        ? aiConversationOptionLockedMessage
        : "选择后，主输入是该角色的台词或行动；旁白请写在场景框";
}

const aiConversationOptionLockedMessage = "会话选项在会话开始后不支持修改，若需要修改，请新建会话";

function aiConversationModelLocked() {
  return state.aiConversationHasImages === true
    || (typeof state.aiConversationModelId === "string" && state.aiConversationModelId.trim().length > 0);
}

function selectedAiModelLabel() {
  return $("#ai-model").selectedOptions[0]?.textContent?.trim() || "尚未选择模型";
}

function aiModelImageIconMarkup() {
  return '<svg class="ai-model-option-image-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="3.5" y="4.5" width="17" height="15" rx="2"></rect><circle cx="9" cy="10" r="1.5"></circle><path d="m5.5 17 4.4-4.4 3.3 3.1 2.2-2.2 3.1 3.5"></path></svg>';
}

function renderAiModelOptions() {
  const host = $("#ai-model-options");
  if (!host) return;
  const select = $("#ai-model");
  const selectedId = select.value;
  host.replaceChildren();
  if (state.models.length === 0) {
    const empty = document.createElement("p");
    empty.className = "ai-model-options-empty";
    empty.textContent = "请先配置模型";
    host.append(empty);
    return;
  }
  for (const model of state.models) {
    const option = document.createElement("button");
    option.type = "button";
    option.className = "ai-model-option";
    option.dataset.modelId = model.id;
    option.setAttribute("role", "option");
    option.setAttribute("aria-selected", String(model.id === selectedId));
    option.tabIndex = model.id === selectedId ? 0 : -1;
    option.disabled = aiInteractionBusy();
    option.title = model.multimodalEnabled === true ? "支持图片输入" : "不支持图片输入";
    const copy = document.createElement("span");
    copy.className = "ai-model-option-copy";
    const name = document.createElement("strong");
    name.textContent = String(model.displayName ?? model.modelId ?? "模型");
    const provider = document.createElement("small");
    provider.textContent = [String(model.providerName ?? "").trim(), modelThinkingEffortLabel(model)]
      .filter(Boolean)
      .join(" · ");
    copy.append(name, provider);
    option.append(copy);
    if (model.multimodalEnabled === true) {
      const icon = document.createElement("span");
      icon.className = "ai-model-option-image";
      icon.setAttribute("aria-label", "支持图片输入");
      icon.innerHTML = aiModelImageIconMarkup();
      option.append(icon);
    }
    option.addEventListener("click", () => {
      if (notifyAiConversationModelLocked(option)) return;
      select.value = model.id;
      select.dispatchEvent(new Event("change", { bubbles: true }));
    });
    host.append(option);
  }
}

function focusAiModelOption() {
  const host = $("#ai-model-options");
  if (!host) return;
  const selected = host.querySelector('[role="option"][aria-selected="true"]')
    ?? host.querySelector('[role="option"]');
  selected?.focus();
}

function syncAiModelPicker() {
  const select = $("#ai-model");
  const button = $("#ai-model-picker");
  const interactionBusy = aiInteractionBusy();
  const modelLocked = aiConversationModelLocked();
  const selectedLabel = selectedAiModelLabel();
  const label = modelLocked
    ? `当前模型：${selectedLabel}。${aiConversationOptionLockedMessage}`
    : `选择实际使用模型：${selectedLabel}`;
  select.disabled = interactionBusy;
  select.title = modelLocked ? aiConversationOptionLockedMessage : "";
  button.disabled = interactionBusy;
  button.title = label;
  button.setAttribute("aria-label", label);
  renderAiModelOptions();
  syncAiImageAttachmentControl();
  if (interactionBusy) setAiModelPickerVisible(false);
}

function notifyAiConversationOptionLocked(select, locked = state.aiPromptSent) {
  if (!locked) return false;
  const now = Date.now();
  const lastToastAt = Number(select.dataset.lockedToastAt ?? 0);
  if (now - lastToastAt > 500) toast(aiConversationOptionLockedMessage);
  select.dataset.lockedToastAt = String(now);
  return true;
}

function notifyAiConversationModelLocked(control) {
  return notifyAiConversationOptionLocked(control, aiConversationModelLocked());
}

function blockLockedAiConversationOptionInteraction(event) {
  const select = event.currentTarget;
  const locked = select.id === "ai-model"
    ? notifyAiConversationModelLocked(select)
    : notifyAiConversationOptionLocked(select);
  if (!locked) return;
  event.preventDefault();
  event.stopPropagation();
}

function blockLockedAiConversationOptionKeydown(event) {
  if (["Tab", "Shift", "Control", "Alt", "Meta"].includes(event.key)) return;
  blockLockedAiConversationOptionInteraction(event);
}

function syncAiTaskOptions() {
  const roleplaySelected = $("#ai-task").value === "roleplay";
  const relationshipRoleplaySelectable = roleplaySelected
    && Boolean(state.aiRoleplayCharacter)
    && (!state.aiPromptSent || Boolean(state.aiRoleplayUserCharacter));
  const interactionBusy = aiInteractionBusy();
  $("#ai-scope").classList.toggle("hidden", roleplaySelected);
  $("#ai-scope").setAttribute("aria-hidden", String(roleplaySelected));
  $("#ai-roleplay-character").classList.toggle("hidden", !roleplaySelected);
  $("#ai-roleplay-character").setAttribute("aria-hidden", String(!roleplaySelected));
  $("#ai-roleplay-user-character").classList.toggle("hidden", !relationshipRoleplaySelectable);
  $("#ai-roleplay-user-character").setAttribute("aria-hidden", String(!relationshipRoleplaySelectable));
  $("#ai-task").disabled = interactionBusy;
  $("#ai-task").title = state.aiPromptSent ? aiConversationOptionLockedMessage : "";
  $("#ai-scope").disabled = interactionBusy || roleplaySelected;
  $("#ai-scope").title = state.aiPromptSent
    ? aiConversationOptionLockedMessage
    : roleplaySelected ? "角色扮演模式可以查询角色记忆、相识角色、知情设定、故事正文和设定图片" : "";
  syncAiModelPicker();
  syncAiSceneComposer();
}

function applyAiConversationTaskType(taskType) {
  const normalizedTaskType = taskType === "roleplay" ? "roleplay" : "chat";
  state.aiTaskType = normalizedTaskType;
  const tab = activeAiChatTab();
  if (tab) tab.taskType = normalizedTaskType;
  $("#ai-task").value = normalizedTaskType;
  $("#ai-task").dataset.previousValue = normalizedTaskType;
  syncAiTaskOptions();
}

function applyAiConversationContextScope(scope) {
  const normalizedScope = scope && typeof scope === "object" ? JSON.parse(JSON.stringify(scope)) : { type: "none" };
  state.aiContextScope = normalizedScope;
  const tab = activeAiChatTab();
  if (tab) tab.contextScope = { ...normalizedScope };
  $("#ai-scope").value = normalizedScope.type === "book" ? "book"
    : normalizedScope.type === "volume" ? "volume"
    : normalizedScope.type === "chapter" && normalizedScope.includeBookSummary ? "chapter-summary"
    : normalizedScope.type === "chapter" ? "chapter"
    : "none";
  syncAiTaskOptions();
}

function applyAiRoleplayCharacter(character, userCharacter = null) {
  state.aiRoleplayCharacter = character?.id ? character : null;
  state.aiRoleplayUserCharacter = state.aiRoleplayCharacter && userCharacter?.id ? userCharacter : null;
  const tab = activeAiChatTab();
  if (tab) tab.roleplayCharacter = state.aiRoleplayCharacter ? { ...state.aiRoleplayCharacter } : null;
  if (tab) tab.roleplayUserCharacter = state.aiRoleplayUserCharacter ? { ...state.aiRoleplayUserCharacter } : null;
  const active = Boolean(state.aiRoleplayCharacter);
  if (active) $("#ai-scope").value = "none";
  $(".ai-panel").classList.toggle("is-roleplaying", active);
  $("#ai-prompt").dataset.placeholder = active
    ? state.aiRoleplayUserCharacter
      ? `以 ${String(state.aiRoleplayUserCharacter.name)} 的身份输入台词或行动……`
      : `输入对 ${String(state.aiRoleplayCharacter.name)} 说的台词或行动……`
    : "告诉 AI 你想讨论或修改什么……";
  renderAiRoleplayCharacterSelect();
  syncAiTaskOptions();
  renderAiQuickActions();
}

function refreshAiMessageRoleLabels() {
  $("#ai-feed").querySelectorAll(".assistant-message .message-heading > span").forEach((label) => {
    label.textContent = aiAssistantLabel();
  });
  $("#ai-feed").querySelectorAll(".user-message .message-heading > span").forEach((label) => {
    label.textContent = aiUserLabel();
  });
}

async function updateAiRoleplayCharacter(characterId, userCharacterId = null) {
  const conversationId = await ensureAiConversation();
  const conversation = await api(`/api/ai-conversations/${conversationId}/roleplay`, {
    method: "PATCH",
    body: { characterId: characterId || null, userCharacterId: userCharacterId || null }
  });
  upsertAiConversationSummary(conversation);
  applyAiConversationTaskType(conversation.taskType);
  applyAiRoleplayCharacter(conversation.roleplayCharacter, conversation.roleplayUserCharacter);
  resetAiContextMeter();
  if ($("#ai-feed").querySelector("[data-message-id]")) refreshAiMessageRoleLabels();
  else resetAiFeed();
  toast(conversation.roleplayCharacter
    ? conversation.roleplayUserCharacter
      ? `已进入 ${conversation.roleplayCharacter.name} 与 ${conversation.roleplayUserCharacter.name} 的关系扮演模式`
      : `已进入 ${conversation.roleplayCharacter.name} 的角色扮演模式`
    : "已退出角色扮演模式");
}

async function ensureAiConversation() {
  if (state.aiConversationId) return state.aiConversationId;
  await createNewAiConversation($("#ai-task").value);
  return state.aiConversationId;
}

async function persistAiConversationTaskType(taskType) {
  const conversationId = await ensureAiConversation();
  const conversation = await api(`/api/ai-conversations/${conversationId}/task-type`, {
    method: "PATCH",
    body: { taskType }
  });
  upsertAiConversationSummary(conversation);
  applyAiConversationTaskType(conversation.taskType);
  applyAiRoleplayCharacter(conversation.roleplayCharacter, conversation.roleplayUserCharacter);
  return conversation;
}

async function persistAiConversationContextScope(scope) {
  const conversationId = await ensureAiConversation();
  const conversation = await api(`/api/ai-conversations/${conversationId}/context-scope`, {
    method: "PATCH",
    body: { scope }
  });
  upsertAiConversationSummary(conversation);
  applyAiConversationContextScope(conversation.contextScope);
  return conversation;
}

async function prepareAiRequestConversation(requestHolder, taskType, scope) {
  let request = assertAiRequestCurrent(requestHolder.snapshot);
  const tab = aiChatTabForRequest(request);
  if (!tab) throw createAiRequestAbortError("Agent 对话页签已关闭");
  if (!request.conversationId) {
    const conversation = await api(`/api/works/${encodeURIComponent(request.workId)}/ai-conversations`, {
      method: "POST",
      body: { taskType },
      signal: request.signal
    });
    assertAiRequestCurrent(request);
    if (String(conversation.workId ?? "") !== request.workId) throw new Error("新对话不属于请求作品");
    applyNewAiConversation(conversation, tab);
    requestHolder.snapshot = aiRequestManager.bind(request, { conversationId: conversation.id });
    request = requestHolder.snapshot;
  }
  const taskConversation = await api(`/api/ai-conversations/${encodeURIComponent(request.conversationId)}/task-type`, {
    method: "PATCH",
    body: { taskType },
    signal: request.signal
  });
  assertAiRequestCurrent(request);
  upsertAiConversationSummary(taskConversation);
  tab.taskType = taskConversation.taskType;
  tab.roleplayCharacter = taskConversation.roleplayCharacter ?? null;
  tab.roleplayUserCharacter = taskConversation.roleplayUserCharacter ?? null;
  if (isActiveAiChatTab(tab)) {
    applyAiConversationTaskType(tab.taskType);
    applyAiRoleplayCharacter(tab.roleplayCharacter, tab.roleplayUserCharacter);
  }

  const scopedConversation = await api(`/api/ai-conversations/${encodeURIComponent(request.conversationId)}/context-scope`, {
    method: "PATCH",
    body: { scope },
    signal: request.signal
  });
  assertAiRequestCurrent(request);
  upsertAiConversationSummary(scopedConversation);
  tab.contextScope = scopedConversation.contextScope;
  if (isActiveAiChatTab(tab)) applyAiConversationContextScope(tab.contextScope);
  return request;
}

async function persistAiConversationMessage(conversationId, role, content, citations = [], metadata = {}, options = {}) {
  if (!conversationId) throw new Error("无法创建 AI 对话");
  return api(`/api/ai-conversations/${encodeURIComponent(conversationId)}/messages`, {
    method: "POST",
    body: {
      role,
      content,
      citations,
      metadata,
      ...(options.requestId ? { requestId: options.requestId } : {})
    },
    ...(options.signal ? { signal: options.signal } : {})
  });
}

async function persistAiRequestInterruption(request, interruption = null) {
  if (!request.conversationId || !request.userMessageId) return null;
  const partialContent = typeof interruption?.content === "string" && interruption.content.trim()
    ? interruption.content
    : null;
  const cancellationMessage = request.signal.reason instanceof Error
    ? request.signal.reason.message
    : "AI 请求已取消";
  const cancelledByClient = request.signal.reason?.code === "AI_REQUEST_CANCELLED";
  const metadata = cancelledByClient
    ? {
        ...(interruption?.metadata ?? {}),
        interrupted: true,
        interruptionCode: "AI_REQUEST_CANCELLED",
        interruptionMessage: cancellationMessage.slice(0, 500)
      }
    : interruption?.metadata ?? {
        interrupted: true,
        interruptionCode: "AI_REQUEST_CANCELLED",
        interruptionMessage: cancellationMessage.slice(0, 500)
      };
  try {
    const message = await persistAiConversationMessage(
      request.conversationId,
      "assistant",
      partialContent ?? "生成已终止，尚未收到可保留的回复内容。",
      [],
      metadata,
      { requestId: aiAssistantRequestId(request) }
    );
    updateAiConversationSummaryFromMessage(message);
    return message;
  } catch {
    return null;
  }
}

function promptTextFromNode(node, root = node) {
  if (node.nodeType === Node.TEXT_NODE) return node.textContent ?? "";
  if (!(node instanceof Element)) return "";
  if (node.matches("[data-ai-reference-key]")) return "";
  if (node.tagName === "BR") return "\n";
  const text = [...node.childNodes].map((child) => promptTextFromNode(child, root)).join("");
  return node !== root && ["DIV", "P"].includes(node.tagName) ? `${text}\n` : text;
}

function aiPromptText() {
  return promptTextFromNode($("#ai-prompt")).replace(/\n$/u, "");
}

function setAiPromptText(value) {
  const prompt = $("#ai-prompt");
  prompt.replaceChildren();
  if (value) prompt.append(document.createTextNode(value));
  renderAiReferences();
}

function activeAiModel() {
  const tab = activeAiChatTab();
  const selectedId = (isActiveAiChatTab(tab) ? $("#ai-model").value : "")
    || tab?.selectedModelId
    || state.aiConversationModelId
    || "";
  return state.models.find((model) => model.id === selectedId) ?? null;
}

function aiModelSupportsImageInput() {
  return activeAiModel()?.multimodalEnabled === true;
}

function syncAiImageAttachmentControl() {
  const button = $("#ai-attachment-button");
  if (!button) return;
  const enabled = aiModelSupportsImageInput();
  button.classList.toggle("hidden", !enabled);
  button.disabled = !enabled || aiInteractionBusy();
  button.setAttribute("aria-hidden", String(!enabled));
  button.title = enabled ? "添加图片附件" : "当前模型不支持图片输入";
}

function renderAiImageAttachments() {
  const host = $("#ai-image-attachments");
  if (!host) return;
  const attachments = normalizeAiChatImageAttachments(state.aiImageAttachments);
  state.aiImageAttachments = attachments;
  host.replaceChildren();
  host.classList.toggle("hidden", attachments.length === 0);
  host.setAttribute("aria-hidden", String(attachments.length === 0));
  for (const [index, attachment] of attachments.entries()) {
    const card = document.createElement("figure");
    card.className = "ai-image-attachment";
    card.dataset.attachmentId = attachment.id;
    const preview = document.createElement("button");
    preview.type = "button";
    preview.className = "ai-image-attachment-preview";
    preview.setAttribute("aria-label", `查看第 ${index + 1} 个图片附件：${attachment.originalName}`);
    preview.title = "点击查看原图";
    const image = document.createElement("img");
    image.src = attachment.contentUrl;
    image.alt = attachment.originalName;
    image.loading = "lazy";
    image.decoding = "async";
    const label = document.createElement("span");
    label.className = "ai-image-attachment-label";
    label.textContent = `#${index + 1}`;
    preview.append(image, label);
    preview.addEventListener("click", () => openAiImagePreview(attachment, index + 1));
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "ai-image-attachment-remove";
    remove.setAttribute("aria-label", `移除图片附件：${attachment.originalName}`);
    remove.title = "移除图片附件";
    remove.textContent = "×";
    remove.addEventListener("click", async () => {
      remove.disabled = true;
      state.aiImageAttachments = state.aiImageAttachments.filter((item) => item.id !== attachment.id);
      renderAiImageAttachments();
      persistActiveAiChatTab();
      try {
        await api(`/api/attachments/${encodeURIComponent(attachment.id)}`, { method: "DELETE" });
      } catch {
        /* 待发送附件从当前输入移除即可，未被历史消息引用的文件会由服务端回收。 */
      }
    });
    card.append(preview, remove);
    host.append(card);
  }
}

function openAiImagePreview(attachment, ordinal = null) {
  const dialog = $("#ai-image-preview-dialog");
  const image = $("#ai-image-preview-image");
  if (!dialog || !image) return;
  image.src = attachment.contentUrl;
  image.alt = attachment.originalName;
  $("#ai-image-preview-title").textContent = Number.isInteger(ordinal) ? `图片附件 #${ordinal}` : "图片附件";
  $("#ai-image-preview-meta").textContent = attachment.originalName;
  if (!dialog.open) dialog.showModal();
}

async function discardAiImageAttachments(attachments) {
  const ids = aiChatImageAttachmentIds(attachments);
  await Promise.all(ids.map((attachmentId) => api(`/api/attachments/${encodeURIComponent(attachmentId)}`, { method: "DELETE" }).catch(() => null)));
}

async function addAiImageFiles(files) {
  if (!aiModelSupportsImageInput()) {
    toast("当前选择的模型不是多模态模型，无法添加图片附件", "error");
    return;
  }
  const candidates = Array.from(files ?? []).filter(isAiChatImageFile);
  if (candidates.length === 0) {
    toast("图片附件仅支持 PNG、JPG、JPEG", "error");
    return;
  }
  const remaining = AI_CHAT_IMAGE_ATTACHMENT_MAX_COUNT - state.aiImageAttachments.length;
  if (remaining <= 0) {
    toast(`一次最多添加 ${AI_CHAT_IMAGE_ATTACHMENT_MAX_COUNT} 张图片附件`, "error");
    return;
  }
  if (candidates.length > remaining) toast(`一次最多添加 ${AI_CHAT_IMAGE_ATTACHMENT_MAX_COUNT} 张图片附件`, "error");
  for (const file of candidates.slice(0, remaining)) {
    try {
      assertAiChatImageFileSize(file);
      const body = new FormData();
      body.append("file", file, file.name || "pasted-image.png");
      const uploaded = await uploadWithProgress(
        `/api/works/${encodeURIComponent(state.work.id)}/attachments?module=ai-chat`,
        { method: "POST", body }
      );
      const attachment = normalizeAiChatImageAttachments([uploaded])[0];
      if (attachment) state.aiImageAttachments = normalizeAiChatImageAttachments([...state.aiImageAttachments, attachment]);
      renderAiImageAttachments();
    } catch (error) {
      toast(`图片附件上传失败：${error.message}`, "error");
    }
  }
  persistActiveAiChatTab();
}

function clearAiPromptComposer({ collapseScenePanel = false } = {}) {
  state.aiCitations = [];
  state.aiReferences = [];
  state.aiImageAttachments = [];
  state.aiSemanticSnapshot = null;
  setAiPromptText("");
  setAiSceneDirection("");
  renderAiCitations();
  renderAiImageAttachments();
  renderAiSemanticInjection();
  hideAiMentionMenu();
  syncAiSceneComposer();
  if (collapseScenePanel) setAiScenePanelExpanded(false);
}

function captureAiPromptComposer() {
  return {
    text: aiPromptText(),
    citations: state.aiCitations.map((citation) => ({ ...citation })),
    references: state.aiReferences.map((reference) => ({ ...reference })),
    images: normalizeAiChatImageAttachments(state.aiImageAttachments),
    semanticSnapshot: state.aiSemanticSnapshot ? structuredClone(state.aiSemanticSnapshot) : null,
    sceneDirection: aiSceneDirectionText(),
    scenePin: captureAiScenePin()
  };
}

function restoreAiPromptComposer(snapshot) {
  state.aiCitations = snapshot.citations.map((citation) => ({ ...citation }));
  state.aiReferences = snapshot.references.map((reference) => ({ ...reference }));
  state.aiImageAttachments = normalizeAiChatImageAttachments(snapshot.images);
  state.aiSemanticSnapshot = snapshot.semanticSnapshot ? structuredClone(snapshot.semanticSnapshot) : null;
  setAiPromptText(snapshot.text);
  restoreAiSceneComposer(snapshot);
  renderAiCitations();
  renderAiImageAttachments();
  renderAiSemanticInjection();
  hideAiMentionMenu();
}

function aiSceneDirectionText() {
  return String($("#ai-scene-direction")?.value ?? "");
}

function setAiSceneDirection(value) {
  const input = $("#ai-scene-direction");
  if (input) input.value = String(value ?? "");
}

function captureAiScenePin() {
  return normalizeRoleplayScenePin({
    location: $("#ai-scene-location")?.value ?? "",
    present: $("#ai-scene-present")?.value ?? "",
    timeLabel: $("#ai-scene-time")?.value ?? ""
  });
}

function setAiScenePin(pin) {
  const normalized = normalizeRoleplayScenePin(pin);
  const location = $("#ai-scene-location");
  const present = $("#ai-scene-present");
  const timeLabel = $("#ai-scene-time");
  if (location) location.value = normalized.location;
  if (present) present.value = normalized.present;
  if (timeLabel) timeLabel.value = normalized.timeLabel;
}

function restoreAiSceneComposer(snapshot = {}) {
  setAiSceneDirection(snapshot.sceneDirection ?? "");
  setAiScenePin(snapshot.scenePin);
  syncAiSceneComposer();
}

function roleplaySceneComposerVisible() {
  return $("#ai-task").value === "roleplay" && Boolean(state.aiRoleplayCharacter);
}

function setAiScenePanelExpanded(expanded) {
  const button = $("#ai-scene-button");
  const panel = $("#ai-scene-panel");
  if (!button || !panel) return;
  const nextExpanded = Boolean(expanded && !button.classList.contains("hidden"));
  panel.classList.toggle("hidden", !nextExpanded);
  button.setAttribute("aria-expanded", String(nextExpanded));
}

function syncAiSceneComposer() {
  const button = $("#ai-scene-button");
  const panel = $("#ai-scene-panel");
  if (!button || !panel) return;
  const visible = roleplaySceneComposerVisible();
  const busy = aiInteractionBusy();
  const readOnly = Boolean(state.work) && !canWritePermissionModule(state.work, "ai-chat");
  button.classList.toggle("hidden", !visible);
  button.disabled = !visible || busy || readOnly;
  button.setAttribute("aria-hidden", String(!visible));
  if (!visible) setAiScenePanelExpanded(false);
  const hasContent = Boolean(aiSceneDirectionText().trim()) || roleplayScenePinHasContent(captureAiScenePin());
  button.classList.toggle("is-active", hasContent);
}

function toggleAiScenePanel() {
  const button = $("#ai-scene-button");
  const panel = $("#ai-scene-panel");
  if (!button || !panel || button.classList.contains("hidden")) return;
  const willOpen = panel.classList.contains("hidden");
  setAiScenePanelExpanded(willOpen);
  if (willOpen) $("#ai-scene-direction")?.focus();
}

function aiPromptTextBeforeCursor() {
  const prompt = $("#ai-prompt");
  const selection = window.getSelection();
  if (!selection?.rangeCount || !prompt.contains(selection.anchorNode)) return aiPromptText();
  const range = selection.getRangeAt(0).cloneRange();
  range.selectNodeContents(prompt);
  range.setEnd(selection.anchorNode, selection.anchorOffset);
  const fragment = document.createElement("div");
  fragment.append(range.cloneContents());
  return promptTextFromNode(fragment).replace(/\n$/u, "");
}

function aiPromptTextFromRange(range, prompt) {
  const beforeCursor = range.cloneRange();
  beforeCursor.selectNodeContents(prompt);
  beforeCursor.setEnd(range.endContainer, range.endOffset);
  const fragment = document.createElement("div");
  fragment.append(beforeCursor.cloneContents());
  return promptTextFromNode(fragment).replace(/\n$/u, "");
}

function aiPromptTextBoundary(prompt, offset) {
  const walker = document.createTreeWalker(prompt, NodeFilter.SHOW_TEXT);
  let remaining = Math.max(0, Number(offset) || 0);
  let lastTextNode = null;
  while (walker.nextNode()) {
    const textNode = walker.currentNode;
    if (textNode.parentElement?.closest("[data-ai-reference-key]")) continue;
    lastTextNode = textNode;
    const length = textNode.textContent?.length ?? 0;
    if (remaining <= length) return { node: textNode, offset: remaining };
    remaining -= length;
  }
  if (lastTextNode) return { node: lastTextNode, offset: lastTextNode.textContent?.length ?? 0 };
  return { node: prompt, offset: prompt.childNodes.length };
}

function hideAiMentionMenu() {
  aiMentionMatch = null;
  aiSkillMatch = null;
  aiMentionRange = null;
  aiMentionActiveIndex = -1;
  const prompt = $("#ai-prompt");
  const menu = $("#ai-mention-menu");
  prompt.setAttribute("aria-expanded", "false");
  prompt.removeAttribute("aria-activedescendant");
  menu.querySelectorAll("[role=option]").forEach((option) => {
    option.classList.remove("is-active");
    option.setAttribute("aria-selected", "false");
  });
  menu.classList.add("hidden");
}

function setAiMentionActiveOption(nextIndex) {
  const prompt = $("#ai-prompt");
  const options = [...$("#ai-mention-menu").querySelectorAll("[role=option]")];
  if (!options.length) {
    aiMentionActiveIndex = -1;
    prompt.removeAttribute("aria-activedescendant");
    return null;
  }
  aiMentionActiveIndex = (nextIndex + options.length) % options.length;
  let activeOption = null;
  options.forEach((option, index) => {
    const active = index === aiMentionActiveIndex;
    option.classList.toggle("is-active", active);
    option.setAttribute("aria-selected", String(active));
    if (active) activeOption = option;
  });
  prompt.setAttribute("aria-activedescendant", activeOption.id);
  activeOption.scrollIntoView({ block: "nearest" });
  return activeOption;
}

function moveAiMentionActiveOption(direction) {
  const optionCount = $("#ai-mention-menu").querySelectorAll("[role=option]").length;
  if (!optionCount) return null;
  const nextIndex = aiMentionActiveIndex < 0
    ? (direction > 0 ? 0 : optionCount - 1)
    : aiMentionActiveIndex + direction;
  return setAiMentionActiveOption(nextIndex);
}

function syncAiReferencesWithPrompt() {
  const prompt = $("#ai-prompt");
  const activeKeys = new Set([...prompt.querySelectorAll("[data-ai-reference-key]")].map((chip) => chip.dataset.aiReferenceKey));
  const activeReferences = state.aiReferences.filter((reference) => activeKeys.has(aiReferenceKey(reference)));
  if (activeReferences.length !== state.aiReferences.length) {
    state.aiReferences = activeReferences;
    renderAiReferences();
  }
}

function updateAiMentionMenu() {
  syncAiReferencesWithPrompt();
  const prompt = $("#ai-prompt");
  const textBeforeCursor = aiPromptTextBeforeCursor();
  const skillMatch = $("#ai-task").value === "roleplay" ? null : findAiSkillCommand(textBeforeCursor);
  const mentionMatch = skillMatch ? null : findAiMention(textBeforeCursor);
  if (!skillMatch && !mentionMatch) return hideAiMentionMenu();
  const selection = window.getSelection();
  if (!selection?.rangeCount || !prompt.contains(selection.anchorNode)) return hideAiMentionMenu();
  aiSkillMatch = skillMatch;
  aiMentionMatch = mentionMatch;
  aiMentionRange = selection.getRangeAt(0).cloneRange();
  const menu = $("#ai-mention-menu");
  if (skillMatch) {
    const options = listAiSkillOptions(skillMatch.query);
    aiMentionActiveIndex = -1;
    prompt.removeAttribute("aria-activedescendant");
    menu.setAttribute("aria-label", "选择写作 Skill");
    menu.innerHTML = options.length
      ? options.map((item, index) => `<button id="ai-skill-option-${index}" class="ai-mention-option ai-skill-option" type="button" role="option" aria-selected="false" tabindex="-1" data-ai-skill-name="${esc(item.name)}"><small>Skill</small><span><strong>/${esc(item.name)}</strong><em>${esc(item.label)} · ${esc(item.description)}</em></span></button>`).join("")
      : '<p class="ai-mention-empty">没有匹配的写作 Skill</p>';
    menu.classList.remove("hidden");
    prompt.setAttribute("aria-expanded", "true");
    return;
  }
  const chapters = state.work?.volumes.flatMap((volume) => volume.chapters.map((chapter) => ({
    ...chapter,
    volumeTitle: volume.title
  }))) ?? [];
  const options = listAiMentionOptions(state.characters, state.settings, chapters, mentionMatch.query)
    .filter((item) => item.kind !== "context-settings" || $("#ai-task").value !== "roleplay");
  aiMentionActiveIndex = -1;
  prompt.removeAttribute("aria-activedescendant");
  menu.setAttribute("aria-label", "引用角色、设定、章节或上下文能力");
  menu.innerHTML = options.length
    ? options.map((item, index) => `<button id="ai-mention-option-${index}" class="ai-mention-option" type="button" role="option" aria-selected="false" tabindex="-1" data-ai-reference-kind="${esc(item.kind)}" data-ai-reference-id="${esc(item.id)}" data-ai-reference-name="${esc(item.name)}"><small>${esc(item.kindLabel)}</small><strong>${esc(item.name)}</strong></button>`).join("")
    : '<p class="ai-mention-empty">没有匹配的角色、设定、章节或上下文能力</p>';
  menu.classList.remove("hidden");
  prompt.setAttribute("aria-expanded", "true");
}

function selectAiMention(button) {
  if (!aiMentionMatch || !aiMentionRange) return;
  const prompt = $("#ai-prompt");
  const reference = {
    kind: button.dataset.aiReferenceKind,
    id: button.dataset.aiReferenceId,
    name: button.dataset.aiReferenceName
  };
  const cursorText = aiPromptTextFromRange(aiMentionRange, prompt);
  const localMention = findAiMention(cursorText);
  if (!localMention) return hideAiMentionMenu();
  const range = document.createRange();
  const startBoundary = aiPromptTextBoundary(prompt, localMention.start);
  const endBoundary = aiPromptTextBoundary(prompt, cursorText.length);
  range.setStart(startBoundary.node, startBoundary.offset);
  range.setEnd(endBoundary.node, endBoundary.offset);
  range.deleteContents();
  const spacer = document.createTextNode(" ");
  range.insertNode(spacer);
  if (!state.aiReferences.some((item) => aiReferenceKey(item) === aiReferenceKey(reference))) {
    state.aiReferences.push(reference);
    range.insertNode(createAiReferenceChip(reference));
  }
  const selection = window.getSelection();
  selection?.removeAllRanges();
  range.setStartAfter(spacer);
  range.collapse(true);
  selection?.addRange(range);
  prompt.focus();
  renderAiReferences();
  hideAiMentionMenu();
}

function selectAiSkill(button) {
  if (!aiSkillMatch || !aiMentionRange) return;
  const prompt = $("#ai-prompt");
  const cursorText = aiPromptTextFromRange(aiMentionRange, prompt);
  const localSkill = findAiSkillCommand(cursorText);
  if (!localSkill) return hideAiMentionMenu();
  const applied = applyAiSkillCommand(cursorText, localSkill, button.dataset.aiSkillName);
  const range = document.createRange();
  const startBoundary = aiPromptTextBoundary(prompt, localSkill.start);
  const endBoundary = aiPromptTextBoundary(prompt, cursorText.length);
  range.setStart(startBoundary.node, startBoundary.offset);
  range.setEnd(endBoundary.node, endBoundary.offset);
  range.deleteContents();
  const command = document.createTextNode(`${applied.command} `);
  range.insertNode(command);
  const selection = window.getSelection();
  selection?.removeAllRanges();
  range.setStartAfter(command);
  range.collapse(true);
  selection?.addRange(range);
  prompt.focus();
  hideAiMentionMenu();
}

function addSelectedLinesAsCitation() {
  if (!state.chapter || !chapterLineSelection) return;
  const selection = selectedChapterLinePayload(chapterLineSelection.start, chapterLineSelection.end);
  const citation = {
    id: `${state.chapter.id}:${selection.safeStart}:${selection.safeEnd}`,
    chapterId: state.chapter.id,
    chapterTitle: state.chapter.title,
    startLine: selection.safeStart + 1,
    endLine: selection.safeEnd + 1,
    text: selection.text
  };
  const existing = state.aiCitations.findIndex((item) => item.id === citation.id);
  if (existing < 0 && state.aiCitations.length >= 20) return toast("一次最多添加 20 条正文引用", "error");
  if (existing >= 0) state.aiCitations.splice(existing, 1, citation);
  else state.aiCitations.push(citation);
  ensureAiPanelExpanded();
  renderAiCitations();
  closeLineCitationMenu();
  toast(`已引用《${citation.chapterTitle}》第 ${citation.startLine}${citation.startLine === citation.endLine ? "" : `-${citation.endLine}`} 行`);
}

async function createSelectedLineAnnotation(kind) {
  const permissionModule = kind === "todo" ? "todos" : "comments";
  if (!state.chapter || !chapterLineSelection || !canWritePermissionModule(state.work, permissionModule)) return;
  const selection = selectedChapterLinePayload(chapterLineSelection.start, chapterLineSelection.end);
  closeLineCitationMenu();
  const note = await inputToast(kind === "todo" ? "描述需要后续处理的事项" : `评论第 ${selection.safeStart + 1} 行正文`, {
    title: kind === "todo" ? "添加正文待办" : "添加正文评论",
    inputLabel: kind === "todo" ? "待办内容" : "评论内容",
    confirmLabel: "添加",
    maxLength: 2000
  });
  if (!note) return;
  try {
    await api(`/api/chapters/${encodeURIComponent(state.chapter.id)}/annotations`, {
      method: "POST",
      body: { kind, startLine: selection.safeStart + 1, endLine: selection.safeEnd + 1, note }
    });
    toast(kind === "todo" ? "正文待办已添加" : "正文评论已添加");
    await loadChapterAnnotationCounts();
    await openChapterAnnotationsDialog(selection.safeStart);
  } catch (error) {
    toast(error.message, "error");
  }
}

function chapterAnnotationLineLabel(annotation) {
  return annotation.startLine === annotation.endLine
    ? `第 ${annotation.startLine} 行`
    : `第 ${annotation.startLine}-${annotation.endLine} 行`;
}

function chapterAnnotationStatusLabel(annotation) {
  if (annotation.status === "resolved") return annotation.kind === "todo" ? "已完成" : "已解决";
  return annotation.kind === "todo" ? "待处理" : "未解决";
}

function chapterAnnotationCard(annotation, { showSource = false } = {}) {
  const lineLabel = chapterAnnotationLineLabel(annotation);
  const sourceLabel = `${annotation.volumeTitle ?? "正文"} / ${annotation.chapterTitle ?? "未命名章节"}`;
  const heading = showSource
    ? `<strong class="chapter-annotation-source" title="${esc(sourceLabel)}">${esc(sourceLabel)}</strong><span class="chapter-annotation-line">${esc(lineLabel)}</span>`
    : `<strong>${esc(lineLabel)}</strong>`;
  return `<article class="chapter-annotation-card ${annotation.status === "resolved" ? "is-resolved" : ""}" data-annotation-id="${esc(annotation.id)}">
    <header><span class="chapter-annotation-kind">${annotation.kind === "todo" ? "待办" : "评论"}</span>${heading}<em>${esc(chapterAnnotationStatusLabel(annotation))}</em></header>
    <blockquote>${esc(annotation.quote || "空白行")}</blockquote>
    <p data-annotation-content>${esc(annotation.note)}</p>
    <small>${esc(annotation.actor)} · ${esc(formatDateTime(annotation.updatedAt))} · v${Number(annotation.versionNo)}</small>
    <footer><button type="button" data-annotation-locate>定位原文</button>${canManageChapterAnnotation(annotation) ? `<button type="button" data-annotation-edit>${annotation.kind === "todo" ? "编辑待办" : "编辑评论"}</button><button type="button" data-annotation-status>${annotation.status === "resolved" ? "重新打开" : (annotation.kind === "todo" ? "完成待办" : "解决评论")}</button><button class="danger-button" type="button" data-annotation-delete>${annotation.kind === "todo" ? "删除待办" : "删除评论"}</button>` : ""}</footer>
  </article>`;
}

function bindChapterAnnotationCards(host, annotations, { refresh, locate, overlayDialog = null }) {
  const suspendOverlay = () => {
    if (overlayDialog?.open) overlayDialog.close();
  };
  const resumeOverlay = () => {
    if (overlayDialog && !overlayDialog.open) overlayDialog.showModal();
  };
  host.querySelectorAll("[data-annotation-id]").forEach((card) => {
    const annotation = annotations.find((item) => item.id === card.dataset.annotationId);
    if (!annotation) return;
    card.querySelector("[data-annotation-locate]")?.addEventListener("click", async () => {
      try { await locate(annotation); }
      catch (error) { toast(error.message, "error"); }
    });
    card.querySelector("[data-annotation-status]")?.addEventListener("click", async () => {
      try {
        await api(`/api/chapter-annotations/${encodeURIComponent(annotation.id)}`, { method: "PATCH", body: { status: annotation.status === "resolved" ? "open" : "resolved", expectedVersionNo: annotation.versionNo } });
        await refresh();
      } catch (error) { toast(error.message, "error"); }
    });
    card.querySelector("[data-annotation-edit]")?.addEventListener("click", async () => {
      suspendOverlay();
      const note = await inputToast(annotation.kind === "todo" ? "修改待办内容" : "修改评论内容", {
        title: annotation.kind === "todo" ? "编辑待办" : "编辑评论",
        inputLabel: annotation.kind === "todo" ? "待办内容" : "评论内容",
        value: annotation.note,
        confirmLabel: "保存",
        maxLength: 2000
      });
      if (!note) return resumeOverlay();
      try {
        await api(`/api/chapter-annotations/${encodeURIComponent(annotation.id)}`, { method: "PATCH", body: { note, expectedVersionNo: annotation.versionNo } });
        await refresh();
      } catch (error) { toast(error.message, "error"); }
      resumeOverlay();
    });
    card.querySelector("[data-annotation-delete]")?.addEventListener("click", async () => {
      suspendOverlay();
      const confirmed = await confirmToast("删除后不会在正文评论中显示，但历史版本仍会保留。", {
        title: annotation.kind === "todo" ? "删除待办" : "删除评论",
        confirmLabel: "确认删除"
      });
      if (!confirmed) return resumeOverlay();
      try {
        await api(`/api/chapter-annotations/${encodeURIComponent(annotation.id)}`, { method: "DELETE", body: { expectedVersionNo: annotation.versionNo } });
        await refresh();
      } catch (error) { toast(error.message, "error"); }
      resumeOverlay();
    });
  });
}

function renderChapterAnnotations() {
  const host = $("#chapter-annotations-list");
  host.innerHTML = chapterAnnotations.length
    ? chapterAnnotations.map((annotation) => chapterAnnotationCard(annotation)).join("")
    : `<p class="entity-history-empty">${chapterAnnotationsLineIndex === null ? "本章还没有评论。在正文行上点击右键即可添加。" : `第 ${chapterAnnotationsLineIndex + 1} 行还没有评论或待办。`}</p>`;
  bindChapterAnnotationCards(host, chapterAnnotations, {
    refresh: async () => {
      await loadChapterAnnotationCounts();
      await loadChapterAnnotations(chapterAnnotationsLineIndex);
    },
    locate: (annotation) => {
      $("#chapter-annotations-dialog").close();
      revealChapterLines(annotation.startLine, annotation.endLine);
    },
    overlayDialog: $("#chapter-annotations-dialog")
  });
}

async function loadChapterAnnotationCounts(chapterId = state.chapter?.id) {
  if (!chapterId || !canReadModule("comments") && !canReadModule("todos")) {
    chapterAnnotationCounts = new Map();
    scheduleChapterLineNumbers();
    return;
  }
  const counts = await api(`/api/chapters/${encodeURIComponent(chapterId)}/annotation-counts`);
  if (String(state.chapter?.id ?? "") !== String(chapterId)) return;
  const savedLineIds = normalizeChapterLineIdDraft(state.chapter.content, state.chapter.lineIds);
  const draftLineIds = syncChapterDraftLineIds($("#chapter-content").value);
  const savedCounts = new Map(
    (Array.isArray(counts) ? counts : [])
      .map((item) => [Number(item.line), Number(item.count)])
      .filter(([line, count]) => Number.isInteger(line) && line > 0 && Number.isInteger(count) && count > 0)
  );
  chapterAnnotationCounts = remapChapterLineCounts(savedLineIds, draftLineIds, savedCounts);
  scheduleChapterLineNumbers();
}

async function loadChapterAnnotations(lineIndex = chapterAnnotationsLineIndex) {
  if (!state.chapter) return;
  const chapterId = state.chapter.id;
  const line = Number.isInteger(lineIndex) && lineIndex >= 0 ? lineIndex + 1 : null;
  const query = line === null ? "" : `?line=${encodeURIComponent(line)}`;
  const annotations = await api(`/api/chapters/${encodeURIComponent(chapterId)}/annotations${query}`);
  if (String(state.chapter?.id ?? "") !== String(chapterId)) return;
  chapterAnnotationsLineIndex = line === null ? null : line - 1;
  chapterAnnotations = annotations;
  renderChapterAnnotations();
}

async function openChapterAnnotationsDialog(lineIndex = null) {
  if (!state.chapter) return;
  chapterAnnotationsLineIndex = Number.isInteger(lineIndex) && lineIndex >= 0 ? lineIndex : null;
  const lineLabel = chapterAnnotationsLineIndex === null ? "" : `第 ${chapterAnnotationsLineIndex + 1} 行的`;
  $("#chapter-annotations-meta").textContent = `《${state.chapter.title}》${lineLabel}正文评论与待办`;
  $("#chapter-annotations-list").innerHTML = '<p class="entity-history-empty">正在加载评论…</p>';
  if (!$("#chapter-annotations-dialog").open) $("#chapter-annotations-dialog").showModal();
  try {
    await loadChapterAnnotations(chapterAnnotationsLineIndex);
  } catch (error) {
    $("#chapter-annotations-dialog").close();
    toast(error.message, "error");
  }
}

function closeLineCitationMenu() {
  $("#line-citation-menu").classList.add("hidden");
}

function showLineCitationMenu(event, lineIndex) {
  event.preventDefault();
  if (!chapterLineSelection || lineIndex < chapterLineSelection.start || lineIndex > chapterLineSelection.end) {
    paintChapterLineSelection(lineIndex, lineIndex);
    selectChapterLines(lineIndex, lineIndex);
  }
  const menu = $("#line-citation-menu");
  $("#add-line-annotation").classList.toggle("hidden", !canWritePermissionModule(state.work, "comments"));
  $("#add-line-todo").classList.toggle("hidden", !canWritePermissionModule(state.work, "todos"));
  const { start, end } = chapterLineSelection;
  $("#line-citation-label").textContent = start === end ? `第 ${start + 1} 行` : `第 ${start + 1}-${end + 1} 行`;
  menu.classList.remove("hidden");
  const rect = menu.getBoundingClientRect();
  menu.style.left = `${Math.max(8, Math.min(event.clientX, window.innerWidth - rect.width - 8))}px`;
  menu.style.top = `${Math.max(8, Math.min(event.clientY, window.innerHeight - rect.height - 8))}px`;
}

function clearChapterLineSelection() {
  chapterLineSelection = null;
  $("#chapter-line-numbers-inner")?.querySelectorAll(".is-line-selected").forEach((row) => {
    row.classList.remove("is-line-selected");
    row.querySelector(".chapter-line-number-select")?.setAttribute("aria-pressed", "false");
  });
}

const typographyStorageKey = "ai-novel-typography-v1";
const typographyDefaults = Object.freeze({ cjkFont: "system", latinFont: "system", fontSize: 17, uiFontSize: 14, aiFontSize: 12, density: "balanced" });
const cjkFontStacks = {
  system: '"PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Heiti SC"',
  pingfang: '"PingFang SC", "Heiti SC", "Microsoft YaHei", "Noto Sans CJK SC"',
  heiti: '"Heiti SC", "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC"',
  yahei: '"Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", "Heiti SC"',
  "noto-sans": '"Noto Sans CJK SC", "Source Han Sans SC", "PingFang SC", "Microsoft YaHei"'
};
const latinFontStacks = {
  system: '"SFMono-Regular", "SF Mono", Menlo, Monaco, Consolas, "Liberation Mono"',
  "sf-mono": '"SFMono-Regular", "SF Mono", Menlo, Monaco, Consolas, "Liberation Mono"',
  menlo: 'Menlo, Monaco, Consolas, "Liberation Mono", "SFMono-Regular"',
  monaco: 'Monaco, Menlo, Consolas, "Liberation Mono", "SFMono-Regular"',
  consolas: 'Consolas, "Liberation Mono", Menlo, Monaco, "SFMono-Regular"'
};
const typographyFontSizes = [15, 16, 17, 18, 20];
const typographyUiFontSizes = [14, 15, 16, 17, 18];
const typographyAiFontSizes = [12, 13, 14, 15, 16];
const densityLineHeights = { compact: 1.4, balanced: 1.55, relaxed: 1.75 };

function normalizeTypographySettings(input) {
  const value = input && typeof input === "object" ? input : {};
  const fontSize = Number(value.fontSize);
  const uiFontSize = Number(value.uiFontSize);
  const aiFontSize = Number(value.aiFontSize);
  return {
    cjkFont: Object.hasOwn(cjkFontStacks, value.cjkFont) ? value.cjkFont : typographyDefaults.cjkFont,
    latinFont: Object.hasOwn(latinFontStacks, value.latinFont) ? value.latinFont : typographyDefaults.latinFont,
    fontSize: typographyFontSizes.includes(fontSize) ? fontSize : typographyDefaults.fontSize,
    uiFontSize: typographyUiFontSizes.includes(uiFontSize) ? uiFontSize : typographyDefaults.uiFontSize,
    aiFontSize: typographyAiFontSizes.includes(aiFontSize) ? aiFontSize : typographyDefaults.aiFontSize,
    density: Object.hasOwn(densityLineHeights, value.density) ? value.density : typographyDefaults.density
  };
}

function loadTypographySettings() {
  try {
    return normalizeTypographySettings(JSON.parse(localStorage.getItem(typographyStorageKey) ?? "{}"));
  } catch {
    return { ...typographyDefaults };
  }
}

let typographySettings = loadTypographySettings();

function currentColorTheme() {
  return normalizeTheme(document.documentElement.dataset.theme, window.matchMedia?.("(prefers-color-scheme: dark)").matches ?? false);
}

function applyColorTheme(theme) {
  const normalized = normalizeTheme(theme);
  const root = document.documentElement;
  root.dataset.theme = normalized;
  root.style.colorScheme = normalized;
  const label = themeToggleLabel(normalized);
  const button = $("#theme-toggle");
  button.setAttribute("aria-label", label);
  button.setAttribute("title", label);
  button.setAttribute("aria-pressed", String(normalized === "dark"));
  const themeColor = document.querySelector('meta[name="theme-color"]');
  if (themeColor) themeColor.content = normalized === "dark" ? "#171714" : "#8b3d2c";
  [settingEditorVditor, knowledgeSectionVditor, characterSectionVditor].forEach((editor) => editor?.setTheme(normalized === "dark" ? "dark" : "classic"));
}

function saveColorTheme(theme) {
  const normalized = normalizeTheme(theme);
  applyColorTheme(normalized);
  try {
    localStorage.setItem(THEME_STORAGE_KEY, normalized);
    return true;
  } catch {
    return false;
  }
}

function applyTypographySettings(settings) {
  const normalized = normalizeTypographySettings(settings);
  const root = document.documentElement;
  root.style.setProperty("--font-cjk", cjkFontStacks[normalized.cjkFont]);
  root.style.setProperty("--font-latin", latinFontStacks[normalized.latinFont]);
  root.style.setProperty("--editor-font-size", `${normalized.fontSize}px`);
  root.style.setProperty("--editor-line-height", String(densityLineHeights[normalized.density]));
  root.style.setProperty("--ui-font-size", `${normalized.uiFontSize}px`);
  root.style.setProperty("--ui-font-scale", String(normalized.uiFontSize / typographyDefaults.uiFontSize));
  root.style.setProperty("--ai-font-size", `${normalized.aiFontSize}px`);
  root.style.setProperty("--ai-font-scale", String(normalized.aiFontSize / typographyDefaults.aiFontSize));
  root.dataset.cjkFont = normalized.cjkFont;
  root.dataset.latinFont = normalized.latinFont;
  root.dataset.fontSize = String(normalized.fontSize);
  root.dataset.uiFontSize = String(normalized.uiFontSize);
  root.dataset.aiFontSize = String(normalized.aiFontSize);
  root.dataset.density = normalized.density;
  scheduleChapterLineNumbers();
}

function saveTypographySettings(settings) {
  typographySettings = normalizeTypographySettings(settings);
  applyTypographySettings(typographySettings);
  try {
    localStorage.setItem(typographyStorageKey, JSON.stringify(typographySettings));
    return true;
  } catch {
    return false;
  }
}

function fillAppearanceForm(settings) {
  const normalized = normalizeTypographySettings(settings);
  $("#appearance-cjk-font").value = normalized.cjkFont;
  $("#appearance-latin-font").value = normalized.latinFont;
  $("#appearance-font-size").value = String(normalized.fontSize);
  $("#appearance-ui-font-size").value = String(normalized.uiFontSize);
  $("#appearance-ai-font-size").value = String(normalized.aiFontSize);
  $("#appearance-density").value = normalized.density;
}

function readAppearanceForm() {
  const form = new FormData($("#appearance-form"));
  return normalizeTypographySettings({
    cjkFont: form.get("cjkFont"),
    latinFont: form.get("latinFont"),
    fontSize: form.get("fontSize"),
    uiFontSize: form.get("uiFontSize"),
    aiFontSize: form.get("aiFontSize"),
    density: form.get("density")
  });
}

function renderTypographyPreview() {
  const settings = readAppearanceForm();
  const preview = $("#font-preview");
  preview.style.fontFamily = `${latinFontStacks[settings.latinFont]}, ${cjkFontStacks[settings.cjkFont]}, monospace, sans-serif`;
  preview.style.fontSize = `${settings.fontSize}px`;
  preview.style.lineHeight = String(densityLineHeights[settings.density]);
  $("#font-size-preview").textContent = `界面 ${settings.uiFontSize} px · Agent 对话 ${settings.aiFontSize} px`;
}

function openAppearanceDialog() {
  fillAppearanceForm(typographySettings);
  renderTypographyPreview();
  syncChapterWhitespaceControls();
  $("#appearance-dialog").showModal();
}

applyTypographySettings(typographySettings);
applyColorTheme(currentColorTheme());
applyPanelLayout();

function optimisticVersionForPath(path) {
  const normalizedPath = String(path).split("?")[0];
  const find = (items, id) => items.find((item) => String(item?.id ?? item?.chapterId ?? "") === id)?.versionNo;
  const workMatch = normalizedPath.match(/^\/api\/works\/([^/]+)(?:\/(?:cover|import|file-versions\/[^/]+\/restore))?$/u);
  if (workMatch) {
    const workId = decodeURIComponent(workMatch[1]);
    return state.works.find((item) => item.id === workId)?.versionNo ?? (state.work?.id === workId ? state.work.versionNo : undefined);
  }
  const resourceMatch = normalizedPath.match(/^\/api\/(volumes|chapters|settings|races|organizations|timeline-tracks|timeline|relationships|foreshadows|characters|character-sections)\/([^/]+)(?:\/(?:restore|move|split))?$/u);
  if (resourceMatch) {
    const resourceId = decodeURIComponent(resourceMatch[2]);
    const collection = {
      settings: state.settings,
      races: state.races,
      organizations: state.organizations,
      "timeline-tracks": state.timelineTracks,
      characters: state.characters
    }[resourceMatch[1]] ?? [];
    if (resourceMatch[1] === "chapters" && state.chapter?.id === resourceId) return state.chapter.versionNo;
    if (resourceMatch[1] === "volumes") return find(state.work?.volumes ?? [], resourceId);
    if (resourceMatch[1] === "character-sections") return find(characterEditorSections, resourceId);
    if (resourceMatch[1] === "characters" && characterEditorItem?.id === resourceId) return characterEditorItem.versionNo;
    if (resourceMatch[1] === "settings" && settingEditorItem?.id === resourceId) return settingEditorItem.versionNo;
    if (["races", "organizations"].includes(resourceMatch[1]) && knowledgeEditorItem?.id === resourceId) return knowledgeEditorItem.versionNo;
    return find(collection, resourceId);
  }
  const outlineMatch = normalizedPath.match(/^\/api\/chapters\/([^/]+)\/outline$/u);
  if (outlineMatch) return find(state.outlines ?? [], decodeURIComponent(outlineMatch[1]));
  const entityRestoreMatch = normalizedPath.match(/^\/api\/entity-versions\/(work|volume|setting|race|organization|timeline-track|timeline-event|relationship|chapter-outline|foreshadow)\/([^/]+)\/restore$/u);
  if (entityRestoreMatch) {
    const entityType = entityRestoreMatch[1];
    const entityId = decodeURIComponent(entityRestoreMatch[2]);
    if (entityType === "work") return state.works.find((item) => item.id === entityId)?.versionNo ?? (state.work?.id === entityId ? state.work.versionNo : undefined);
    if (entityType === "volume") return find(state.work?.volumes ?? [], entityId);
    if (entityType === "chapter-outline") return find(state.outlines ?? [], entityId);
    const collection = {
      setting: state.settings,
      race: state.races,
      organization: state.organizations,
      "timeline-track": state.timelineTracks
    }[entityType] ?? [];
    return find(collection, entityId);
  }
  return undefined;
}

function attachOptimisticVersion(path, method, body) {
  if (!["PATCH", "PUT", "DELETE", "POST"].includes(method)) return body;
  if (body instanceof FormData) {
    if (!body.has("expectedVersionNo")) {
      const versionNo = optimisticVersionForPath(path);
      if (Number.isInteger(versionNo) && versionNo > 0) body.append("expectedVersionNo", String(versionNo));
    }
    return body;
  }
  const currentBody = body && typeof body === "object" && !Array.isArray(body) ? body : {};
  if (currentBody.expectedVersionNo !== undefined) return currentBody;
  const versionNo = optimisticVersionForPath(path);
  return Number.isInteger(versionNo) && versionNo > 0 ? { ...currentBody, expectedVersionNo: versionNo } : body;
}

async function api(path, options = {}) {
  const method = String(options.method ?? "GET").toUpperCase();
  const body = options.skipOptimisticVersion ? options.body : attachOptimisticVersion(path, method, options.body);
  const headers = { ...(options.headers ?? {}) };
  if (state.csrfToken && !["GET", "HEAD", "OPTIONS"].includes(method)) headers["X-CSRF-Token"] = state.csrfToken;
  if (!(body instanceof FormData)) headers["Content-Type"] = "application/json";
  let response;
  try {
    response = await fetch(path, body instanceof FormData ? { ...options, body, headers } : {
      ...options,
      headers,
      body: body && typeof body !== "string" ? JSON.stringify(body) : body
    });
  } catch (error) {
    if (!isAiRequestCancellation(error)) updateSystemHealth({ status: "offline" });
    throw error;
  }
  updateSystemHealth({ status: response.status >= 500 ? "degraded" : "ready" });
  if (!response.ok) {
    const payload = await response.json().catch(() => ({ error: { message: `请求失败：${response.status}` } }));
    // Presence is best-effort; a heartbeat 401 must not force the login wall.
    if (response.status === 401 && !path.startsWith("/api/auth/") && !path.includes("/presence")) {
      const restarted = await checkSystemBoot(true);
      if (!restarted) {
        invalidateAuthentication();
      }
    }
    throw createClientError(payload.error, `请求失败：${response.status}`, response.status);
  }
  if (response.status === 204) {
    invalidateModuleRequestsAfterMutation(path, method);
    return null;
  }
  const payload = await response.json();
  if (path === "/api/health") {
    applyImageUploadLimits(payload.data?.uploadLimits);
    applyAiChatTabLimit(payload.data?.aiChatTabLimit);
    updateSystemHealth({
      status: payload.data?.status === "ok" ? "ready" : "degraded",
      version: payload.data?.version
    });
  }
  invalidateModuleRequestsAfterMutation(path, method);
  return payload.data;
}

function uploadWithProgress(path, options = {}, onProgress = () => {}) {
  const method = String(options.method ?? "GET").toUpperCase();
  const body = options.skipOptimisticVersion ? options.body : attachOptimisticVersion(path, method, options.body);
  if (!(body instanceof FormData)) return api(path, options);
  const headers = { ...(options.headers ?? {}) };
  if (state.csrfToken && !["GET", "HEAD", "OPTIONS"].includes(method)) headers["X-CSRF-Token"] = state.csrfToken;
  onProgress(0);
  return new Promise((resolve, reject) => {
    const request = new XMLHttpRequest();
    request.open(method, path, true);
    request.withCredentials = true;
    Object.entries(headers).forEach(([name, value]) => request.setRequestHeader(name, String(value)));
    request.upload.addEventListener("progress", (event) => {
      onProgress(event.lengthComputable && event.total > 0 ? (event.loaded / event.total) * 100 : null);
    });
    request.upload.addEventListener("load", () => onProgress(100));
    request.addEventListener("error", () => {
      updateSystemHealth({ status: "offline" });
      reject(new Error("网络连接失败"));
    });
    request.addEventListener("abort", () => reject(new Error("上传已取消")));
    request.addEventListener("load", async () => {
      const responseStatus = request.status;
      let payload = null;
      try {
        payload = request.responseText ? JSON.parse(request.responseText) : null;
      } catch {
        reject(new Error("服务器返回了无效响应"));
        return;
      }
      updateSystemHealth({ status: responseStatus >= 500 ? "degraded" : "ready" });
      if (responseStatus < 200 || responseStatus >= 300) {
        if (responseStatus === 401 && !path.startsWith("/api/auth/") && !path.includes("/presence")) {
          const restarted = await checkSystemBoot(true);
          if (!restarted) invalidateAuthentication();
        }
        const errorPayload = payload?.error;
        reject(createClientError(errorPayload, `请求失败：${responseStatus}`, responseStatus));
        return;
      }
      if (responseStatus === 204) {
        invalidateModuleRequestsAfterMutation(path, method);
        resolve(null);
        return;
      }
      if (!payload || typeof payload !== "object") {
        reject(new Error("服务器返回了无效响应"));
        return;
      }
      invalidateModuleRequestsAfterMutation(path, method);
      resolve(payload.data);
    });
    request.send(body);
  });
}

function createClientError(payload, fallbackMessage, fallbackStatus = null) {
  const source = payload && typeof payload === "object" && !Array.isArray(payload) ? payload : {};
  const error = new Error(typeof source.message === "string" ? source.message : fallbackMessage);
  error.code = typeof source.code === "string" ? source.code : undefined;
  error.status = Number.isInteger(source.status) ? source.status : fallbackStatus;
  error.details = source.details;
  error.failure = typeof source.failure === "string" ? source.failure : undefined;
  error.callId = typeof source.callId === "string" ? source.callId : undefined;
  error.providerName = typeof source.providerName === "string" ? source.providerName : undefined;
  error.providerId = typeof source.providerId === "string" ? source.providerId : undefined;
  error.modelId = typeof source.modelId === "string" ? source.modelId : undefined;
  error.modelRecordId = typeof source.modelRecordId === "string" ? source.modelRecordId : undefined;
  error.phase = typeof source.phase === "string" ? source.phase : undefined;
  error.idleTimeoutSeconds = typeof source.idleTimeoutSeconds === "number" ? source.idleTimeoutSeconds : undefined;
  return error;
}

function aiStreamInterruptionLabel(code) {
  if (code === "AI_STREAM_IDLE_TIMEOUT") return "网络超时";
  if (code === "AI_STREAM_NETWORK_ERROR") return "网络中断";
  if (code === "AI_STREAM_UPSTREAM_CLOSED") return "流被关闭";
  if (code === "AI_STREAM_REQUEST_CANCELLED") return "请求已取消";
  if (code === "AI_REQUEST_CANCELLED") return "已终止";
  return "生成中断";
}

function formatAiStreamInterruptionMeta(code, preservedCharacters) {
  const label = aiStreamInterruptionLabel(code);
  return preservedCharacters > 0 ? `${label} · 已保留 ${preservedCharacters} 字` : label;
}

function formatAiFailureMessage(error) {
  const message = error instanceof Error ? error.message : String(error ?? "未知错误");
  const lines = [`调用失败：${message}`];
  const code = typeof error?.code === "string" ? error.code : "";
  const status = Number.isInteger(error?.status) ? error.status : null;
  const details = error?.details && typeof error.details === "object" && !Array.isArray(error.details) ? error.details : {};
  const failure = typeof error?.failure === "string" ? error.failure : typeof details.failure === "string" ? details.failure : "";
  const callId = typeof error?.callId === "string" ? error.callId : typeof details.callId === "string" ? details.callId : "";
  const providerName = typeof error?.providerName === "string" ? error.providerName : typeof details.providerName === "string" ? details.providerName : "";
  const providerId = typeof error?.providerId === "string" ? error.providerId : typeof details.providerId === "string" ? details.providerId : "";
  const modelId = typeof error?.modelId === "string" ? error.modelId : typeof details.modelId === "string" ? details.modelId : "";
  if (code) lines.push(`错误码：${code}`);
  if (status) lines.push(`服务端状态：HTTP ${status}`);
  if (details.platformLimited === true) {
    const limitSource = details.limitScope === "provider"
      ? `配置的供应商额度${providerName ? `（${providerName}）` : ""}`
      : "单个小说额度";
    lines.push(`叙界平台限制来源：${limitSource}`);
  }
  if (providerName || providerId) lines.push(`模型供应商：${providerName || providerId}`);
  if (modelId) lines.push(`模型 ID：${modelId}`);
  if (callId) lines.push(`调用 ID：${callId}`);
  if (failure && failure !== message) lines.push(`详细原因：${failure}`);
  return lines.join("\n");
}

function isAgentToolCallLimitFailure(text) {
  return /more than \d+ tool calls in one response cycle\./u.test(String(text ?? ""));
}

function aiToolCallSettingsLinkMarkup(text) {
  if (!isAgentToolCallLimitFailure(text) || !state.work || !canReadModule("ai-settings")) return "";
  const href = serializePageRoute({ view: "module", workId: state.work.id, module: "ai-settings" });
  return `<p class="ai-error-settings-link-wrap"><a class="ai-error-settings-link" data-ai-tool-call-settings-link href="${esc(href)}">前往本书 AI 设置调整工具调用上限</a></p>`;
}

async function openAiToolCallSettings() {
  if (!state.work || !canReadModule("ai-settings")) return;
  await showModule("ai-settings");
  const target = document.getElementById("agent-tool-call-limit-settings");
  if (!target) return;
  target.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
  target.classList.add("is-targeted");
  window.setTimeout(() => target.classList.remove("is-targeted"), 1_800);
  const input = target.querySelector("#agent-tool-call-limit");
  if (input instanceof HTMLInputElement) input.focus({ preventScroll: true });
}

async function apiPage(path, page = 1, limit = 30) {
  const separator = path.includes("?") ? "&" : "?";
  const result = await api(`${path}${separator}page=${page}&limit=${limit}`);
  if (Array.isArray(result)) return { items: result, page, limit, hasMore: false, nextPage: null };
  return result;
}

async function apiAllPages(path, limit = 100) {
  const items = [];
  let page = 1;
  while (true) {
    const result = await apiPage(path, page, limit);
    items.push(...(result.items ?? []));
    if (!result.hasMore || !result.nextPage) return items;
    page = result.nextPage;
  }
}

function cachedModuleRequest(module, requestKey, loader, options = {}) {
  const workId = state.work?.id;
  if (!workId) return Promise.resolve().then(loader);
  return moduleRequestCache.request(workId, module, requestKey, loader, options);
}

function moduleApi(module, path, options = {}) {
  return cachedModuleRequest(module, `api:${path}`, () => api(path), options);
}

function moduleApiPage(module, path, page = 1, limit = 30, options = {}) {
  return cachedModuleRequest(module, `page:${path}:${page}:${limit}`, () => apiPage(path, page, limit), options);
}

function moduleApiAllPages(module, path, limit = 100, options = {}) {
  return cachedModuleRequest(module, `all:${path}:${limit}`, () => apiAllPages(path, limit), options);
}

function invalidateModuleRequestsAfterMutation(path, method) {
  if (["GET", "HEAD", "OPTIONS"].includes(method) || !state.work) return;
  if (
    path.startsWith("/api/auth/")
    || path.includes("/presence")
    || path.includes("/context/prepare")
    || path.includes("/chat/stream")
  ) return;

  const affected = new Set();
  if (path.includes("/ai-settings") || path.includes("/task-defaults") || path.includes("/providers") || path.includes("/models")) {
    affected.add("ai-settings");
  }
  if (path.includes("/tasks")) affected.add("tasks");
  if (path.includes("/drafts")) affected.add("drafts");
  if (path.includes("/settings") && !path.includes("/ai-settings")) affected.add("settings");
  if (path.includes("/characters") || path.includes("/character-sections")) affected.add("characters");
  if (path.includes("/races")) affected.add("races");
  if (path.includes("/organizations")) affected.add("organizations");
  if (path.includes("/timeline")) affected.add("timeline");
  if (path.includes("/outlines") || path.includes("/foreshadows") || path.includes("/foreshadow-reminders")) affected.add("outlines");
  if (path.includes("/relationships")) affected.add("relationships");
  if (path.includes("/chapter-annotations/") || /\/chapters\/[^/]+\/annotations(?:$|\?)/u.test(path)) affected.add("comments");
  if (path.includes("/reviews")) affected.add("reviews");
  if (/\/api\/works\/[^/]+\/replace(?:$|\?)/u.test(path)) {
    affected.add("settings");
    if (state.work?.id) moduleRequestCache.invalidate(state.work.id, "settings");
  }
  if (path.includes("/entity-versions/")) {
    if (path.includes("/draft/")) affected.add("drafts");
    if (path.includes("/setting/")) affected.add("settings");
    if (path.includes("/character/")) affected.add("characters");
    if (path.includes("/race/")) affected.add("races");
    if (path.includes("/organization/")) affected.add("organizations");
    if (path.includes("/timeline-event/") || path.includes("/timeline-track/")) affected.add("timeline");
    if (path.includes("/chapter-outline/") || path.includes("/foreshadow/")) affected.add("outlines");
    if (path.includes("/relationship/")) affected.add("relationships");
    if (path.includes("/review/")) affected.add("reviews");
  }
  if (cachedWorkModules.has(state.module)) affected.add(state.module);
  affected.forEach((module) => moduleRequestCache.invalidate(state.work.id, module));
}

function applyProductHealthMetadata(health) {
  const version = String(health?.version ?? "").trim();
  const versionLabel = String(health?.versionLabel ?? "").trim();
  document.querySelectorAll("[data-product-footer-version]").forEach((element) => {
    element.textContent = versionLabel || (version ? `v${version}` : "v—");
  });
  document.querySelectorAll("[data-product-footer-development]").forEach((element) => {
    element.classList.toggle("hidden", health?.development !== true);
  });
}

function applyProductUpdateMetadata(update) {
  if (update && typeof update === "object") productUpdateStatus = update;
  if (update?.checked !== true) {
    renderBackgroundTaskCenter();
    return;
  }
  const latestVersion = String(update.latestVersion ?? "").trim();
  const releaseUrl = String(update.releaseUrl ?? "").trim();
  const updateAvailable = update.updateAvailable === true && Boolean(latestVersion) && Boolean(releaseUrl);
  const updateDot = document.querySelector("[data-settings-update-dot]");
  updateDot?.classList.toggle("hidden", !updateAvailable);
  const settingsButton = $("#settings-button");
  settingsButton.setAttribute("aria-label", updateAvailable ? `设置，有新版本 v${latestVersion}` : "设置");
  settingsButton.title = updateAvailable ? `设置，有新版本 v${latestVersion}` : "设置";
  document.querySelectorAll("[data-product-footer-update]").forEach((element) => {
    element.classList.toggle("hidden", !updateAvailable);
    if (updateAvailable) {
      element.textContent = `发现新版本 v${latestVersion}，查看更新说明`;
      element.href = releaseUrl;
      element.setAttribute("aria-label", `查看叙界 v${latestVersion} 更新说明`);
    } else {
      element.textContent = "";
      element.removeAttribute("href");
      element.removeAttribute("aria-label");
    }
  });
  renderBackgroundTaskCenter();
}

function scheduleSystemHealthCheck() {
  if (systemHealthTimer !== null) window.clearTimeout(systemHealthTimer);
  systemHealthTimer = window.setTimeout(() => {
    systemHealthTimer = null;
    void refreshSystemHealth();
  }, systemHealthPollInterval);
}

async function refreshSystemHealth() {
  try {
    const health = await api("/api/health");
    applyProductHealthMetadata(health);
  } catch {
    // 系统状态已由 api 记录；健康检查失败不弹出重复提示
  } finally {
    scheduleSystemHealthCheck();
  }
}

function scheduleProductUpdateCheck() {
  if (productUpdateTimer !== null) window.clearTimeout(productUpdateTimer);
  if (productUpdateStatus?.enabled === false) {
    productUpdateTimer = null;
    return;
  }
  const nextCheckAt = Date.parse(String(productUpdateStatus?.nextCheckAt ?? ""));
  const delay = Number.isFinite(nextCheckAt)
    ? Math.max(1000, nextCheckAt - Date.now())
    : fallbackProductUpdatePollInterval;
  productUpdateTimer = window.setTimeout(() => {
    productUpdateTimer = null;
    void refreshProductUpdate();
  }, Math.min(delay, 2_147_483_647));
}

async function refreshProductUpdate() {
  if (productUpdateChecking || productUpdateStatus?.enabled === false) return;
  productUpdateChecking = true;
  renderBackgroundTaskCenter();
  try {
    applyProductUpdateMetadata(await api("/api/update-check"));
  } catch {
    // 更新探测失败时静默保留当前展示状态
  } finally {
    productUpdateChecking = false;
    renderBackgroundTaskCenter();
    scheduleProductUpdateCheck();
  }
}

async function initializeProductFooters() {
  const year = String(new Date().getFullYear());
  document.querySelectorAll("[data-product-footer-year]").forEach((element) => { element.textContent = year; });
  applyProductHealthMetadata(null);
  applyProductUpdateMetadata(null);
  await refreshSystemHealth();
  void refreshProductUpdate();
}

function observeSystemBootId(value) {
  const nextBootId = typeof value === "string" ? value.trim() : "";
  if (!nextBootId) return false;
  if (!systemBootId) {
    systemBootId = nextBootId;
    return false;
  }
  if (nextBootId === systemBootId) return false;
  systemRestartDetected = true;
  if (systemBootCheckTimer !== null) clearTimeout(systemBootCheckTimer);
  systemBootCheckTimer = null;
  if (systemRestartDialogTimer !== null) clearTimeout(systemRestartDialogTimer);
  systemRestartDialogTimer = window.setTimeout(() => {
    systemRestartDialogTimer = null;
    if (!systemRestartDetected) return;
    const dialog = $("#system-restart-dialog");
    if (!dialog.open) dialog.showModal();
    window.requestAnimationFrame(() => $("#system-restart-dialog-title").focus());
  }, systemRestartDialogDelay);
  return true;
}

async function checkSystemBoot(forceFresh = false) {
  if (!state.user || systemRestartDetected) return systemRestartDetected;
  if (systemBootCheckPromise) {
    if (!forceFresh) return systemBootCheckPromise;
    await systemBootCheckPromise;
    if (systemRestartDetected) return true;
  }
  systemBootCheckPromise = (async () => {
    try {
      const response = await fetch("/api/health", {
        cache: "no-store",
        headers: { Accept: "application/json" }
      });
      if (!response.ok) return false;
      const payload = await response.json();
      return observeSystemBootId(payload?.data?.bootId);
    } catch {
      return false;
    }
  })();
  try {
    return await systemBootCheckPromise;
  } finally {
    systemBootCheckPromise = null;
  }
}

function scheduleSystemBootCheck(delay = systemBootCheckInterval) {
  if (systemBootCheckTimer !== null) clearTimeout(systemBootCheckTimer);
  systemBootCheckTimer = null;
  if (!state.user || systemRestartDetected) return;
  systemBootCheckTimer = setTimeout(async () => {
    systemBootCheckTimer = null;
    await checkSystemBoot();
    scheduleSystemBootCheck();
  }, delay);
}

function selectAuthMode(mode) {
  const registerTab = $("#auth-register-tab");
  const login = mode === "login" || registerTab.disabled;
  $("#auth-login-tab").setAttribute("aria-selected", String(login));
  registerTab.setAttribute("aria-selected", String(!login));
  $("#login-form").classList.toggle("hidden", !login);
  $("#register-form").classList.toggle("hidden", login);
  $("#auth-error").textContent = "";
  // 验证码默认不加载，等用户点击“点击显示验证码”按钮后再请求，避免首屏空白等待
  resetAuthCaptcha(login ? "login" : "register");
}

function resetAuthCaptcha(target = "login") {
  const prefix = target === "register" ? "register" : "login";
  const image = $(`#${prefix}-captcha-image`);
  image.hidden = true;
  image.removeAttribute("src");
  $(`#${prefix}-captcha-placeholder`).hidden = false;
  $(`#${prefix}-captcha-id`).value = "";
  const answerInput = $(`#${prefix}-form`).querySelector('input[name="captchaAnswer"]');
  if (answerInput) answerInput.value = "";
}

async function refreshAuthCaptcha(target = "login") {
  const response = await fetch("/api/auth/captcha", { headers: { Accept: "application/json" } });
  if (!response.ok) throw new Error("无法加载验证码");
  const challenge = (await response.json()).data;
  const prefix = target === "register" ? "register" : "login";
  $(`#${prefix}-captcha-id`).value = challenge.captchaId;
  const image = $(`#${prefix}-captcha-image`);
  image.src = challenge.imageDataUrl;
  image.hidden = false;
  $(`#${prefix}-captcha-placeholder`).hidden = true;
  const answerInput = $(`#${prefix}-form`).querySelector('input[name="captchaAnswer"]');
  if (answerInput) answerInput.value = "";
}

function clearAuthenticationOverlays() {
  const toastRegion = $("#toast-region");
  toastRegion.replaceChildren();
  document.querySelectorAll("[popover]").forEach((popover) => {
    if (typeof popover.hidePopover === "function" && popover.matches(":popover-open")) popover.hidePopover();
  });
  document.querySelectorAll("dialog[open]").forEach((dialog) => dialog.close());
}

function invalidateAuthentication() {
  stopS3BackupEventPolling();
  state.user = null;
  state.csrfToken = null;
  moduleRequestCache.clear();
  showAuth(false);
}

function showAuth(setupRequired, registrationOpen = false, setupTokenRequired = false) {
  if (state.user) return;
  document.documentElement.classList.remove("dev-auth-bypass");
  document.documentElement.classList.add("login-route");
  window.history.replaceState(null, "", serializePageRoute({ view: "login" }));
  clearAuthenticationOverlays();
  document.body.classList.add("auth-pending");
  $("#auth-view").classList.remove("hidden");
  const canRegister = registrationOpen === true;
  $("#auth-title").textContent = setupRequired
    ? canRegister ? "创建首个管理员账户" : "注册已禁用"
    : "登录后继续创作";
  $("#auth-description").textContent = setupRequired
    ? canRegister
      ? "这是首次启动。首个注册用户会成为系统管理员，并接管现有作品。"
      : "请将 APP_ALLOW_REGISTRATION 设置为 true 后创建首个管理员账户。"
    : "你的作品、协作权限和每一次修改都会绑定到账户。";
  const registerTab = $("#auth-register-tab");
  registerTab.disabled = !canRegister;
  registerTab.setAttribute("aria-disabled", String(!canRegister));
  registerTab.textContent = canRegister ? "注册" : "注册已禁用";
  const setupTokenField = $("#register-setup-token-field");
  const setupTokenInput = setupTokenField.querySelector('input[name="setupToken"]');
  setupTokenField.classList.toggle("hidden", !setupTokenRequired);
  setupTokenInput.required = setupTokenRequired;
  selectAuthMode(setupRequired && canRegister ? "register" : "login");
}

function applyAuthenticatedUser(session) {
  state.user = session.user;
  state.csrfToken = session.csrfToken;
  const isSystemAdmin = session.user.isSystemAdmin === true;
  const accountButton = $("#account-button");
  $("#account-name").textContent = session.user.displayName;
  renderUserAvatar($("#account-avatar"), session.user);
  accountButton.setAttribute("aria-label", isSystemAdmin
    ? `账户：${session.user.displayName}，系统管理员`
    : `账户：${session.user.displayName}`);
  $("#account-admin-mark").classList.toggle("hidden", !isSystemAdmin);
  $("#account-menu-display-name").textContent = session.user.displayName;
  $("#account-menu-username").textContent = `@${session.user.username}`;
  $("#account-menu-role").textContent = isSystemAdmin ? "系统管理员" : "普通用户";
  $("#auth-view").classList.add("hidden");
  document.documentElement.classList.remove("login-route");
  if (!session.csrfToken) document.body.classList.remove("auth-pending");
  // 注意：auth-pending 由 initializePage 路由完成后才移除，
  // 避免会话确认后、目标视图渲染前露出无内容的编辑器外壳
}

function applyPlatformUiSettings(settings) {
  const position = settings?.toastPosition === "top-right" ? "top-right" : "bottom-right";
  state.uiSettings = {
    toastPosition: position,
    pageSizes: normalizePageSizes(settings?.pageSizes),
    galaxyFrameRate: normalizeGalaxyFrameRate(settings?.galaxyFrameRate)
  };
  $("#toast-region").dataset.position = position;
}

function pageSizeFor(module) {
  return normalizePageSize(state.uiSettings.pageSizes[module], defaultPageSizes[module] ?? 30);
}

function paginateModuleItems(items, page, sizeKey) {
  const limit = pageSizeFor(sizeKey);
  const total = items.length;
  const pageCount = Math.max(1, Math.ceil(total / limit));
  const safePage = Math.min(Math.max(1, Number(page) || 1), pageCount);
  const start = (safePage - 1) * limit;
  return {
    items: items.slice(start, start + limit),
    page: safePage,
    limit,
    total,
    pageCount,
    hasMore: safePage < pageCount,
    nextPage: safePage < pageCount ? safePage + 1 : null
  };
}

function renderModulePagination(pageResult, pageKey, label) {
  if (pageResult.pageCount <= 1) return "";
  return `<nav class="module-pagination" aria-label="${esc(label)}分页">
    <button type="button" data-module-page-key="${esc(pageKey)}" data-module-page="${pageResult.page - 1}" ${pageResult.page <= 1 ? "disabled" : ""}>上一页</button>
    <span>第 ${pageResult.page}/${pageResult.pageCount} 页 · 本页 ${pageResult.itemCount ?? pageResult.items.length} 条 · 共 ${pageResult.total} 条</span>
    <button type="button" data-module-page-key="${esc(pageKey)}" data-module-page="${pageResult.nextPage ?? pageResult.page + 1}" ${pageResult.hasMore ? "" : "disabled"}>下一页</button>
  </nav>`;
}

function bindModulePagination(pageKey, renderPage) {
  $("#module-content").querySelectorAll(`[data-module-page-key="${CSS.escape(pageKey)}"]`).forEach((button) => button.addEventListener("click", async () => {
    if (button.disabled) return;
    $("#module-content").querySelectorAll(`[data-module-page-key="${CSS.escape(pageKey)}"]`).forEach((control) => { control.disabled = true; });
    await renderPage(Number(button.dataset.modulePage));
  }));
}

async function loadPlatformUiSettings() {
  try {
    applyPlatformUiSettings(await api("/api/ui-settings"));
  } catch {
    applyPlatformUiSettings({ toastPosition: "bottom-right" });
  }
}

async function initializeAuthentication() {
  const route = parsePageRoute(window.location.hash);
  const response = await fetch("/api/auth/session", { headers: { Accept: "application/json" } });
  if (!response.ok) throw new Error("无法读取登录状态");
  const session = (await response.json()).data;
  if (!session.authenticated) {
    // 未登录时一律转到登录页路由；登录页本身则保持原样
    if (route.view !== "login") window.history.replaceState(null, "", serializePageRoute({ view: "login" }));
    showAuth(session.setupRequired, session.registrationOpen === true, session.setupTokenRequired === true);
    return false;
  }
  // 已登录却停在登录页路由时，回到书架首页
  if (route.view === "login") window.history.replaceState(null, "", serializePageRoute({ view: "shelf" }));
  observeSystemBootId(session.bootId);
  applyAuthenticatedUser(session);
  scheduleSystemBootCheck();
  await loadPlatformUiSettings();
  startS3BackupEventPolling();
  return true;
}

function syncToastRegionHost() {
  const region = $("#toast-region");
  const host = resolveToastRegionHost([...document.querySelectorAll("dialog[open]")], document.body);
  if (!host || region.parentElement === host) return false;
  if (typeof region.hidePopover === "function" && region.matches(":popover-open")) region.hidePopover();
  host.append(region);
  return true;
}

function raiseToastRegion() {
  const region = $("#toast-region");
  syncToastRegionHost();
  if (typeof region.showPopover !== "function") return;
  if (region.matches(":popover-open")) region.hidePopover();
  region.showPopover();
}

function dismissToastElement(element) {
  element.remove();
  const region = $("#toast-region");
  if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) {
    region.hidePopover();
  }
}

function dismissDeleteToasts() {
  const region = $("#toast-region");
  region.querySelectorAll(".delete-toast").forEach((element) => element.remove());
  if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) {
    region.hidePopover();
  }
}

function deleteToast(message) {
  toast(message);
  $("#toast-region").lastElementChild?.classList.add("delete-toast");
}

function dismissChapterInsightToast() {
  chapterInsightRequestId += 1;
  const region = $("#toast-region");
  region.querySelector(".chapter-insight-toast")?.remove();
  $("#insight-button").setAttribute("aria-expanded", "false");
  if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) {
    region.hidePopover();
  }
}

function toast(message, type = "info", extraClass = "") {
  if (systemRestartDetected || (!state.user && document.documentElement.classList.contains("login-route"))) return;
  const region = $("#toast-region");
  const element = document.createElement("div");
  element.className = `toast ${type}${extraClass ? ` ${extraClass}` : ""}`;
  element.setAttribute("role", type === "error" ? "alert" : "status");
  element.setAttribute("aria-atomic", "true");
  const messageContent = document.createElement("span");
  messageContent.textContent = message;
  element.append(messageContent);
  element.addEventListener("click", () => dismissToastElement(element), { once: true });
  region.append(element);
  raiseToastRegion();
  setTimeout(() => dismissToastElement(element), 3600);
}

async function runEntityEditorSave({ busyTarget, button, prepare, save }) {
  if (button.disabled) return null;
  const initialLabel = button.textContent;
  const initialInert = busyTarget.inert;
  const activeElement = document.activeElement;
  let focusTarget = busyTarget.contains(activeElement) ? activeElement : null;
  let finalLabel = initialLabel;
  button.disabled = true;
  try {
    // prepare 会在首次 await 前同步采集快照；同一事件循环内随即锁定，避免新的输入插入。
    const preparation = prepare();
    if (busyTarget.contains(document.activeElement)) focusTarget = document.activeElement;
    busyTarget.inert = true;
    busyTarget.setAttribute("aria-busy", "true");
    const prepared = await preparation;
    if (prepared === null) return null;
    button.textContent = "保存中…";
    toast("正在保存…");
    await new Promise((resolve) => window.setTimeout(resolve, 0));
    const result = await save(prepared);
    finalLabel = result?.buttonLabel ?? finalLabel;
    toast(result?.message ?? "保存成功");
    return result;
  } catch (error) {
    toast(error instanceof Error ? error.message : "保存失败，请重试", "error");
    return null;
  } finally {
    busyTarget.removeAttribute("aria-busy");
    busyTarget.inert = initialInert;
    button.disabled = false;
    button.textContent = finalLabel;
    if (!busyTarget.contains(document.activeElement) && focusTarget?.isConnected) {
      focusTarget.focus({ preventScroll: true });
    }
  }
}

function upsertEntityCollection(items, saved) {
  const nextItems = Array.isArray(items) ? [...items] : [];
  const index = nextItems.findIndex((item) => item.id === saved.id);
  if (index >= 0) nextItems[index] = saved;
  else nextItems.push(saved);
  return nextItems;
}

function persistentToast(message, type = "info") {
  const region = $("#toast-region");
  const element = document.createElement("div");
  element.className = `toast ${type}`;
  element.setAttribute("role", "status");
  const messageContent = document.createElement("span");
  messageContent.textContent = message;
  element.append(messageContent);
  element.addEventListener("click", () => dismissToastElement(element), { once: true });
  region.append(element);
  raiseToastRegion();
  return () => dismissToastElement(element);
}

function createImportProgressToast(fileName) {
  const region = $("#import-progress-region");
  const element = document.createElement("div");
  element.className = "toast import-progress-toast";
  element.setAttribute("role", "status");
  element.setAttribute("aria-atomic", "true");
  const copy = document.createElement("div");
  copy.className = "import-progress-copy";
  const title = document.createElement("strong");
  title.textContent = `正在导入“${fileName}”`;
  const status = document.createElement("span");
  status.className = "import-progress-status";
  status.textContent = "正在上传 · 0%";
  const progress = document.createElement("progress");
  progress.max = 100;
  progress.value = 0;
  progress.setAttribute("aria-label", "书籍导入上传进度");
  copy.append(title, status);
  element.append(copy, progress);
  region.append(element);
  if (typeof region.showPopover === "function" && !region.matches(":popover-open")) region.showPopover();
  let closed = false;
  return {
    update(uploadProgress) {
      if (closed) return;
      if (Number.isFinite(uploadProgress) && uploadProgress >= 100) {
        progress.removeAttribute("value");
        status.textContent = "上传完成，正在解析并写入作品…";
        return;
      }
      if (Number.isFinite(uploadProgress)) {
        const percentage = Math.max(0, Math.min(99, Math.round(uploadProgress)));
        progress.value = percentage;
        status.textContent = `正在上传 · ${percentage}%`;
      } else {
        progress.removeAttribute("value");
        status.textContent = "正在上传…";
      }
    },
    close() {
      if (closed) return;
      closed = true;
      element.remove();
      if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) {
        region.hidePopover();
      }
    }
  };
}

function restoreToastFocus(previousFocus) {
  if (
    previousFocus instanceof HTMLElement
    && previousFocus.isConnected
    && !previousFocus.matches(":disabled")
    && previousFocus.getClientRects().length > 0
  ) {
    previousFocus.focus({ preventScroll: true });
    if (document.activeElement === previousFocus) return;
  }
  const body = document.body;
  const previousTabIndex = body.getAttribute("tabindex");
  body.setAttribute("tabindex", "-1");
  body.focus({ preventScroll: true });
  if (previousTabIndex === null) body.removeAttribute("tabindex");
  else body.setAttribute("tabindex", previousTabIndex);
}

function confirmToast(message, { title = "请再次确认", confirmLabel = "确认", cancelLabel = "取消" } = {}) {
  const previousFocus = document.activeElement;
  const region = $("#toast-region");
  const element = document.createElement("section");
  element.className = "toast toast-confirmation";
  element.setAttribute("role", "alertdialog");
  element.setAttribute("aria-label", title);
  const heading = document.createElement("strong");
  heading.textContent = title;
  const description = document.createElement("p");
  description.textContent = message;
  const actions = document.createElement("div");
  actions.className = "toast-confirmation-actions";
  const cancel = document.createElement("button");
  cancel.className = "ghost-button";
  cancel.type = "button";
  cancel.textContent = cancelLabel;
  const confirm = document.createElement("button");
  confirm.className = "primary-button";
  confirm.type = "button";
  confirm.textContent = confirmLabel;
  actions.append(cancel, confirm);
  element.append(heading, description, actions);
  return new Promise((resolve) => {
    const finish = (confirmed) => {
      element.remove();
      if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) region.hidePopover();
      restoreToastFocus(previousFocus);
      resolve(confirmed);
    };
    cancel.addEventListener("click", () => finish(false), { once: true });
    confirm.addEventListener("click", () => finish(true), { once: true });
    element.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      finish(false);
    });
    region.append(element);
    raiseToastRegion();
    cancel.focus();
  });
}

function inputToast(message, { title = "请输入", inputLabel = title, value = "", placeholder = "", confirmLabel = "确认", cancelLabel = "取消", maxLength = 500 } = {}) {
  const region = $("#toast-region");
  const element = document.createElement("section");
  element.className = "toast toast-confirmation toast-input-dialog";
  element.setAttribute("role", "alertdialog");
  element.setAttribute("aria-label", title);
  const heading = document.createElement("strong");
  heading.textContent = title;
  const description = document.createElement("p");
  description.textContent = message;
  const input = document.createElement("input");
  input.className = "toast-input";
  input.type = "text";
  input.maxLength = maxLength;
  input.value = value;
  input.placeholder = placeholder;
  input.setAttribute("aria-label", inputLabel);
  const actions = document.createElement("div");
  actions.className = "toast-confirmation-actions";
  const cancel = document.createElement("button");
  cancel.className = "ghost-button";
  cancel.type = "button";
  cancel.textContent = cancelLabel;
  const confirm = document.createElement("button");
  confirm.className = "primary-button";
  confirm.type = "button";
  confirm.textContent = confirmLabel;
  actions.append(cancel, confirm);
  element.append(heading, description, input, actions);
  region.append(element);
  raiseToastRegion();
  input.focus();
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      element.remove();
      if (!region.childElementCount && typeof region.hidePopover === "function" && region.matches(":popover-open")) region.hidePopover();
      resolve(value);
    };
    cancel.addEventListener("click", () => finish(null), { once: true });
    confirm.addEventListener("click", () => finish(input.value.trim()), { once: true });
    element.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        finish(null);
      } else if (event.key === "Enter") {
        event.preventDefault();
        finish(input.value.trim());
      }
    });
  });
}

document.addEventListener("toggle", (event) => {
  const target = event.target;
  if (!(target instanceof HTMLDialogElement)) return;
  const region = $("#toast-region");
  if (target.open && region.childElementCount) {
    raiseToastRegion();
    return;
  }
  if (!target.open && (region.parentElement !== document.body || region.childElementCount)) {
    const moved = syncToastRegionHost();
    if (moved && region.childElementCount && typeof region.showPopover === "function") region.showPopover();
  }
}, true);

function paintTopbarStatus(text, { source, tone, title }) {
  const element = $("#save-state");
  const colors = { ok: "var(--green)", pending: "var(--muted)", error: "var(--accent)" };
  topbarStatusSource = source;
  element.textContent = text;
  element.style.color = colors[tone] ?? colors.ok;
  element.dataset.statusSource = source;
  element.setAttribute("aria-label", `${source === "system" ? "系统" : "工作台"}状态：${text}`);
  element.title = title || text;
}

function setTopbarViewState(text) {
  state.dirty = false;
  paintTopbarStatus(text, { source: "view", tone: "ok", title: text });
}

function updateSystemHealth(next) {
  systemHealthSnapshot = {
    ...systemHealthSnapshot,
    ...next,
    version: next.version === undefined ? systemHealthSnapshot.version : String(next.version ?? "")
  };
  if (topbarStatusSource === "system") renderSystemHealth();
}

function renderSystemHealth() {
  const presentation = systemStatusPresentation(systemHealthSnapshot);
  paintTopbarStatus(presentation.label, {
    source: "system",
    tone: presentation.tone,
    title: presentation.title
  });
}

function showSystemStatus() {
  state.dirty = false;
  topbarStatusSource = "system";
  renderSystemHealth();
}

function setSaveState(text, dirty = false) {
  state.dirty = dirty;
  paintTopbarStatus(text, {
    source: "save",
    tone: dirty ? "error" : "ok",
    title: text
  });
}

function resetChapterDraftLineIds(chapter = state.chapter) {
  chapterBeforeInputState = null;
  chapterDraftLineIdState = chapter ? {
    chapterId: chapter.id,
    content: String(chapter.content ?? ""),
    lineIds: normalizeChapterLineIdDraft(chapter.content, chapter.lineIds)
  } : null;
}

function syncChapterDraftLineIds(content, hint = null) {
  if (!state.chapter) return [];
  if (!chapterDraftLineIdState || chapterDraftLineIdState.chapterId !== state.chapter.id) {
    resetChapterDraftLineIds(state.chapter);
  }
  if (chapterDraftLineIdState.content !== content) {
    const beforeLineIds = chapterDraftLineIdState.lineIds;
    const lineIds = reconcileChapterLineIdDraft(
      chapterDraftLineIdState.content,
      content,
      beforeLineIds,
      hint
    );
    chapterAnnotationCounts = remapChapterLineCounts(beforeLineIds, lineIds, chapterAnnotationCounts);
    chapterDraftLineIdState = {
      chapterId: state.chapter.id,
      content,
      lineIds
    };
  }
  return chapterDraftLineIdState.lineIds;
}

function chapterDraftSnapshot() {
  if (!state.chapter) return null;
  const content = $("#chapter-content").value;
  const lineIds = syncChapterDraftLineIds(content);
  return {
    chapterId: state.chapter.id,
    title: $("#chapter-title").value.trim(),
    content,
    ...(lineIds.length <= MAX_CHAPTER_LINE_IDS ? { lineIds } : {})
  };
}

function sameChapterSnapshot(left, right) {
  return Boolean(left && right && left.chapterId === right.chapterId && left.title === right.title && left.content === right.content);
}

function cancelChapterAutoSave() {
  if (chapterAutoSaveTimer !== null) clearTimeout(chapterAutoSaveTimer);
  chapterAutoSaveTimer = null;
}

function scheduleChapterAutoSave(delay = chapterAutoSaveDelay) {
  if (!state.chapter || !canEditProse() || chapterEditorReadOnly) return;
  cancelChapterAutoSave();
  if (collaborationAutoSaveDisabled) {
    setSaveState("多人协作，自动保存已关闭", true);
    return;
  }
  setSaveState("等待自动保存", true);
  chapterAutoSaveTimer = setTimeout(() => {
    chapterAutoSaveTimer = null;
    persistChapter({ automatic: true });
  }, delay);
}

async function persistChapter({ automatic = false } = {}) {
  if (!canEditProse() || chapterEditorReadOnly) return null;
  if (!state.chapter) {
    if (!automatic) toast("请先选择章节", "error");
    return null;
  }
  cancelChapterAutoSave();
  if (automatic) {
    await refreshPresence();
    if (collaborationAutoSaveDisabled) {
      setSaveState("多人协作，自动保存已关闭", true);
      return null;
    }
  }
  if (chapterSaveInFlight) {
    await chapterSaveInFlight;
    const pendingDraft = chapterDraftSnapshot();
    if (!sameChapterSnapshot(pendingDraft, lastSavedChapterSnapshot)) return persistChapter({ automatic });
    return state.chapter;
  }
  if (chapterSaveGuardInFlight) {
    await chapterSaveGuardInFlight;
    return persistChapter({ automatic });
  }
  const draft = chapterDraftSnapshot();
  if (!draft?.title) {
    setSaveState("标题不能为空", true);
    if (!automatic) toast("章节标题不能为空", "error");
    return null;
  }
  if (sameChapterSnapshot(draft, lastSavedChapterSnapshot)) {
    setSaveState(automatic ? "已自动保存" : collaborationAutoSaveDisabled ? "已保存 · 自动保存已关闭" : "已保存");
    if (!automatic) await loadChapterForeshadowReminders();
    return state.chapter;
  }
  const saveGuard = confirmConcurrentSave();
  chapterSaveGuardInFlight = saveGuard;
  const confirmed = await saveGuard;
  if (chapterSaveGuardInFlight === saveGuard) chapterSaveGuardInFlight = null;
  if (!confirmed) {
    setSaveState("检测到同页协作，未保存", true);
    return null;
  }
  setSaveState(automatic ? "自动保存中" : "保存中", true);
  const workId = state.work.id;
  const request = (async () => {
    const chapter = await api(`/api/chapters/${draft.chapterId}`, {
      method: "PATCH",
      body: { title: draft.title, content: draft.content, lineIds: draft.lineIds, source: automatic ? "auto" : "manual" }
    });
    const work = await api(`/api/works/${workId}`);
    return { chapter, work };
  })();
  chapterSaveInFlight = request;
  try {
    const saved = await request;
    if (state.work?.id !== workId || state.chapter?.id !== draft.chapterId) return saved.chapter;
    state.chapter = saved.chapter;
    state.work = saved.work;
    resetChapterDraftLineIds(state.chapter);
    lastSavedChapterSnapshot = draft;
    renderTree();
    updateChapterStats();
    try {
      await loadChapterAnnotationCounts(saved.chapter.id);
    } catch (error) {
      toast("正文评论位置已更新，但评论数量刷新失败，请稍后重试", "error");
    }
    const currentDraft = chapterDraftSnapshot();
    if (sameChapterSnapshot(currentDraft, draft)) {
      setSaveState(automatic ? "已自动保存" : collaborationAutoSaveDisabled ? "已保存 · 自动保存已关闭" : "已保存");
    } else {
      scheduleChapterAutoSave(250);
    }
    await loadChapterForeshadowReminders();
    return state.chapter;
  } catch (error) {
    if (state.chapter?.id === draft.chapterId) setSaveState("自动保存失败", true);
    toast(error.message, "error");
    return null;
  } finally {
    if (chapterSaveInFlight === request) chapterSaveInFlight = null;
  }
}

async function confirmDiscardChanges(message = "当前章节有未保存修改，继续将丢弃这些修改。是否继续？") {
  if (!state.dirty) return true;
  return confirmToast(message, {
    title: "放弃未保存修改",
    confirmLabel: "放弃并继续",
    cancelLabel: "继续编辑"
  });
}

function chooseExistingWorkImportMode(file) {
  const dialog = $("#import-mode-dialog");
  const form = dialog.querySelector("form");
  const confirm = $("#import-mode-confirm");
  const canOverwrite = canReplaceProse();
  $("#import-mode-file-summary").textContent = `文件：${file.name}；当前作品：《${state.work.title}》`;
  $("#import-mode-unsaved-warning").classList.toggle("hidden", !state.dirty);
  form.reset();
  $("#import-mode-overwrite").disabled = !canOverwrite;
  $("#import-mode-overwrite-permission").classList.toggle("hidden", canOverwrite);
  confirm.disabled = true;
  form.onchange = () => { confirm.disabled = !form.querySelector('input[name="importMode"]:checked'); };
  dialog.returnValue = "cancel";
  dialog.showModal();
  $("#import-mode-dialog-title").focus();
  return new Promise((resolve) => {
    dialog.addEventListener("close", () => {
      const mode = form.querySelector('input[name="importMode"]:checked')?.value;
      resolve(dialog.returnValue === "confirm" && ["append", "overwrite"].includes(mode) ? mode : null);
    }, { once: true });
  });
}

function updateDocumentTitle(work = null) {
  const workTitle = String(work?.title ?? "").trim();
  document.title = workTitle ? `${workTitle} · 叙界` : platformDocumentTitle;
}

async function loadWorks(preferredId) {
  state.works = (await apiPage("/api/works")).items;
  if (preferredId) {
    await selectWork(preferredId);
    return;
  }
  showShelf();
}

function restoredSettingsReturnContext(route) {
  if (route.returnView === "module" && route.returnModule) return { view: "module", module: route.returnModule };
  if (route.returnView === "editor" && route.returnChapterId) return { view: "editor", chapterId: route.returnChapterId };
  if (route.returnView === "welcome") return { view: "welcome" };
  if (route.returnView === "shelf") return { view: "shelf" };
  if (state.work && state.chapter) return { view: "editor", chapterId: state.chapter.id };
  if (state.work) return { view: "welcome" };
  return { view: "shelf" };
}

async function initializePage() {
  const route = parsePageRoute(window.location.hash);
  const earlyReaderChapterRequest = window.__scriverseReaderChapterPrefetch;
  const earlyReaderWorksRequest = window.__scriverseReaderWorksPrefetch;
  const earlyReaderWorkRequest = window.__scriverseReaderWorkPrefetch;
  const [authenticated] = await Promise.all([initializeAuthentication(), initializeProductFooters()]);
  if (!authenticated) {
    restoringPageRoute = false;
    return;
  }
  const requestedWorkDetailRequest = route.workId
    ? earlyReaderWorkRequest?.workId === route.workId
      ? earlyReaderWorkRequest.request.then((result) => result.work ?? api(`/api/works/${encodeURIComponent(route.workId)}?directory=volumes`).catch(() => null))
      : api(`/api/works/${encodeURIComponent(route.workId)}?directory=volumes`).catch(() => null)
    : Promise.resolve(null);
  initialReaderChapterRequest = route.view === "reader" && route.chapterId
    ? earlyReaderChapterRequest?.chapterId === route.chapterId
      ? earlyReaderChapterRequest
      : {
        chapterId: route.chapterId,
        request: api(`/api/chapters/${encodeURIComponent(route.chapterId)}`)
          .then((chapter) => ({ chapter }), (error) => ({ error }))
      }
    : null;
  const [worksPage, requestedWorkDetail] = await Promise.all([
    earlyReaderWorksRequest?.request.then((result) => result.works ?? apiPage("/api/works")) ?? apiPage("/api/works"),
    requestedWorkDetailRequest
  ]);
  state.works = worksPage.items;
  initialWorkDetail = requestedWorkDetail;
  try {
    if (route.view === "shelf") {
      showShelf();
      return;
    }
    if (route.view === "im") {
      await imWorkspace.open();
      return;
    }

    const requestedWork = route.workId ? state.works.find((work) => work.id === route.workId) : null;
    if (route.workId && !requestedWork) {
      showShelf();
      return;
    }

    if (requestedWork) {
      state.module = route.view === "module"
        ? route.module
        : route.view === "entity-editor"
          ? ({ setting: "settings", character: "characters", race: "races", organization: "organizations" }[route.entity] ?? "characters")
          : "editor";
      await selectWork(requestedWork.id, route.view === "editor" ? route.chapterId : null);
    }

    if (route.view === "reader") {
      await openReadingPreview({ chapterId: route.chapterId, restorePosition: true });
      return;
    }
    if (route.view === "editor") {
      if (route.chapterId && state.chapter?.id !== route.chapterId) await selectChapter(route.chapterId);
      if (state.chapter?.id === route.chapterId && $("#editor-view").classList.contains("hidden")) await selectChapter(state.chapter.id);
      return;
    }
    if (route.view === "module") return;
    if (route.view === "entity-editor") {
      const item = route.entityId
        ? await api(`/api/${route.entity === "setting" ? "settings" : route.entity === "character" ? "characters" : route.entity === "race" ? "races" : "organizations"}/${encodeURIComponent(route.entityId)}`)
        : null;
      if (route.entityId && !item) {
        toast(({ setting: "未找到要编辑的设定", character: "未找到要编辑的角色", race: "未找到要编辑的种族", organization: "未找到要编辑的组织" }[route.entity] ?? "未找到要编辑的档案"), "error");
        return;
      }
      const options = { readOnly: route.entityMode === "read" };
      if (route.entity === "setting") await openSettingEditor(item, options);
      else if (route.entity === "character") await openCharacterEditor(item, options);
      else if (route.entity === "race") await openRaceDialog(item, options);
      else if (route.entity === "organization") await openOrganizationDialog(item, options);
      return;
    }
    if (route.view === "welcome") {
      showWelcome(true);
      return;
    }
    if (route.view === "settings") {
      await showSettingsHub();
      settingsReturnContext = restoredSettingsReturnContext(route);
      renderSettingsHub();
      return;
    }
    if (route.view === "platform-ai") {
      await showPlatformAi();
      settingsReturnContext = restoredSettingsReturnContext(route);
      return;
    }
    if (route.view === "platform-usage") {
      await showPlatformUsage();
      settingsReturnContext = restoredSettingsReturnContext(route);
      return;
    }
    if (route.view === "work-audit") {
      await showWorkAudit();
      settingsReturnContext = restoredSettingsReturnContext(route);
    }
  } finally {
    delete window.__scriverseReaderChapterPrefetch;
    delete window.__scriverseReaderWorksPrefetch;
    delete window.__scriverseReaderWorkPrefetch;
    initialWorkDetail = null;
    initialReaderChapterRequest = null;
    document.body.classList.remove("auth-pending");
    document.documentElement.removeAttribute("data-pending-view");
    document.documentElement.classList.remove("pending-shelf-mode");
    restoringPageRoute = false;
    replacePageRoute(currentPageRoute());
    scheduleFirstUseOnboarding();
  }
}

function showShelf() {
  imWorkspace.close();
  stopBackgroundTaskCenter();
  dismissChapterInsightToast();
  dismissDeleteToasts();
  state.dirty = false;
  settingsReturnContext = null;
  updateDocumentTitle();
  $("#app").classList.add("shelf-mode");
  $("#shelf-view").classList.remove("hidden");
  $("#platform-ai-view").classList.add("hidden");
  $("#platform-usage-view").classList.add("hidden");
  $("#work-audit-view").classList.add("hidden");
  $("#settings-hub-view").classList.add("hidden");
  $("#welcome-view").classList.add("hidden");
  $("#editor-view").classList.add("hidden");
  $("#module-view").classList.add("hidden");
  $("#work-meta").textContent = `${state.works.length} 部作品`;
  $("#settings-button").removeAttribute("aria-current");
  $("#top-search-button").disabled = true;
  setTopbarViewState("书架");
  renderShelf();
  replacePageRoute({ view: "shelf" });
}

function captureSettingsReturnContext() {
  if (!$("#shelf-view").classList.contains("hidden")) return { view: "shelf" };
  if (!$("#editor-view").classList.contains("hidden")) return { view: "editor", chapterId: state.chapter?.id ?? null };
  if (!$("#module-view").classList.contains("hidden")) return { view: "module", module: state.module };
  if (!$("#welcome-view").classList.contains("hidden")) return { view: "welcome" };
  return { view: state.work ? "editor" : "shelf", chapterId: state.chapter?.id ?? null };
}

function renderSettingsHub() {
  const hasWork = Boolean(state.work);
  const canManageWork = hasWork && ["admin", "owner"].includes(String(state.work.accessRole));
  const canReadAggregate = hasWork && canReadAggregateContent();
  const canExportManuscript = hasWork && canReadModule("editor");
  const isAdmin = state.user?.role === "admin";
  $("#platform-ai-button").classList.toggle("hidden", !isAdmin);
  $("#platform-usage-button").classList.toggle("hidden", !isAdmin);
  $("#platform-usage-pricing-refresh").classList.toggle("hidden", !isAdmin);
  $("#user-management-button").classList.toggle("hidden", !isAdmin);
  $("#admin-ai-conversations-button").classList.toggle("hidden", !isAdmin);
  $("#platform-ui-settings-button").classList.toggle("hidden", !isAdmin);
  $("#s3-backup-button").classList.toggle("hidden", !isAdmin);
  $("#collaboration-button").disabled = !canManageWork;
  $("#writing-progress-button").disabled = !hasWork || !canReadModule("editor");
  $("#work-audit-button").disabled = !canManageWork;
  $("#global-replace-button").classList.toggle("hidden", !canGlobalReplaceAny());
  $("#top-search-button").disabled = !canReadAggregate;
  $("#export-button").disabled = !canExportManuscript;
  $("#export-button").setAttribute("aria-expanded", "false");
  $("#settings-return").textContent = settingsReturnContext?.view === "shelf" || !hasWork ? "返回书架" : "返回当前作品";
  $("#settings-work-note").textContent = hasWork
    ? `当前作品：《${state.work.title}》。导出正文时可选择 Markdown ZIP 或 DOCX；DOCX 在有封面时会嵌入为首页。`
    : "当前未选择作品；打开作品后可使用导出。";
}

function renderWritingProgress(progress) {
  $("#writing-current-words").textContent = Number(progress.currentWords).toLocaleString("zh-CN");
  $("#writing-today-words").textContent = Number(progress.todayWords).toLocaleString("zh-CN");
  $("#writing-daily-completion").textContent = `${Math.round(Number(progress.dailyCompletion) * 100)}%`;
  $("#writing-total-completion").textContent = `${Math.round(Number(progress.totalCompletion) * 100)}%`;
  $("#writing-daily-goal").value = String(progress.goal.dailyGoal);
  $("#writing-total-goal").value = String(progress.goal.targetTotal);
  $("#writing-deadline").value = progress.goal.deadline ?? "";
  $("#writing-goal-save").disabled = !canEditProse();
  const maxWords = Math.max(1, ...progress.trend.map((item) => Number(item.words)));
  const maxDailyWords = Math.max(1, ...progress.trend.map((item) => Math.max(0, Number(item.delta))));
  const dailyPoints = progress.trend.map((item, index) => {
    const x = progress.trend.length > 0 ? (index + 0.5) / progress.trend.length * 1000 : 0;
    const y = 94 - Math.max(0, Number(item.delta)) / maxDailyWords * 88;
    return { x: x.toFixed(2), y: y.toFixed(2) };
  });
  const dailyLine = `<svg class="writing-trend-daily-line" viewBox="0 0 1000 100" preserveAspectRatio="none" aria-hidden="true"><polyline points="${dailyPoints.map((point) => `${point.x},${point.y}`).join(" ")}"></polyline></svg><span class="writing-trend-daily-points" aria-hidden="true">${dailyPoints.map((point) => `<i style="--point-x:${(Number(point.x) / 10).toFixed(2)}%;--point-y:${point.y}%"></i>`).join("")}</span>`;
  const chart = $("#writing-trend-chart");
  chart.innerHTML = progress.trend.map((item, index) => {
    const height = Math.max(3, Math.round(Number(item.words) / maxWords * 100));
    const dailyWords = Math.max(0, Number(item.delta));
    const label = `${item.date}：累计 ${Number(item.words).toLocaleString("zh-CN")} 字，当日新增 +${dailyWords.toLocaleString("zh-CN")} 字`;
    return `<span class="writing-trend-bar${index === progress.trend.length - 1 ? " is-today" : ""}" style="--bar-height:${height}%" data-writing-trend-label="${esc(label)}" tabindex="0" aria-label="${esc(label)}"><i></i><small>${index % 5 === 0 || index === progress.trend.length - 1 ? esc(item.date.slice(5)) : ""}</small></span>`;
  }).join("") + dailyLine + '<span class="writing-trend-legend" aria-hidden="true"><i></i>累计字数 <b></b>当日新增</span><output id="writing-trend-tooltip" class="writing-trend-tooltip" role="tooltip" hidden></output>';
  const tooltip = $("#writing-trend-tooltip");
  const hideTooltip = () => { tooltip.hidden = true; };
  const showTooltip = (bar) => {
    const marker = bar.querySelector("i");
    if (!marker) return;
    tooltip.textContent = bar.dataset.writingTrendLabel;
    tooltip.hidden = false;
    const chartRect = chart.getBoundingClientRect();
    const markerRect = marker.getBoundingClientRect();
    const centeredLeft = markerRect.left + markerRect.width / 2 - chartRect.left;
    const edgeInset = tooltip.offsetWidth / 2 + 8;
    tooltip.style.left = `${Math.min(chart.clientWidth - edgeInset, Math.max(edgeInset, centeredLeft))}px`;
    tooltip.style.top = `${Math.max(tooltip.offsetHeight + 8, markerRect.top - chartRect.top - 8)}px`;
  };
  chart.querySelectorAll(".writing-trend-bar").forEach((bar) => {
    bar.addEventListener("mouseenter", () => showTooltip(bar));
    bar.addEventListener("mouseleave", hideTooltip);
    bar.addEventListener("focus", () => showTooltip(bar));
    bar.addEventListener("blur", hideTooltip);
  });
}

async function loadWritingProgress() {
  if (!state.work) return;
  renderWritingProgress(await api(`/api/works/${encodeURIComponent(state.work.id)}/writing-progress`));
}

async function openWritingProgressDialog() {
  if (!state.work || !canReadModule("editor")) return;
  $("#writing-progress-dialog").showModal();
  try {
    await loadWritingProgress();
  } catch (error) {
    $("#writing-progress-dialog").close();
    toast(error.message, "error");
  }
}

