  sourceRef: "来源引用",
  changeNote: "变更说明",
  name: "名称",
  description: "说明",
  chapterType: "章节类型",
  volumeId: "所属分卷",
  previousVolumeId: "原分卷",
  sortOrder: "排序位置",
  timeLabel: "时间标签",
  location: "地点",
  eventType: "事件类型",
  batch: "批量操作",
  recoverable: "可恢复",
  excludedFromAnalysis: "排除 AI 分析",
