const globalReplaceScopeLabels = Object.freeze({
  prose: "正文",
  settings: "设定库",
  "prose-and-settings": "正文+设定库"
});

function syncGlobalReplaceScopeOptions() {
  const dialog = $("#replace-dialog");
  const options = [...dialog.querySelectorAll('input[name="replaceScope"]')];
  for (const option of options) {
    const allowed = canGlobalReplaceScope(option.value);
    option.disabled = !allowed;
    option.closest(".replace-scope-option")?.classList.toggle("is-disabled", !allowed);
  }
  const selected = options.find((option) => option.checked && !option.disabled) ?? options.find((option) => !option.disabled);
  options.forEach((option) => { option.checked = option === selected; });
  const scope = selected?.value ?? "";
  const volumeSelect = $("#replace-volume");
  const volumeEnabled = scope === "prose" || scope === "prose-and-settings";
  volumeSelect.disabled = !volumeEnabled || !canEditProse();
  $("#replace-volume-description").textContent = scope === "settings"
    ? "当前选择了设定库，分卷筛选不会生效。"
    : "选择分卷后，只替换该分卷的章节正文；设定库不按分卷筛选。";
  $("#replace-submit").disabled = !scope || !canGlobalReplaceScope(scope);
  $("#replace-permission-note").textContent = scope
    ? "替换完成后，命中的章节和设定会分别生成新的版本历史。"
    : "当前账户没有可写入的正文或设定库权限。";
}

function renderGlobalReplaceVolumeOptions() {
  const select = $("#replace-volume");
  const currentValue = select.value;
  const volumes = Array.isArray(state.work?.volumes) ? state.work.volumes : [];
  select.innerHTML = [
    '<option value="">全部分卷（整部作品正文）</option>',
    ...volumes.map((volume) => `<option value="${esc(volume.id)}">${esc(volume.title)}</option>`)
  ].join("");
  select.value = volumes.some((volume) => String(volume.id) === currentValue) ? currentValue : "";
}

function openGlobalReplaceDialog() {
  if (!state.work) {
    toast("请先打开一部作品", "error");
    return;
  }
  if (!canGlobalReplaceAny()) {
    toast("当前账户没有正文或设定库的编辑权限", "error");
    return;
  }
  if ($("#search-dialog").open) $("#search-dialog").close();
  $("#replace-form").reset();
  renderGlobalReplaceVolumeOptions();
  syncGlobalReplaceScopeOptions();
  $("#replace-dialog").showModal();
  queueMicrotask(() => $("#replace-find").focus());
}

async function refreshWorkAfterGlobalReplace(route, result) {
  const workId = state.work?.id;
  if (!workId) return;
  const previousVolumes = Array.isArray(state.work.volumes) ? state.work.volumes : [];
  const refreshPlan = buildGlobalReplaceRefreshPlan({
    volumes: previousVolumes,
    collapsedVolumeIds: state.collapsedVolumeIds,
    selectedChapterId: state.chapter?.id,
    selectedChapterVolumeId: state.chapter?.volumeId,
    routeChapterId: route.view === "editor" ? route.chapterId : null,
    scope: String(result?.scope ?? ""),
    chapterCount: result?.chapterCount,
    settingCount: result?.settingCount
  });
  const nextWork = result?.work ?? await api(`/api/works/${encodeURIComponent(workId)}?directory=volumes`);
  if (!nextWork || nextWork.id !== workId) return;
  const refreshGeneration = refreshPlan.proseChanged ? ++workScopedUiGeneration : workScopedUiGeneration;
  const previousVolumeById = new Map(previousVolumes.map((volume) => [volume.id, volume]));
  state.work = nextWork;
  state.work.volumes = (Array.isArray(state.work.volumes) ? state.work.volumes : []).map((volume) => {
    const previousVolume = previousVolumeById.get(volume.id);
    return {
      ...volume,
      chapterCount: resolveGlobalReplaceChapterCount(volume, previousVolume),
      chapters: refreshPlan.proseChanged
        ? []
        : Array.isArray(previousVolume?.chapters)
          ? previousVolume.chapters
          : Array.isArray(volume.chapters) ? volume.chapters : []
    };
  });
  state.works = state.works.map((work) => work.id === workId ? { ...work, ...nextWork } : work);
  if (refreshPlan.settingsChanged) state.settings = [];
  if (refreshPlan.proseChanged) {
    loadedVolumeChapterIds.clear();
    volumeChapterLoadingIds.clear();
    volumeChapterRequests.clear();
  }
  const expandedVolumeIds = new Set(refreshPlan.expandedVolumeIds);
  state.collapsedVolumeIds = new Set(state.work.volumes
    .filter((volume) => !expandedVolumeIds.has(volume.id))
    .map((volume) => volume.id));
  applyWorkAccessMode();
  showSystemStatus();
  updateDocumentTitle(state.work);
  $("#work-meta").textContent = `${state.work.title}${state.work.author ? ` · ${state.work.author}` : ""} · ${Number(state.work.wordCount ?? 0).toLocaleString("zh-CN")} 字`;
  $("#top-search-button").disabled = !canReadAggregateContent();
  renderTree();
  if (refreshPlan.proseChanged) {
    await Promise.all(refreshPlan.reloadVolumeIds.map((volumeId) => loadVolumeChapters(volumeId)));
    if (state.work?.id !== workId || refreshGeneration !== workScopedUiGeneration) return;
  }
  if (route.view === "editor" && route.chapterId && canReadModule("editor")) {
    if (refreshPlan.proseChanged) {
      state.chapter = null;
      lastSavedChapterSnapshot = null;
    }
    await selectChapter(route.chapterId);
    if (refreshPlan.proseChanged && state.chapter?.volumeId) await loadVolumeChapters(state.chapter.volumeId);
  } else if (refreshPlan.proseChanged && refreshPlan.selectedChapterId) {
    const chapter = await api(`/api/chapters/${encodeURIComponent(refreshPlan.selectedChapterId)}`);
    if (state.work?.id !== workId || refreshGeneration !== workScopedUiGeneration) return;
    state.chapter = chapter;
    resetChapterDraftLineIds(state.chapter);
    mergeChapterDirectoryEntry(chapter);
    lastSavedChapterSnapshot = { chapterId: chapter.id, title: chapter.title, content: chapter.content };
    await loadVolumeChapters(chapter.volumeId);
  } else if (route.view === "module") {
    await showModule(route.module);
  } else if (route.view === "settings") {
    renderSettingsHub();
    replacePageRoute({ view: "settings", workId: state.work.id, ...settingsRouteContext() });
  } else if (route.view === "welcome") {
    showWelcome(true);
  }
}

async function submitGlobalReplace(event) {
  event.preventDefault();
  if (!state.work) return;
  const find = $("#replace-find").value;
  const replacement = $("#replace-with").value;
  const scope = $("#replace-form").querySelector('input[name="replaceScope"]:checked')?.value ?? "prose";
  const volumeId = scope === "settings" ? null : ($("#replace-volume").value || null);
  if (!find.trim()) {
    toast("请输入要查找的内容", "error");
    $("#replace-find").focus();
    return;
  }
  if (!canGlobalReplaceScope(scope)) {
    toast("当前账户没有所选范围的编辑权限", "error");
    syncGlobalReplaceScopeOptions();
    return;
  }
  const dialog = $("#replace-dialog");
  const reopenDialog = () => {
    dialog.showModal();
    syncGlobalReplaceScopeOptions();
    queueMicrotask(() => $("#replace-find").focus());
  };
  dialog.close();
  if (state.dirty && !(await confirmDiscardChanges("当前章节有未保存修改，执行全局替换会放弃这些修改。是否继续？"))) {
    reopenDialog();
    return;
  }
  const scopeLabel = globalReplaceScopeLabels[scope] ?? "正文";
  const selectedVolume = volumeId
    ? state.work.volumes.find((volume) => String(volume.id) === volumeId)
    : null;
  const targetLabel = selectedVolume
    ? `${scopeLabel}（正文仅限“${selectedVolume.title}”分卷${scope === "prose-and-settings" ? "，设定库仍为全部设定库" : ""}）`
    : scopeLabel;
  const replacementLabel = replacement ? `“${replacement}”` : "空内容";
  const confirmed = await confirmToast(`将把《${state.work.title}》的${targetLabel}中所有“${find}”替换为${replacementLabel}。每个命中对象都会生成新版本，确认继续吗？`, {
    title: "确认全局替换",
    confirmLabel: "确认替换"
  });
  if (!confirmed) {
    reopenDialog();
    return;
  }
  const button = $("#replace-submit");
  const route = currentPageRoute();
  const workId = state.work.id;
  const hadDirtyDraft = state.dirty;
  button.disabled = true;
  button.textContent = "替换中…";
  cancelChapterAutoSave();
  state.dirty = false;
  let replacementApplied = false;
  const restoreDraftAfterNoop = () => {
    if (!hadDirtyDraft) return;
    if (state.chapter && canEditProse() && !chapterEditorReadOnly) scheduleChapterAutoSave();
    else state.dirty = true;
  };
  try {
    const result = await api(`/api/works/${encodeURIComponent(workId)}/replace`, {
      method: "POST",
      body: { find, replacement, scope, volumeId },
      skipOptimisticVersion: true
    });
    $("#replace-dialog").close();
    if (Number(result.totalMatches) > 0) {
      replacementApplied = true;
      await refreshWorkAfterGlobalReplace(route, result);
      if (Number(result.chapterCount) === 0) restoreDraftAfterNoop();
      const changedTargets = [];
      if (Number(result.chapterCount) > 0) changedTargets.push(`${result.chapterCount} 章`);
      if (Number(result.settingCount) > 0) changedTargets.push(`${result.settingCount} 条设定`);
      toast(`全局替换完成：${result.totalMatches} 处，已更新 ${changedTargets.join("、")}`);
    } else {
      restoreDraftAfterNoop();
      toast("没有找到需要替换的内容");
    }
  } catch (error) {
    if (!replacementApplied) restoreDraftAfterNoop();
    toast(error.message, "error");
  } finally {
    button.disabled = false;
    button.textContent = "开始替换";
    syncGlobalReplaceScopeOptions();
  }
}

function highlightedSearchText(value, query) {
  return splitGlobalSearchHighlight(value, query)
    .map((segment) => segment.match ? `<mark>${esc(segment.text)}</mark>` : esc(segment.text))
    .join("");
}

function renderSearchResults(results, query) {
  if (!results.length) {
    $("#search-results").innerHTML = '<p class="search-results-status">未找到相关内容。</p>';
    return;
  }
  const orderedResults = prioritizeGlobalSearchResults(results);
  const matchKindLabel = { metadata: "资料命中", exact: "精确命中", phonetic: "拼音命中" };
  $("#search-results").innerHTML = `<p class="search-results-summary">找到 ${orderedResults.length} 条结果，非正文结果优先，正文条目随后展示。</p>${orderedResults.map((item) => {
    const matchKinds = Array.isArray(item.matchKinds) ? item.matchKinds : [];
    const lineRange = Number.isInteger(item.startLine)
      ? `<span class="search-result-chip">${item.startLine === item.endLine ? `第 ${item.startLine} 行` : `第 ${item.startLine}-${item.endLine} 行`}</span>`
      : "";
    const subtitle = item.subtitle ? `<small>${esc(item.subtitle)}</small>` : "";
    return `
    <button type="button" class="search-result">
      <div class="search-result-meta"><span>${esc(searchResultTypeLabel(item.type))}</span><strong>${highlightedSearchText(item.title, query)}</strong></div>
      <p>${highlightedSearchText(item.snippet || "无摘要", query)}</p>
      <div class="search-result-details">${subtitle}${lineRange}${matchKinds.map((kind) => `<span class="search-result-chip search-result-chip-${esc(kind)}">${esc(matchKindLabel[kind] ?? kind)}</span>`).join("")}</div>
    </button>`;
  }).join("")}`;
  $("#search-results").querySelectorAll(".search-result").forEach((button, index) => {
    button.addEventListener("click", () => {
      openSearchResult(orderedResults[index])
        .catch((error) => toast(error.message, "error"));
    });
  });
}

async function runWorkSearch() {
  if (!state.work) throw new Error("请先打开一部作品");
  const query = $("#search-query").value.trim();
  if (!query) {
    $("#search-results").innerHTML = '<p class="search-results-empty">请输入关键词。</p>';
    return;
  }
  $("#search-results").innerHTML = '<p class="search-results-status">正在检索……</p>';
  const parameters = new URLSearchParams({ q: query });
  const type = $("#search-type").value;
  if (type) parameters.set("type", type);
  const results = await api(`/api/works/${encodeURIComponent(state.work.id)}/search?${parameters}`);
  renderSearchResults(results, query);
}

function revealChapterLines(startLine, endLine) {
  const start = Math.max(0, Number(startLine) - 1);
  const end = Math.max(start, Number(endLine ?? startLine) - 1);
  const input = $("#chapter-content");
  const selection = selectedChapterLinePayload(start, end);
  chapterLineSelection = { start: selection.safeStart, end: selection.safeEnd };
  input.focus({ preventScroll: true });
  input.setSelectionRange(selection.startOffset, selection.startOffset + selection.text.length);
  scheduleChapterLineNumbers();
  requestAnimationFrame(() => {
    renderChapterLineNumbers({ targetLineIndex: selection.safeStart });
    paintChapterLineSelection(selection.safeStart, selection.safeEnd);
  });
}

function openSearchEntityPreview(result, item) {
  const rowsByType = {
    "timeline-track": [["时间轴名称", item.name], ["简介", item.description], ["排序", item.sortOrder]],
    "timeline-event": [["事件名称", item.name], ["时间", item.timeLabel], ["类型", item.eventType], ["地点", item.location], ["说明", item.description], ["状态", item.status]],
    relationship: [["关系", result.title], ["大类", relationshipCategoryLabel(item.category)], ["子类", item.subtype], ["关键词", Array.isArray(item.keywords) ? item.keywords.join("、") : ""], ["当前状态", item.currentStatus], ["置信度", typeof item.confidence === "number" ? `${Math.round(item.confidence * 100)}%` : ""]],
    "chapter-outline": [["章节", item.chapterTitle], ["本章目标", item.goal], ["核心冲突", item.conflict], ["关键转折", item.turningPoint], ["补充说明", item.notes], ["规划状态", outlineStatusLabel(item.status)]],
    foreshadow: [["伏笔名称", item.title], ["内容与作用", item.description], ["重要程度", levelLabel(item.importance)], ["状态", foreshadowStatusLabel(item.status)], ["回收结论", item.resolutionNote]]
  };
  const rows = rowsByType[result.type] ?? [];
  const content = rows
    .filter(([, value]) => value !== undefined && value !== null && String(value).trim())
    .map(([label, value]) => `<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`)
    .join("");
  openDialog(
    result.title || searchResultTypeLabel(result.type),
    `<dl class="search-result-preview">${content || "<div><dt>详情</dt><dd>暂无补充信息</dd></div>"}</dl>`,
    async () => undefined,
    searchResultTypeLabel(result.type),
    { submitLabel: "关闭", hideCancel: true, wide: true }
  );
}

async function openSearchResult(result) {
  const target = resolveGlobalSearchTarget(result);
  if (!target) throw new Error("无法打开该搜索结果");
  $("#search-dialog").close();
  const inSettings = !$("#settings-hub-view").classList.contains("hidden")
    || !$("#platform-ai-view").classList.contains("hidden")
    || !$("#platform-usage-view").classList.contains("hidden")
    || !$("#work-audit-view").classList.contains("hidden");
  if (inSettings) await returnFromSettings();
  if (target.kind === "agent-history") {
    ensureAiPanelExpanded();
    await openAiConversation(target.conversationId, true, target.messageId);
    if (target.messageId) focusAiConversationMessage(target.messageId);
    return;
  }
  if (target.kind === "chapter") {
    await selectChapter(target.id);
    if (state.chapter?.id === target.id && target.startLine) {
      revealChapterLines(target.startLine, target.endLine);
      toast(target.startLine === target.endLine ? `已定位到第 ${target.startLine} 行` : `已定位到第 ${target.startLine}-${target.endLine} 行`);
    }
    return;
  }
  await showModule(target.module);
  if (state.module !== target.module) return;
  const item = await api(target.apiPath);
  if (target.entity === "setting") openSettingEditor(item, { readOnly: true });
  if (target.entity === "character") await openCharacterEditor(item, { readOnly: true });
  if (target.entity === "race") await openRaceDialog(item, { readOnly: true });
  if (target.entity === "organization") await openOrganizationDialog(item, { readOnly: true });
  if (target.entity === "review") openReviewDetailDialog(item);
  if (["timeline-track", "timeline-event", "relationship", "chapter-outline", "foreshadow"].includes(target.entity)) {
    openSearchEntityPreview(result, item);
  }
}

async function showSettingsHub() {
  imWorkspace.close();
  const alreadyInSettings = !$("#settings-hub-view").classList.contains("hidden")
    || !$("#platform-ai-view").classList.contains("hidden")
    || !$("#platform-usage-view").classList.contains("hidden")
    || !$("#work-audit-view").classList.contains("hidden");
  if (!alreadyInSettings) {
    if (state.dirty && !(await confirmDiscardChanges("当前章节有未保存修改，进入设置将放弃本地修改。是否继续？"))) return false;
    settingsReturnContext = captureSettingsReturnContext();
    state.dirty = false;
  }
  dismissChapterInsightToast();
  dismissTokenUsageDetails({ restoreFocus: false });
  dismissDeleteToasts();
  updateDocumentTitle(state.work);
  $("#app").classList.add("shelf-mode");
  $("#shelf-view").classList.add("hidden");
  $("#platform-ai-view").classList.add("hidden");
  $("#platform-usage-view").classList.add("hidden");
  $("#work-audit-view").classList.add("hidden");
  $("#settings-hub-view").classList.remove("hidden");
  $("#welcome-view").classList.add("hidden");
  $("#editor-view").classList.add("hidden");
  $("#module-view").classList.add("hidden");
  $("#work-meta").textContent = "设置中心";
  $("#settings-button").setAttribute("aria-current", "page");
  setTopbarViewState("设置");
  renderSettingsHub();
  replacePageRoute({ view: "settings", workId: state.work?.id ?? null, ...settingsRouteContext() });
  return true;
}

async function returnToSettingsHub(actionSelector, dialogSelector = null) {
  const dialog = dialogSelector ? $(dialogSelector) : null;
  if (dialog?.open) dialog.close();
  if (!(await showSettingsHub())) return;
  queueMicrotask(() => $(actionSelector)?.focus());
}

async function returnFromSettings() {
  const context = settingsReturnContext ?? { view: "shelf" };
  settingsReturnContext = null;
  $("#settings-button").removeAttribute("aria-current");
  $("#settings-hub-view").classList.add("hidden");
  $("#platform-ai-view").classList.add("hidden");
  $("#platform-usage-view").classList.add("hidden");
  $("#work-audit-view").classList.add("hidden");
  if (context.view === "shelf" || !state.work) return showShelf();
  $("#app").classList.remove("shelf-mode");
  $("#shelf-view").classList.add("hidden");
  updateDocumentTitle(state.work);
  $("#work-meta").textContent = `${state.work.title}${state.work.author ? ` · ${state.work.author}` : ""} · ${Number(state.work.wordCount ?? 0).toLocaleString("zh-CN")} 字`;
  if (context.view === "module") return showModule(context.module);
  if (context.view === "editor" && context.chapterId) return selectChapter(context.chapterId);
  return showWelcome(true);
}

