async function loadModels() {
  const workId = state.work?.id;
  if (!workId) return;
  const generation = workScopedUiGeneration;
  const models = await api(`/api/works/${workId}/models`);
  if (state.work?.id !== workId || generation !== workScopedUiGeneration) return;
  applyAiModels(models);
  loadedAiModelsWorkId = workId;
}

function applyAiModels(models) {
  state.models = models.filter((model) => isSelectableModel(model));
  const select = $("#ai-model");
  select.innerHTML = state.models.length
    ? state.models.map((model) => `<option value="${esc(model.id)}">${esc(modelOptionLabel(model))}</option>`).join("")
    : '<option value="">请先配置模型</option>';
  if (state.aiConversationModelId && state.models.some((model) => model.id === state.aiConversationModelId)) {
    select.value = state.aiConversationModelId;
  }
  setAiContextMeter(null);
  syncAiTaskOptions();
  syncAiModelPicker();
}

async function ensureAiModelsLoaded() {
  const workId = state.work?.id;
  if (!workId || loadedAiModelsWorkId === workId) return;
  if (aiModelsLoadPromise && aiModelsLoadWorkId === workId) return aiModelsLoadPromise;
  const select = $("#ai-model");
  select.innerHTML = '<option value="">正在加载模型……</option>';
  syncAiModelPicker();
  aiModelsLoadWorkId = workId;
  aiModelsLoadPromise = loadModels();
  try {
    await aiModelsLoadPromise;
  } catch (error) {
    if (state.work?.id === workId) {
      select.innerHTML = '<option value="">模型加载失败，点击重试</option>';
      syncAiModelPicker();
    }
    throw error;
  } finally {
    if (aiModelsLoadWorkId === workId) {
      aiModelsLoadPromise = null;
      aiModelsLoadWorkId = null;
    }
  }
}

function currentAiRequestScope() {
  if (!state.work) return null;
  const selectedTaskType = $("#ai-task").value;
  const roleplaySelected = selectedTaskType === "roleplay";
  const taskType = "chat";
  const scopeType = state.aiPromptSent
    ? null
    : roleplaySelected ? "none" : $("#ai-scope").value;
  if (!state.aiPromptSent && scopeType !== "none" && scopeType !== "settings-catalog" && !state.chapter) return null;
  const volume = state.chapter ? state.work.volumes.find((item) => item.id === state.chapter.volumeId) : null;
  const conversationScope = state.aiPromptSent
    ? JSON.parse(JSON.stringify(state.aiContextScope ?? { type: "none" }))
    : scopeType === "none" ? { type: "none" }
    : scopeType === "book" ? { type: "book" }
    : scopeType === "volume" ? { type: "volume", volumeId: volume?.id }
    : scopeType === "settings-catalog" ? { type: "settings-catalog" }
    : { type: "chapter", chapterId: state.chapter?.id };
  if (!state.aiPromptSent && scopeType === "chapter-summary") conversationScope.includeBookSummary = true;
  conversationScope.includeSettingInfo = false;
  const referencedScope = mergeAiReferenceScope(conversationScope, state.aiReferences);
  const chapterInput = state.chapter && !roleplaySelected ? $("#chapter-content") : null;
  const selectionStart = chapterInput?.selectionStart ?? 0;
  const selectionEnd = chapterInput?.selectionEnd ?? 0;
  const selection = chapterInput?.value.slice(selectionStart, selectionEnd) ?? "";
  const writingTarget = state.chapter && !roleplaySelected ? {
    chapterId: state.chapter.id,
    writingChapterVersion: state.chapter.versionNo,
    ...(selection ? { selection, selectionStart, selectionEnd } : {})
  } : {};
  const scope = { ...referencedScope, ...writingTarget };
  if (state.aiSemanticSnapshot?.id) scope.semanticSnapshotId = state.aiSemanticSnapshot.id;
  return { taskType, scope, conversationScope, selection };
}

function renderAiContextDistribution(usage) {
  const popover = $("#ai-context-popover");
  const host = $("#ai-context-distribution");
  const distribution = normalizeAiContextTokenDistribution(usage);
  const contextWindow = distribution.contextWindow.toLocaleString("zh-CN");
  $("#ai-context-popover-description").textContent = usage
    ? `已占用 ${distribution.occupiedTokens.toLocaleString("zh-CN")} / ${contextWindow} tok · ${formatAiContextUsagePercent(distribution.occupiedTokens, distribution.contextWindow)}`
    : "选择可用模型后显示当前上下文用量";
  host.replaceChildren(...distribution.items.map((item) => {
    const row = document.createElement("div");
    row.className = "ai-context-distribution-row";
    row.dataset.key = item.key;
    row.setAttribute("role", "listitem");
    row.setAttribute("aria-label", `${item.label}：${item.tokens.toLocaleString("zh-CN")} tok，占 ${item.percent}%`);

    const label = document.createElement("div");
    label.className = "ai-context-distribution-label";
    const title = document.createElement("span");
    title.textContent = item.label;
    if (item.key === "skills" || item.key === "input" || item.key === "output") {
      const description = document.createElement("small");
      description.textContent = item.key === "skills"
        ? item.tokens > 0 ? "按需加载" : "未加载"
        : item.key === "input" ? "用户和 agent 的交互" : "当前调用实际输出";
      title.append(" ", description);
    }
    const value = document.createElement("strong");
    value.textContent = `${item.tokens.toLocaleString("zh-CN")} tok · ${item.percent}%`;
    label.append(title, value);

    const track = document.createElement("div");
    track.className = "ai-context-distribution-track";
    track.setAttribute("aria-hidden", "true");
    const bar = document.createElement("span");
    bar.style.setProperty("--distribution-percent", String(item.percent));
    track.append(bar);
    row.append(label, track);
    return row;
  }));
  popover.dataset.hasUsage = String(Boolean(usage));
  return distribution;
}

function setAiContextMeter(usage, allowShrink = true) {
  const displayUsage = allowShrink
    ? resolveAiContextUsage(latestAiContextUsage, usage)
    : mergeAiContextUsage(latestAiContextUsage, usage, false);
  latestAiContextUsage = displayUsage;
  const meter = $("#ai-context-meter");
  const value = meter.querySelector("b");
  const distribution = renderAiContextDistribution(displayUsage);
  if (!displayUsage) {
    meter.classList.add("is-empty");
    meter.classList.remove("is-warning", "is-danger");
    meter.style.setProperty("--context-usage", "0");
    value.textContent = "—";
    const tooltip = formatAiContextUsageTooltip(null);
    meter.dataset.tooltip = tooltip;
    meter.setAttribute("aria-label", tooltip);
    return;
  }
  const percent = distribution.contextWindow > 0
    ? Math.min(100, distribution.occupiedTokens / distribution.contextWindow * 100)
    : 0;
  meter.classList.remove("is-empty");
  meter.classList.toggle("is-warning", percent >= 70 && percent < 90);
  meter.classList.toggle("is-danger", percent >= 90);
  meter.style.setProperty("--context-usage", String(percent));
  value.textContent = formatAiContextUsagePercent(distribution.occupiedTokens, distribution.contextWindow);
  const tooltip = formatAiContextUsageTooltip(displayUsage);
  meter.dataset.tooltip = tooltip;
  meter.setAttribute("aria-label", `当前上下文用量：${tooltip}`);
}

function resetAiContextMeter() {
  latestAiContextUsage = null;
  setAiContextMeter(null);
}

function setAiChatTabContextUsage(tab, usage, allowShrink = true) {
  if (!tab) return;
  if (isActiveAiChatTab(tab)) {
    setAiContextMeter(usage, allowShrink);
    tab.contextUsage = latestAiContextUsage;
    return;
  }
  tab.contextUsage = allowShrink
    ? resolveAiContextUsage(tab.contextUsage, usage)
    : mergeAiContextUsage(tab.contextUsage, usage, false);
}

function setAiContextDistributionVisible(visible) {
  const meter = $("#ai-context-meter");
  const popover = $("#ai-context-popover");
  popover.classList.toggle("hidden", !visible);
  meter.setAttribute("aria-expanded", String(visible));
  if (!visible && document.activeElement === $("#ai-context-popover-close")) meter.focus();
}

function setAiModelPickerVisible(visible) {
  const button = $("#ai-model-picker");
  const popover = $("#ai-model-popover");
  popover.classList.toggle("hidden", !visible);
  button.setAttribute("aria-expanded", String(visible));
  if (!visible && (document.activeElement === $("#ai-model") || document.activeElement?.closest("#ai-model-options"))) button.focus();
  if (visible) focusAiModelOption();
}

function showAiContextWarning(usage = null) {
  $("#ai-context-warning-title").textContent = "对话上下文过长";
  $("#ai-context-warning-message").textContent = "当前对话上下文过长，是否进行压缩？不压缩可能会导致后续请求失败";
  $("#ai-context-warning").classList.remove("hidden");
}

function hideAiContextWarning() {
  $("#ai-context-warning").classList.add("hidden");
}

function setAiChatTabContextWarning(tab, visible) {
  if (!tab) return;
  tab.contextWarning = visible;
  if (!isActiveAiChatTab(tab)) return;
  if (visible) showAiContextWarning();
  else hideAiContextWarning();
}

function setAiContextWarningActionsDisabled(disabled) {
  for (const button of $("#ai-context-warning").querySelectorAll("button")) button.disabled = disabled;
}

async function loadAiReferences() {
  const workId = state.work?.id;
  if (!workId) return;
  const generation = workScopedUiGeneration;
  const [characters, settings, races, organizations] = await Promise.all([
    canReadModule("characters") ? apiAllPages(`/api/works/${workId}/characters`) : Promise.resolve([]),
    canReadModule("settings") ? api(`/api/works/${workId}/settings/context`) : Promise.resolve([]),
    canReadModule("races") ? api(`/api/works/${workId}/races`) : Promise.resolve([]),
    canReadModule("organizations") ? apiAllPages(`/api/works/${workId}/organizations`) : Promise.resolve([])
  ]);
  if (state.work?.id !== workId || generation !== workScopedUiGeneration) return;
  state.characters = characters;
  state.settings = settings;
  state.races = races;
  state.organizations = organizations;
  renderAiRoleplayCharacterSelect();
  loadedAiReferencesWorkId = workId;
}

async function ensureAiReferencesLoaded() {
  const workId = state.work?.id;
  if (!workId || loadedAiReferencesWorkId === workId) return;
  if (aiReferencesLoadPromise && aiReferencesLoadWorkId === workId) return aiReferencesLoadPromise;
  aiReferencesLoadWorkId = workId;
  aiReferencesLoadPromise = loadAiReferences();
  try {
    await aiReferencesLoadPromise;
  } finally {
    if (aiReferencesLoadWorkId === workId) {
      aiReferencesLoadPromise = null;
      aiReferencesLoadWorkId = null;
    }
  }
}

function field(name, label, type = "text", value = "", options = []) {
  if (type === "textarea") return `<label>${esc(label)}<textarea name="${esc(name)}">${esc(value)}</textarea></label>`;
  if (type === "markdown") return `<div class="form-field markdown-editor-field${options.readOnly ? " is-read-only" : ""}" data-vditor-editor-field><span>${esc(label)}</span><div class="vditor-editor-host" data-vditor-editor data-attachment-module="${esc(options.attachmentModule ?? "settings")}" data-placeholder="${esc(options.placeholder ?? `在这里编辑${label}`)}" aria-label="${esc(label)} Markdown 编辑器"${options.readOnly ? ' aria-readonly="true"' : ""}></div><textarea class="hidden" name="${esc(name)}" data-vditor-value maxlength="200000" aria-label="${esc(label)} Markdown 原文" ${options.readOnly ? "readonly" : ""}>${esc(value)}</textarea></div>`;
  if (type === "item-list") {
    const values = Array.isArray(value) && value.length ? value : [""];
    return `<div class="form-field item-list-field"><span>${esc(label)}</span><div class="item-list-rows" data-item-list-rows data-name="${esc(name)}" data-label="${esc(label)}">${values.map((item) => `<div class="item-list-row"><input name="${esc(name)}" value="${esc(item)}" aria-label="${esc(label)}"><button type="button" data-item-list-remove aria-label="删除此条">删除</button></div>`).join("")}</div><button class="item-list-add" type="button" data-item-list-add>添加一条</button></div>`;
  }
  if (type === "keyword-chips") {
    const chipLabel = String(label).includes("关键词") ? "关键词" : label;
    const values = uniqueRelationshipKeywords(Array.isArray(value) ? value : []);
    const chips = values.map((keyword) => `<span class="keyword-chip" data-keyword-chip><span>${esc(keyword)}</span><input type="hidden" name="${esc(name)}" value="${esc(keyword)}" data-keyword-value><button type="button" data-keyword-chip-remove aria-label="删除${esc(chipLabel)}：${esc(keyword)}">×</button></span>`).join("");
    return `<div class="form-field keyword-chip-field" data-keyword-chips data-name="${esc(name)}" data-remove-label="${esc(chipLabel)}"><span>${esc(label)}</span><div class="keyword-chip-editor" role="group" aria-label="${esc(label)}">${chips}<input type="text" data-keyword-input aria-label="${esc(label)}" placeholder="输入${esc(chipLabel)}后按回车添加，逗号可批量添加" autocomplete="off"></div><small>输入${esc(chipLabel)}后按回车添加；也可用逗号一次添加多个。</small></div>`;
  }
  if (type === "key-value-list") {
    const config = Array.isArray(options) ? {} : options;
    const keyName = config.keyName ?? "detailLabel";
    const valueName = config.valueName ?? "detailValue";
    const keyPlaceholder = config.keyPlaceholder ?? "字段名，如身高";
    const valuePlaceholder = config.valuePlaceholder ?? "字段值，如119.786米";
    const keyAriaLabel = config.keyAriaLabel ?? "扩展属性名称";
    const valueAriaLabel = config.valueAriaLabel ?? "扩展属性内容";
    const removeLabel = config.removeLabel ?? "删除此扩展属性";
    const addLabel = config.addLabel ?? "添加属性";
    const multilineValue = config.multilineValue ?? false;
    const values = normalizeCharacterDetails(value);
    const rows = values.length ? values : [{ label: "", value: "" }];
    return `<div class="form-field structured-list-field character-profile-detail-list"><span>${esc(label)}</span><div class="structured-list-rows" data-structured-list-rows data-kind="key-value">${rows.map((item) => `<div class="structured-list-row key-value-list-row"><input name="${esc(keyName)}" value="${esc(item.label)}" placeholder="${esc(keyPlaceholder)}" aria-label="${esc(keyAriaLabel)}">${multilineValue ? `<textarea class="key-value-list-value" name="${esc(valueName)}" rows="1" placeholder="${esc(valuePlaceholder)}" aria-label="${esc(valueAriaLabel)}" data-auto-grow>${esc(item.value)}</textarea>` : `<input name="${esc(valueName)}" value="${esc(item.value)}" placeholder="${esc(valuePlaceholder)}" aria-label="${esc(valueAriaLabel)}">`}<button type="button" data-structured-list-remove aria-label="${esc(removeLabel)}">删除</button></div>`).join("")}</div><button class="item-list-add" type="button" data-structured-list-add>${esc(addLabel)}</button></div>`;
  }
  if (type === "section-list") {
    const values = normalizeCharacterSections(value);
    const rows = values.length ? values : [{ title: "", content: "" }];
    return `<div class="form-field structured-list-field character-profile-section-list"><span>${esc(label)}</span><small>适合记录能力、形态、生态、历史事件、传说和研究版本等长篇内容。</small><div class="structured-list-rows" data-structured-list-rows data-kind="section">${rows.map((item) => `<div class="structured-list-row section-list-row"><input name="sectionTitle" value="${esc(item.title)}" placeholder="章节标题，如能力与特征" aria-label="设定章节标题"><textarea name="sectionContent" placeholder="章节内容，支持 Markdown" aria-label="设定章节内容">${esc(item.content)}</textarea><button type="button" data-structured-list-remove aria-label="删除此设定章节">删除</button></div>`).join("")}</div><button class="item-list-add" type="button" data-structured-list-add>添加设定章节</button></div>`;
  }
  if (type === "select") return `<label>${esc(label)}<select name="${esc(name)}">${options.map(([key, text]) => `<option value="${esc(key)}" ${key === value ? "selected" : ""}>${esc(text)}</option>`).join("")}</select></label>`;
  if (type === "multiselect") {
    const selected = new Set((Array.isArray(value) ? value : []).map(String));
    return `<label>${esc(label)}<select name="${esc(name)}" multiple size="${Math.min(8, Math.max(3, options.length))}">${options.map(([key, text]) => `<option value="${esc(key)}" ${selected.has(String(key)) ? "selected" : ""}>${esc(text)}</option>`).join("")}</select></label>`;
  }
  if (type === "chips") {
    const selected = new Set((Array.isArray(value) ? value : []).map(String));
    return `<div class="form-field chip-field"><span>${esc(label)}</span><div class="chip-picker" role="group" aria-label="${esc(label)}">${options.map(([key, text]) => `<label class="member-chip"><input type="checkbox" name="${esc(name)}" value="${esc(key)}" ${selected.has(String(key)) ? "checked" : ""}><span>${esc(text)}</span></label>`).join("")}</div></div>`;
  }
  if (type === "checkbox") return `<label class="checkbox-field"><input name="${esc(name)}" type="checkbox" ${value ? "checked" : ""}><span>${esc(label)}</span></label>`;
  return `<label>${esc(label)}<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${type === "password" ? 'autocomplete="new-password"' : ""} ${type === "number" ? 'step="any"' : ""}></label>`;
}

function knowledgeSectionTitleFromMarkdown(content, index) {
  return String(content).match(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/mu)?.[1]?.trim() || `设定 ${index + 1}`;
}

function normalizeKnowledgeEditorSections(item) {
  const sections = Array.isArray(item?.settingsSections)
    ? item.settingsSections.map((section, index) => ({
      title: String(section.title ?? "").trim() || knowledgeSectionTitleFromMarkdown(section.contentMarkdown ?? "", index),
      contentMarkdown: String(section.contentMarkdown ?? section.content ?? ""),
      summary: String(section.summary ?? ""),
      sortOrder: Number.isFinite(Number(section.sortOrder)) ? Number(section.sortOrder) : index
    }))
    : [];
  if (sections.length > 0) return sections;
  const legacy = String(item?.settingsMarkdown ?? (Array.isArray(item?.settings) ? item.settings.join("\n\n") : ""));
  return legacy.trim() ? [{ title: knowledgeSectionTitleFromMarkdown(legacy, 0), contentMarkdown: legacy, summary: "", sortOrder: 0 }] : [];
}

function knowledgeSectionPreviewText(section) {
  const content = String(section.contentMarkdown ?? "").replace(/!\[[^\]]*\]\([^)]*\)/gu, "图片").replace(/[`*_>#-]/gu, "").replace(/\s+/gu, " ").trim();
  return content ? `${content.slice(0, 180)}${content.length > 180 ? "…" : ""}` : "暂无正文内容";
}

function renderKnowledgeMarkdownSections() {
  const host = $("#knowledge-markdown-sections");
  if (!host) return;
  const label = knowledgeEditorKind === "race" ? "种族" : "组织";
  const canEdit = !entityEditorReadOnly && canEditModule(knowledgeEditorKind === "race" ? "races" : "organizations");
  const sections = Array.isArray(knowledgeEditorSections) ? knowledgeEditorSections : [];
  const sectionCards = sections.map((section, index) => {
    const content = knowledgeEditorKind === "race"
      ? `<div class="knowledge-markdown-document character-markdown-document message-body">${renderMarkdown(section.contentMarkdown) || '<p class="character-markdown-empty">本设定暂无正文。</p>'}</div>`
      : `<p class="knowledge-section-card-preview">${esc(knowledgeSectionPreviewText(section))}</p>`;
    return `<article class="knowledge-markdown-section" data-knowledge-section-index="${index}"><header><div><span>设定 ${index + 1}</span><h4>${esc(section.title || `未命名设定 ${index + 1}`)}</h4>${section.summary ? `<p>${esc(section.summary)}</p>` : ""}</div><div>${canEdit ? `<button type="button" data-knowledge-section-edit="${index}">编辑</button><button type="button" data-knowledge-section-delete="${index}">删除</button>` : ""}</div></header>${content}</article>`;
  }).join("");
  host.innerHTML = `<div class="knowledge-markdown-list-toolbar"><div><b>${label} Markdown 设定</b><span>将每条设定单独保存为章节，需要编辑时打开大编辑器。</span></div>${canEdit ? '<button type="button" class="ghost-button" data-knowledge-section-create>新建设定</button>' : ""}</div>${sectionCards ? `<div class="knowledge-markdown-list">${sectionCards}</div>` : '<p class="knowledge-markdown-empty">还没有 Markdown 设定，点击“新建设定”开始记录。</p>'}`;
  host.querySelector("[data-knowledge-section-create]")?.addEventListener("click", () => void openKnowledgeSectionEditor());
  host.querySelectorAll("[data-knowledge-section-edit]").forEach((button) => button.addEventListener("click", () => void openKnowledgeSectionEditor(Number(button.dataset.knowledgeSectionEdit))));
  host.querySelectorAll("[data-knowledge-section-delete]").forEach((button) => button.addEventListener("click", async () => {
    const index = Number(button.dataset.knowledgeSectionDelete);
    const section = knowledgeEditorSections[index];
    if (!section || !(await confirmToast(
      `确定删除“${section.title || `设定 ${index + 1}`}”吗？`,
      { title: "删除设定", confirmLabel: "确认删除" }
    ))) return;
    knowledgeEditorSections.splice(index, 1);
    knowledgeEditorSections.forEach((item, sortOrder) => { item.sortOrder = sortOrder; });
    markEntityEditorDirty();
    renderKnowledgeMarkdownSections();
  }));
}

function bindDynamicListControls(container) {
  resizeAutoGrowingTextareas(container);
  container.addEventListener("input", (event) => {
    if (event.target.matches?.("textarea[data-auto-grow]")) resizeAutoGrowingTextarea(event.target);
  });
  container.querySelectorAll("[data-item-list-add]").forEach((button) => button.addEventListener("click", () => {
    const rows = button.previousElementSibling;
    const row = document.createElement("div");
    row.className = "item-list-row";
    const input = document.createElement("input");
    input.name = rows.dataset.name;
    input.setAttribute("aria-label", rows.dataset.label || "列表项目");
    const remove = document.createElement("button");
    remove.type = "button";
    remove.dataset.itemListRemove = "";
    remove.setAttribute("aria-label", "删除此条");
    remove.textContent = "删除";
    row.append(input, remove);
    rows.append(row);
    input.focus();
  }));
  container.querySelectorAll("[data-structured-list-add]").forEach((button) => button.addEventListener("click", () => {
    const rows = button.previousElementSibling;
    const row = rows.lastElementChild.cloneNode(true);
    row.querySelectorAll("input, textarea").forEach((control) => { control.value = ""; });
    rows.append(row);
    resizeAutoGrowingTextareas(row);
    row.querySelector("input").focus();
  }));
  container.onclick = (event) => {
    const remove = event.target.closest("[data-item-list-remove], [data-structured-list-remove]");
    if (!remove) return;
    const row = remove.closest(".item-list-row, .structured-list-row");
    const rows = row.parentElement;
    if (rows.children.length === 1) {
      row.querySelectorAll("input, textarea").forEach((control) => { control.value = ""; });
      resizeAutoGrowingTextareas(row);
    }
    else row.remove();
  };
}

const supportsNativeTextareaContentSizing = typeof CSS !== "undefined" && CSS.supports("field-sizing", "content");

function resizeAutoGrowingTextarea(textarea) {
  if (supportsNativeTextareaContentSizing) {
    textarea.style.removeProperty("height");
    return;
  }
  textarea.style.height = "0px";
  const minimumHeight = Number.parseFloat(getComputedStyle(textarea).minHeight) || 0;
  textarea.style.height = `${Math.max(minimumHeight, textarea.scrollHeight)}px`;
}

const autoGrowingTextareaWidths = new WeakMap();
const autoGrowingTextareaObserver = typeof ResizeObserver === "function"
  ? new ResizeObserver((entries) => {
    entries.forEach(({ target }) => {
      const width = target.getBoundingClientRect().width;
      if (autoGrowingTextareaWidths.get(target) === width) return;
      autoGrowingTextareaWidths.set(target, width);
      resizeAutoGrowingTextarea(target);
    });
  })
  : null;

function resizeAutoGrowingTextareas(container) {
  container?.querySelectorAll("textarea[data-auto-grow]").forEach((textarea) => {
    resizeAutoGrowingTextarea(textarea);
    autoGrowingTextareaObserver?.observe(textarea);
  });
}

let autoGrowingTextareaResizeFrame = null;
window.addEventListener("resize", () => {
  if (autoGrowingTextareaResizeFrame !== null) cancelAnimationFrame(autoGrowingTextareaResizeFrame);
  autoGrowingTextareaResizeFrame = requestAnimationFrame(() => {
    autoGrowingTextareaResizeFrame = null;
    resizeAutoGrowingTextareas(document);
  });
});

function appendRelationshipKeywordChips(editor, values) {
  const input = editor.querySelector("[data-keyword-input]");
  if (!input) return;
  const existing = new Set([...editor.querySelectorAll("[data-keyword-value]")].map((control) => String(control.value).toLocaleLowerCase("zh-CN")));
  const name = editor.dataset.name || "keywords";
  const removeLabel = editor.dataset.removeLabel || "关键词";
  for (const keyword of uniqueRelationshipKeywords(values)) {
    const key = keyword.toLocaleLowerCase("zh-CN");
    if (existing.has(key)) continue;
    existing.add(key);
    input.insertAdjacentHTML("beforebegin", `<span class="keyword-chip" data-keyword-chip><span>${esc(keyword)}</span><input type="hidden" name="${esc(name)}" value="${esc(keyword)}" data-keyword-value><button type="button" data-keyword-chip-remove aria-label="删除${esc(removeLabel)}：${esc(keyword)}">×</button></span>`);
  }
}

function commitRelationshipKeywordInput(editor) {
  const input = editor.querySelector("[data-keyword-input]");
  if (!input) return;
  appendRelationshipKeywordChips(editor, splitRelationshipKeywords(input.value));
  input.value = "";
}

function bindRelationshipKeywordControls(container) {
  container.querySelectorAll("[data-keyword-chips]").forEach((editor) => {
    const input = editor.querySelector("[data-keyword-input]");
    if (!input) return;
    input.addEventListener("keydown", (event) => {
      if (event.isComposing || event.key !== "Enter") return;
      event.preventDefault();
      commitRelationshipKeywordInput(editor);
    });
    input.addEventListener("input", () => {
      const { completed, remainder } = splitRelationshipKeywordInput(input.value);
      if (!completed.length) return;
      appendRelationshipKeywordChips(editor, completed);
      input.value = remainder;
    });
    editor.addEventListener("click", (event) => {
      const remove = event.target.closest("[data-keyword-chip-remove]");
      if (!remove) return;
      remove.closest("[data-keyword-chip]")?.remove();
    });
  });
}

function commitRelationshipKeywordInputs(container) {
  container.querySelectorAll("[data-keyword-chips]").forEach(commitRelationshipKeywordInput);
}

async function openDialog(title, fields, onSubmit, eyebrow = "新增", options = {}) {
  formDialogVditors.forEach(destroyVditorEditor);
  formDialogVditors = [];
  void discardPendingMarkdownAttachments();
  const dialog = $("#form-dialog");
  const form = $("#dynamic-form");
  form.noValidate = false;
  const submit = $("#dialog-submit");
  const submitStatus = $("#dialog-submit-status");
  const submitStatusMessage = $("#dialog-submit-status-message");
  const titleInput = $("#dialog-title-input");
  const submitLabel = options.submitLabel ?? "保存";
  let submitting = false;
  let disabledStates = [];
  $("#dialog-context-actions").replaceChildren();
  $("#dialog-title").textContent = title;
  $("#dialog-title").classList.toggle("hidden", Boolean(options.titleInput));
  titleInput.classList.toggle("hidden", !options.titleInput);
  titleInput.name = options.titleInput ? "title" : "";
  titleInput.value = options.titleInput ? String(options.titleInput.value ?? "") : "";
  titleInput.placeholder = options.titleInput?.placeholder ?? "";
  titleInput.readOnly = Boolean(options.titleInput?.readOnly);
  titleInput.setAttribute("aria-label", options.titleInput?.label ?? "记录标题");
  $("#dialog-eyebrow").textContent = eyebrow;
  $("#dialog-meta").textContent = options.meta ?? "";
  $("#dialog-meta").classList.toggle("hidden", !options.meta);
  $("#dialog-fields").innerHTML = fields;
  submit.textContent = submitLabel;
  submitStatusMessage.textContent = options.pendingMessage ?? "正在提交，请稍候";
  submitStatus.classList.add("hidden");
  form.classList.remove("is-submitting");
  form.removeAttribute("aria-busy");
  $("#dynamic-form .dialog-actions [value='cancel']").classList.toggle("hidden", Boolean(options.hideCancel));
  const dialogActions = form.querySelector(".dialog-actions");
  dialogActions?.querySelector("[data-dialog-danger-action]")?.remove();
  if (options.dangerAction) {
    const dangerButton = document.createElement("button");
    dangerButton.className = "danger-button dialog-danger-action";
    dangerButton.type = "button";
    dangerButton.dataset.dialogDangerAction = "";
    dangerButton.textContent = options.dangerAction.label;
    dangerButton.addEventListener("click", () => { void options.dangerAction.onClick(); });
    dialogActions?.insertBefore(dangerButton, dialogActions.querySelector("[value='cancel']"));
  }
  dialog.classList.toggle("wide-dialog", Boolean(options.wide));
  dialog.classList.toggle("trace-dialog", Boolean(options.trace));
  dialog.classList.toggle("large-dialog", Boolean(options.large));
  dialog.classList.toggle("editor-dialog", Boolean(options.editor));
  bindDynamicListControls($("#dialog-fields"));
  bindRelationshipKeywordControls($("#dialog-fields"));
  if ($("#dialog-fields").querySelector("[data-vditor-editor]") && !(await loadVditorResources())) return;
  formDialogVditors = bindVditorEditors($("#dialog-fields"));
  form.onclick = null;
  form.onkeydown = null;
  dialog.oncancel = (event) => {
    if (submitting) event.preventDefault();
  };
  form.onsubmit = async (event) => {
    if (submitting) {
      event.preventDefault();
      return;
    }
    if (event.submitter?.value === "cancel") {
      void discardPendingMarkdownAttachments();
      return;
    }
    event.preventDefault();
    submitting = true;
    form.setAttribute("aria-busy", "true");
    form.classList.add("is-submitting");
    submitStatus.classList.remove("hidden");
    submit.textContent = options.pendingLabel ?? "处理中…";
    try {
      commitRelationshipKeywordInputs(form);
      const formData = new FormData(form);
      disabledStates = [...form.elements].map((control) => [control, control.disabled]);
      disabledStates.forEach(([control]) => {
        control.disabled = true;
      });
      await onSubmit(formData);
      const markdown = [...form.querySelectorAll("[data-vditor-value]")].map((textarea) => textarea.value).join("\n\n");
      await cleanupPendingMarkdownAttachments(markdown);
      dialog.close();
    } catch (error) {
      const message = error instanceof Error ? error.message : "未知错误";
      toast(`${options.errorPrefix ?? ""}${message}`, "error");
    } finally {
      disabledStates.forEach(([control, wasDisabled]) => {
        control.disabled = wasDisabled;
      });
      disabledStates = [];
      submitting = false;
      form.removeAttribute("aria-busy");
      form.classList.remove("is-submitting");
      submitStatus.classList.add("hidden");
      submit.textContent = submitLabel;
    }
  };
  dialog.showModal();
  $("#dialog-fields").scrollTop = 0;
}

function openWorkDialog() {
  openDialog("创建作品",
    field("method", "创建方式", "select", "blank", [["blank", "从零新建"], ["import", "导入 TXT / DOCX 新建"]]) +
    field("title", "作品名称（导入时可留空）") + field("author", "作者") + field("description", "简介", "textarea"),
    async (form) => {
      const metadata = { title: String(form.get("title") ?? "").trim(), author: form.get("author"), description: form.get("description") };
      if (form.get("method") === "import") {
        state.pendingImportMeta = metadata;
        $("#new-import-file").click();
        return;
      }
      if (!metadata.title) throw new Error("从零新建时必须填写作品名称");
      const work = await api("/api/works", { method: "POST", body: metadata });
      toast("作品已创建");
      await loadWorks(work.id);
    }, "新的世界");
}

