async function deleteWork(work) {
  if (!work || !canManageWork(work)) return toast("仅作品创建者或系统管理员可以删除作品", "error");
  $("#form-dialog").close();
  const deletingCurrentWork = state.work?.id === work.id;
  const unsavedWarning = deletingCurrentWork && state.dirty ? " 当前章节尚有未保存修改，这些本地修改不会进入回收站。" : "";
  if (!await confirmToast(`将作品“${work.title}”移入回收站吗？正文、设定、关联资料和版本历史会完整保留，默认 30 天内可恢复。${unsavedWarning}`, {
    title: "删除作品",
    confirmLabel: "移入回收站"
  })) return openWorkSettingsDialog(work);
  if (deletingCurrentWork) cancelChapterAutoSave();
  try {
    await api(`/api/works/${encodeURIComponent(work.id)}`, {
      method: "DELETE",
      body: { expectedVersionNo: work.versionNo }
    });
    if (deletingCurrentWork) {
      state.dirty = false;
      resetWorkScopedUiCaches();
      state.work = null;
      state.chapter = null;
    }
    await loadWorks();
    deleteToast(`作品“${work.title}”已移入回收站`);
  } catch (error) {
    if (deletingCurrentWork && state.dirty) scheduleChapterAutoSave();
    toast(error.message, "error");
    openWorkSettingsDialog(work);
  }
}

async function openChapterDialog(volumeId = null) {
  if (!state.work) return openWorkDialog();
  if (!canEditProse()) return toast("当前权限只能编辑设定资料，正文为只读", "error");
  if (!state.work.volumes.length) {
    await api(`/api/works/${state.work.id}/volumes`, { method: "POST", body: { title: "正文", kind: "main" } });
    state.work = await api(`/api/works/${state.work.id}`);
    renderTree();
  }
  const selectedVolumeId = state.work.volumes.some((volume) => volume.id === volumeId) ? volumeId : state.work.volumes[0].id;
  openDialog("新建章节", field("title", "章节标题") + field("volumeId", "所属卷", "select", selectedVolumeId, state.work.volumes.map((volume) => [volume.id, volume.title])) + field("chapterType", "章节类型", "select", "正文", chapterTypes.map((value) => [value, value])), async (form) => {
    const chapter = await api(`/api/works/${state.work.id}/chapters`, { method: "POST", body: { title: form.get("title"), volumeId: form.get("volumeId"), chapterType: form.get("chapterType"), content: "" } });
    state.work = await api(`/api/works/${state.work.id}`);
    await selectChapter(chapter.id, { editMode: true });
  });
}

function openVolumeDialog(item) {
  if (!state.work) return openWorkDialog();
  if (!canEditProse()) return toast("当前权限只能编辑设定资料，不能修改分卷", "error");
  const kindOptions = [["main", "正文卷"], ["prequel", "前传"], ["extra", "番外"], ["epilogue", "后记"], ["appendix", "附录"]];
  const nextStoryOrder = Math.max(-1, ...state.work.volumes.map((volume) => Number(volume.storyOrder)).filter(Number.isInteger)) + 1;
  const storyOrder = Number.isInteger(Number(item?.storyOrder)) ? Number(item.storyOrder) : nextStoryOrder;
  const storyOrderField = `<label>剧情顺序<input name="storyOrder" type="number" min="0" max="1000000" step="1" required value="${esc(String(storyOrder))}" aria-describedby="volume-story-order-help"></label><p id="volume-story-order-help" class="form-field-note">仅用于 AI 判断分卷间的剧情先后，不改变左侧目录、阅读或导出顺序；相同值表示并行或暂时无法定序。</p>`;
  const management = item ? `<section class="entity-dialog-management" aria-label="分卷详情操作">
    <div><strong>分卷详情</strong><small>可将当前分卷单独导出为 EPUB；移入回收站时会连同其中章节隐藏，正文、版本和关联资料默认保留 30 天。</small></div>
    <div class="entity-dialog-management-actions"><button class="ghost-button" type="button" data-dialog-volume-export>导出 EPUB</button><button class="danger-button" type="button" data-dialog-volume-delete>移入回收站</button></div>
  </section>` : "";
  openDialog(item ? "分卷详情" : "新建分卷",
    field("title", "分卷名称", "text", item?.title) +
    field("kind", "分卷类型", "select", item?.kind ?? "main", kindOptions) +
    storyOrderField +
    field("description", "分卷简介", "textarea", item?.description) +
    field("keywords", "分卷关键词", "keyword-chips", item?.keywords ?? []) +
    management,
    async (form) => {
      const body = {
        title: form.get("title"),
        kind: form.get("kind"),
        storyOrder: Number(form.get("storyOrder")),
        description: form.get("description"),
        keywords: uniqueRelationshipKeywords(form.getAll("keywords").map(String))
      };
      await api(item ? `/api/volumes/${item.id}` : `/api/works/${state.work.id}/volumes`, { method: item ? "PATCH" : "POST", body });
      state.work = await api(`/api/works/${state.work.id}`);
      renderTree();
      toast(item ? "分卷设置已保存" : "分卷已创建");
    }, "分卷设置");
  $("#dialog-fields").querySelector("[data-dialog-volume-export]")?.addEventListener("click", (event) => {
    void downloadVolumeEpub(item, event.currentTarget);
  });
  $("#dialog-fields").querySelector("[data-dialog-volume-delete]")?.addEventListener("click", () => {
    void deleteVolume(item);
  });
}

async function deleteVolume(item) {
  if (!state.work || !item || !canEditProse()) return toast("当前权限不能删除分卷", "error");
  $("#form-dialog").close();
  if (!await confirmToast(`将分卷“${item.title}”移入回收站吗？其中章节会一并隐藏，正文、版本和关联资料默认保留 30 天。`, {
    title: "删除分卷",
    confirmLabel: "移入回收站"
  })) return openVolumeDialog(item);
  try {
    await api(`/api/volumes/${item.id}`, { method: "DELETE", body: { expectedVersionNo: item.versionNo } });
    state.collapsedVolumeIds.delete(item.id);
    state.work = await api(`/api/works/${state.work.id}`);
    renderTree();
    deleteToast(`分卷“${item.title}”已移入回收站`);
  } catch (error) {
    toast(error.message, "error");
    openVolumeDialog(item);
  }
}

function syncSettingEditorChrome(viewOnly) {
  const item = settingEditorItem;
  $("#setting-editor-eyebrow").textContent = viewOnly ? "阅读设定" : item ? "编辑设定" : "新建设定";
  $("#setting-editor-version").textContent = item ? `v${item.versionNo}` : "新档案";
  $("#setting-editor-submit").textContent = item ? "保存新版本" : "创建设定";
  $("#setting-editor-submit").classList.toggle("hidden", viewOnly);
  const showManagementActions = Boolean(item && !viewOnly);
  $("#setting-editor-confirm").classList.toggle("hidden", !showManagementActions || item?.status !== "pending");
  $("#setting-editor-deprecate").classList.toggle("hidden", !showManagementActions || item?.status !== "pending");
  $("#setting-editor-history").classList.toggle("hidden", !showManagementActions);
  $("#setting-editor-delete").classList.toggle("hidden", !showManagementActions);
}

function settingEditorSnapshot(markdown = null) {
  const content = markdown ?? settingEditorVditor?.getValue() ?? $("#setting-editor-body").value;
  return JSON.stringify({
    title: $("#setting-editor-name").value,
    category: $("#setting-editor-category").value,
    content,
    locked: $("#setting-editor-locked").checked
  });
}

function syncSettingEditorDirty(markdown = null) {
  const currentMarkdown = settingEditorVditor?.getValue() ?? markdown ?? $("#setting-editor-body").value;
  $("#setting-editor-body").value = currentMarkdown;
  entityEditorDirty = settingEditorDirtyTracker.isDirty(settingEditorSnapshot(currentMarkdown));
}

async function openSettingEditor(item = null, { readOnly = false } = {}) {
  if (!(await loadVditorResources())) return;
  entityEditorReadOnly = readOnly;
  destroyVditorEditor(settingEditorVditor);
  settingEditorVditor = null;
  settingEditorItem = item;
  $("#setting-editor-name").value = item?.title ?? "";
  $("#setting-editor-category").value = item?.category ?? "世界规则";
  $("#setting-editor-locked").checked = Boolean(item?.locked);
  $("#setting-editor-body").value = item?.content ?? "";
  const viewOnly = readOnly || !canEditModule("settings");
  $("#setting-editor-form").classList.toggle("is-read-only", viewOnly);
  $("#setting-editor-form").querySelectorAll("input, textarea").forEach((control) => { control.readOnly = viewOnly; });
  $("#setting-editor-form").querySelectorAll("select, input[type='checkbox']").forEach((control) => { control.disabled = viewOnly; });
  const editButton = $("#setting-editor-edit");
  editButton.classList.toggle("hidden", !readOnly || !canEditModule("settings"));
  editButton.onclick = () => { void openSettingEditor(settingEditorItem); };
  bindEntityDetailPinButton($("#setting-editor-pin"), "setting", () => viewOnly ? settingEditorItem : null, (updated) => {
    settingEditorItem = updated;
    state.settings = upsertEntityCollection(state.settings, updated);
  });
  bindEntityDetailFavoriteButton($("#setting-editor-favorite"), "setting", () => viewOnly ? settingEditorItem : null, (updated) => {
    settingEditorItem = updated;
    state.settings = upsertEntityCollection(state.settings, updated);
  });
  const statusButtons = [$("#setting-editor-confirm"), $("#setting-editor-deprecate")];
  syncSettingEditorChrome(viewOnly);
  $("#setting-editor-history").onclick = async () => {
    const currentItem = settingEditorItem;
    if (!currentItem) return;
    if (!(await closeEntityEditor())) return;
    openEntityHistory("setting", currentItem.id, currentItem.title, async () => { await renderSettings(); await loadAiReferences(); });
  };
  $("#setting-editor-delete").onclick = () => {
    const currentItem = settingEditorItem;
    if (!currentItem) return;
    void deleteManagedEntity({
      typeLabel: "设定",
      item: currentItem,
      endpoint: (setting) => `/api/settings/${encodeURIComponent(setting.id)}`,
      refresh: () => closeEntityEditor({ force: true }),
      warning: "这条设定及其版本历史会被删除。"
    });
  };
  statusButtons.forEach((button) => {
    button.onclick = async () => {
      const currentItem = settingEditorItem;
      if (!currentItem) return;
      button.disabled = true;
      const status = button.id === "setting-editor-confirm" ? "confirmed" : "deprecated";
      try {
        await api(`/api/settings/${currentItem.id}`, { method: "PATCH", body: { status, changeNote: status === "confirmed" ? "确认 AI 设定候选" : "弃用 AI 设定候选" } });
        await closeEntityEditor({ force: true });
        await loadAiReferences();
        toast(status === "confirmed" ? "设定候选已确认" : "设定候选已弃用");
      } catch (error) {
        toast(error.message, "error");
      } finally {
        button.disabled = false;
      }
    };
  });
  $("#setting-editor-form").onsubmit = async (event) => {
    event.preventDefault();
    if (readOnly || !canEditModule("settings")) return;
    const submit = $("#setting-editor-submit");
    await runEntityEditorSave({
      busyTarget: event.currentTarget,
      button: submit,
      prepare: async () => {
        const form = new FormData(event.currentTarget);
        const title = String(form.get("title") ?? "").trim();
        if (!title) {
          toast("请填写设定标题", "error");
          $("#setting-editor-name").focus();
          return null;
        }
        const content = String(form.get("content") ?? "");
        if (!content.trim()) {
          toast("请填写设定正文", "error");
          $("#setting-editor-body").focus();
          return null;
        }
        const currentItem = settingEditorItem;
        const changeNote = currentItem ? await inputToast("简要说明这次修改，便于以后查看版本历史。可以留空。", {
          title: "填写版本说明",
          inputLabel: "版本说明",
          placeholder: "例如：补充纪元历法限制",
          confirmLabel: "保存新版本"
        }) : "";
        if (changeNote === null || !(await confirmConcurrentSave())) return null;
        const locked = form.get("locked") === "on";
        return {
          currentItem,
          body: {
            title,
            category: String(form.get("category") ?? "世界规则"),
            content,
            locked,
            status: locked ? "confirmed" : (currentItem?.status ?? "draft"),
            ...(currentItem ? { changeNote } : {})
          }
        };
      },
      save: async ({ currentItem, body }) => {
        const saved = await api(currentItem ? `/api/settings/${currentItem.id}` : `/api/works/${state.work.id}/settings`, { method: currentItem ? "PATCH" : "POST", body });
        await cleanupPendingMarkdownAttachments(body.content);
        settingEditorItem = saved;
        state.settings = upsertEntityCollection(state.settings, saved);
        syncSettingEditorChrome(false);
        settingEditorDirtyTracker.markSaved(settingEditorSnapshot(body.content));
        entityEditorDirty = false;
        replacePageRoute(currentPageRoute());
        return {
          buttonLabel: "保存新版本",
          message: currentItem ? `设定已保存为 v${saved.versionNo}` : `设定已创建为 v${saved.versionNo}`
        };
      }
    });
  };
  showEntityEditorPage("setting", { readOnly });
  settingEditorDirtyTracker.markSaved(settingEditorSnapshot(item?.content ?? ""));
  settingEditorVditor = createVditorEditor($("#setting-editor-markdown"), item?.content ?? "", {
    onInput: (markdown) => syncSettingEditorDirty(markdown),
    readOnly: viewOnly
  });
  (readOnly ? $("#setting-editor-back") : $("#setting-editor-name")).focus();
}

function characterEditorSection(key, title, description, content, headerActions = "") {
  const hasHeaderActions = Boolean(headerActions);
  const header = hasHeaderActions
    ? `<header><div class="character-editor-section-header-copy"><span class="eyebrow">${esc(title)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p></div>${headerActions}</header>`
    : `<header><div><span class="eyebrow">${esc(title)}</span><h3>${esc(title)}</h3></div><p>${esc(description)}</p></header>`;
  return `<section class="character-editor-section${key === "basic" ? "" : " hidden"}${hasHeaderActions ? " has-header-actions" : ""}" data-character-editor-panel="${esc(key)}" role="tabpanel">
    ${header}
    <div class="character-editor-section-fields">${content}</div>
  </section>`;
}

function activateCharacterEditorTab(key) {
  document.querySelectorAll("[data-character-editor-tab]").forEach((button) => {
    const active = button.dataset.characterEditorTab === key;
    button.setAttribute("aria-selected", String(active));
    button.tabIndex = active ? 0 : -1;
  });
  document.querySelectorAll("[data-character-editor-panel]").forEach((panel) => panel.classList.toggle("hidden", panel.dataset.characterEditorPanel !== key));
  resizeAutoGrowingTextareas(document.querySelector(`[data-character-editor-panel="${key}"]`));
  if (
    key === "relationships"
    && characterEditorItem?.id
    && canReadModule("relationships")
    && !characterEditorRelationshipsLoaded
    && !characterEditorRelationshipsLoading
  ) {
    void loadCharacterEditorRelationships(characterEditorItem.id);
  }
  if (
    key === "roleplay-memory"
    && characterEditorItem?.id
    && !roleplayMemoryLoaded
    && !roleplayMemoryLoading
  ) {
    void loadRoleplayMemories({ resetCursor: true }).catch((error) => toast(`角色扮演记忆加载失败：${error.message}`, "error"));
  }
}

function setCharacterHistoryVisible(visible) {
  const panel = $("#character-history-panel");
  const workspace = panel.closest(".character-editor-workspace");
  panel.classList.toggle("hidden", !visible);
  workspace.classList.toggle("history-open", visible);
  $("#character-history-button").setAttribute("aria-expanded", String(visible));
}

function renderCharacterEditorRelationships() {
  const host = $("#character-editor-relationships");
  if (!host) return;
  if (!characterEditorItem?.id) {
    host.innerHTML = '<div class="character-editor-empty-field"><b>人物关系</b><span>保存人物档案后即可添加与其他人物的关系。</span></div>';
    return;
  }
  if (characterEditorRelationshipsLoading) {
    host.innerHTML = '<p class="character-relationship-status">正在读取人物关系……</p>';
    return;
  }
  if (!characterEditorRelationshipsLoaded) {
    host.innerHTML = '<p class="character-relationship-status">打开人物关系分区后载入关系。</p>';
    return;
  }
  const characterId = String(characterEditorItem.id);
  const nameOf = (id) => state.characters.find((character) => character.id === id)?.name ?? "未知角色";
  const rows = characterEditorRelationships.map((relationship) => {
    const isSource = relationship.fromCharacterId === characterId;
    const otherCharacterId = isSource ? relationship.toCharacterId : relationship.fromCharacterId;
    const direction = relationship.directed ? (isSource ? "→" : "←") : "↔";
    const category = relationshipCategoryLabel(relationship.category);
    const relationLabel = [category, relationship.subtype].filter(Boolean).join(" · ") || "未细分";
    const keywords = Array.isArray(relationship.keywords) ? relationship.keywords : [];
    const actions = !entityEditorReadOnly && canEditModule("relationships")
      ? `<div class="character-relationship-actions"><button type="button" data-character-relationship-edit="${esc(relationship.id)}">编辑关系</button><button class="danger-button" type="button" data-character-relationship-delete="${esc(relationship.id)}">删除关系</button></div>`
      : "";
    return `<article class="character-relationship-row">
      <div class="character-relationship-heading"><div><strong>${esc(nameOf(otherCharacterId))}</strong><span>${direction} ${esc(relationLabel)}</span></div>${actions}</div>
      <div class="character-relationship-keywords"><small>关系关键词</small><div>${keywords.map((keyword) => `<span class="pill relationship-keyword">${esc(keyword)}</span>`).join("") || '<span class="character-relationship-empty-keywords">未填写关键词</span>'}</div></div>
    </article>`;
  }).join("");
  host.innerHTML = `<div class="character-relationship-toolbar"><p>与 ${esc(characterEditorItem.name)} 有关的其他人物及关系关键词。</p>${!entityEditorReadOnly && canEditModule("relationships") ? '<button type="button" class="ghost-button" data-character-relationship-create>新建关系</button>' : ""}</div>${rows || '<p class="character-relationship-status">暂未记录与其他人物的关系。</p>'}`;
  host.querySelectorAll("[data-character-relationship-edit]").forEach((button) => button.addEventListener("click", () => {
    const relationship = characterEditorRelationships.find((item) => item.id === button.dataset.characterRelationshipEdit);
    if (relationship) void openRelationshipDialog(relationship, { characterId });
  }));
  host.querySelectorAll("[data-character-relationship-delete]").forEach((button) => button.addEventListener("click", () => {
    const relationship = characterEditorRelationships.find((item) => item.id === button.dataset.characterRelationshipDelete);
    if (!relationship) return;
    button.disabled = true;
    void deleteRelationshipRecord(relationship, characterId).finally(() => {
      if (button.isConnected) button.disabled = false;
    });
  }));
  host.querySelector("[data-character-relationship-create]")?.addEventListener("click", () => void openRelationshipDialog(null, { characterId }));
}

async function loadCharacterEditorRelationships(characterId, { refresh = false } = {}) {
  const workId = state.work?.id;
  if (!workId || characterEditorItem?.id !== characterId) return;
  if (!refresh && (characterEditorRelationshipsLoaded || characterEditorRelationshipsLoading)) return;
  characterEditorRelationshipsLoading = true;
  characterEditorRelationshipsLoaded = false;
  renderCharacterEditorRelationships();
  let loaded = false;
  try {
    const [characters, relationships] = await Promise.all([
      moduleApiAllPages("characters", `/api/works/${workId}/characters`),
      moduleApiAllPages("relationships", `/api/works/${workId}/relationships`)
    ]);
    if (state.work?.id !== workId || characterEditorItem?.id !== characterId) return;
    state.characters = characters;
    characterEditorRelationships = sortCharacterRelationships(relationships.filter((relationship) => relationship.fromCharacterId === characterId || relationship.toCharacterId === characterId), characterId);
    characterEditorRelationshipsLoaded = true;
    loaded = true;
  } catch (error) {
    if (state.work?.id === workId && characterEditorItem?.id === characterId) {
      $("#character-editor-relationships").innerHTML = `<p class="character-relationship-status">关系载入失败：${esc(error.message)}</p>`;
    }
  } finally {
    if (state.work?.id === workId && characterEditorItem?.id === characterId) {
      characterEditorRelationshipsLoading = false;
      if (loaded) renderCharacterEditorRelationships();
    }
  }
}

async function refreshRelationshipSurfaces(characterId = null) {
  const tasks = [];
  if (state.module === "relationships") tasks.push(renderRelationships());
  if (characterId && entityEditorType === "character" && !$("#entity-editor-view").classList.contains("hidden") && characterEditorItem?.id === characterId) {
    tasks.push(loadCharacterEditorRelationships(characterId, { refresh: true }));
  }
  await Promise.all(tasks);
}

async function deleteRelationshipRecord(item, characterId = null) {
  const relationshipName = `${state.characters.find((character) => character.id === item.fromCharacterId)?.name ?? "未知角色"} / ${state.characters.find((character) => character.id === item.toCharacterId)?.name ?? "未知角色"}`;
  if (!await confirmToast(`确认删除人物关系“${relationshipName}”吗？`, { title: "删除人物关系", confirmLabel: "继续删除" })) return false;
  if (!await confirmToast(`删除人物关系“${relationshipName}”后无法恢复。`, { title: "删除操作需要再次确认", confirmLabel: "确认删除" })) return false;
  try {
    await api(`/api/relationships/${item.id}`, { method: "DELETE", body: { expectedVersionNo: item.versionNo } });
    await Promise.all([refreshRelationshipSurfaces(characterId), loadAiReferences()]);
    deleteToast(`已删除人物关系“${relationshipName}”`);
    return true;
  } catch (error) {
    toast(error.message, "error");
    return false;
  }
}

