document.addEventListener("keydown", (event) => {
  const header = event.target.closest?.("[data-markdown-table-header]");
  if (header && (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10"))) {
    event.preventDefault();
    openMarkdownTableMenu(header, 0, 0);
    return;
  }
  if (event.key === "Escape") {
    if (!$("#ai-semantic-search-panel").classList.contains("hidden")) {
      setAiSemanticSearchVisible(false);
      $("#ai-semantic-search-toggle").focus();
      return;
    }
    if (!$("#ai-model-popover").classList.contains("hidden")) {
      setAiModelPickerVisible(false);
      return;
    }
    if (!$("#chapter-search-panel").classList.contains("hidden")) {
      closeChapterSearchPanel();
      return;
    }
    if (!$("#ai-history-action-menu").classList.contains("hidden")) return;
    if (!$("#ai-conversation-switcher-menu").classList.contains("hidden")) {
      setAiConversationSwitcherVisible(false);
      $("#ai-conversation-switcher").focus();
      return;
    }
    if (aiConversationWorkspaceOpen) {
      setAiConversationWorkspaceVisible(false);
      return;
    }
    closeChapterTypeMenu();
    closeLineCitationMenu();
    closeMarkdownTableMenu(true);
    closeManuscriptExportMenu();
    closeAiHistoryActionMenu(true);
    hideAiMentionMenu();
    setAiContextDistributionVisible(false);
  }
});
